CREATE TABLE provider_memberships (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    provider_id uuid NOT NULL REFERENCES providers(id) ON DELETE RESTRICT,
    user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    role_code text NOT NULL REFERENCES provider_roles(code) ON DELETE RESTRICT,
    status text NOT NULL DEFAULT 'active' CHECK (status IN ('invited','active','suspended','removed')),
    joined_at timestamptz NOT NULL DEFAULT now(),
    ended_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE(provider_id,user_id), UNIQUE(id,provider_id),
    CHECK ((status='removed')=(ended_at IS NOT NULL))
);
CREATE INDEX provider_memberships_user_idx ON provider_memberships(user_id,provider_id,status);
CREATE INDEX provider_memberships_active_role_idx ON provider_memberships(provider_id,role_code) WHERE status='active';

CREATE TABLE provider_member_permission_overrides (
    membership_id uuid NOT NULL,
    provider_id uuid NOT NULL,
    permission_code text NOT NULL REFERENCES provider_permissions(code) ON DELETE RESTRICT,
    allowed boolean NOT NULL,
    created_by_user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY(membership_id,permission_code),
    FOREIGN KEY(membership_id,provider_id) REFERENCES provider_memberships(id,provider_id) ON DELETE RESTRICT
);
CREATE INDEX provider_member_permission_overrides_provider_idx ON provider_member_permission_overrides(provider_id);
CREATE INDEX provider_member_permission_overrides_creator_idx ON provider_member_permission_overrides(provider_id,created_by_user_id);
CREATE INDEX provider_member_permission_overrides_creator_user_idx ON provider_member_permission_overrides(created_by_user_id);

CREATE VIEW provider_effective_permissions AS
SELECT m.provider_id,m.user_id,m.id AS membership_id,p.code AS permission_code
FROM provider_memberships m
JOIN providers o ON o.id=m.provider_id AND o.status NOT IN ('suspended','archived')
JOIN users u ON u.id=m.user_id AND u.status='active'
CROSS JOIN provider_permissions p
LEFT JOIN provider_role_permissions r ON r.role_code=m.role_code AND r.permission_code=p.code
LEFT JOIN provider_member_permission_overrides x ON x.membership_id=m.id AND x.permission_code=p.code
WHERE m.status='active' AND (m.role_code='owner' OR COALESCE(x.allowed,r.permission_code IS NOT NULL));

CREATE FUNCTION provider_has_permission(p_provider_id uuid,p_user_id uuid,p_permission_code text)
RETURNS boolean LANGUAGE sql STABLE SET search_path=travora,pg_temp AS $$
 SELECT EXISTS(SELECT 1 FROM providers WHERE id=p_provider_id)
    AND EXISTS(SELECT 1 FROM provider_permissions WHERE code=p_permission_code)
    AND (EXISTS(SELECT 1 FROM users WHERE id=p_user_id AND role='admin' AND status='active')
     OR EXISTS(SELECT 1 FROM provider_effective_permissions
               WHERE provider_id=p_provider_id AND user_id=p_user_id AND permission_code=p_permission_code));
$$;
COMMENT ON FUNCTION provider_has_permission(uuid,uuid,text) IS 'Authorization helper for an API-authenticated user. Active global admins have administrative access. This does not authenticate its supplied user id or install RLS.';

CREATE TABLE provider_branches (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    provider_id uuid NOT NULL REFERENCES providers(id) ON DELETE RESTRICT,
    code text NOT NULL CHECK (code ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
    name_ar text NOT NULL CHECK (length(btrim(name_ar))>0),
    name_en text NOT NULL CHECK (length(btrim(name_en))>0),
    destination_id uuid REFERENCES destinations(id) ON DELETE RESTRICT,
    country_code char(2) REFERENCES countries(code) ON DELETE RESTRICT,
    address_ar text,
    address_en text,
    timezone text NOT NULL DEFAULT 'Africa/Cairo',
    latitude numeric(9,6), longitude numeric(9,6),
    opening_hours jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(opening_hours)='object'),
    status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','temporarily_closed','archived')),
    created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE(id,provider_id), UNIQUE(provider_id,code),
    CHECK ((latitude IS NULL)=(longitude IS NULL)),
    CHECK (latitude IS NULL OR latitude BETWEEN -90 AND 90),
    CHECK (longitude IS NULL OR longitude BETWEEN -180 AND 180)
);
CREATE INDEX provider_branches_destination_idx ON provider_branches(destination_id);
CREATE INDEX provider_branches_country_idx ON provider_branches(country_code);

CREATE TABLE provider_invitations (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    provider_id uuid NOT NULL REFERENCES providers(id) ON DELETE RESTRICT,
    email text NOT NULL CHECK (email=lower(btrim(email)) AND email ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'),
    role_code text NOT NULL REFERENCES provider_roles(code) ON DELETE RESTRICT CHECK (role_code<>'owner'),
    token_hash bytea NOT NULL UNIQUE CHECK (octet_length(token_hash)=32),
    invited_by_user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    accepted_by_user_id uuid REFERENCES users(id) ON DELETE RESTRICT,
    status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','accepted','expired','revoked')),
    expires_at timestamptz NOT NULL,
    accepted_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),
    CHECK (expires_at>created_at),
    CHECK ((status='accepted')=(accepted_at IS NOT NULL AND accepted_by_user_id IS NOT NULL)),
    CHECK (status='accepted' OR (accepted_at IS NULL AND accepted_by_user_id IS NULL))
);
CREATE UNIQUE INDEX provider_invitations_pending_email_idx ON provider_invitations(provider_id,email) WHERE status='pending';
CREATE INDEX provider_invitations_inviter_idx ON provider_invitations(provider_id,invited_by_user_id);
CREATE INDEX provider_invitations_inviter_user_idx ON provider_invitations(invited_by_user_id);
CREATE INDEX provider_invitations_accepted_user_idx ON provider_invitations(accepted_by_user_id);
CREATE INDEX provider_invitations_expiry_idx ON provider_invitations(expires_at) WHERE status='pending';
COMMENT ON COLUMN provider_invitations.token_hash IS 'SHA-256 digest of a cryptographically random invitation token. Never store or log the raw token. Expired pending invitations must be marked expired by the worker before replacement.';

CREATE TABLE provider_applications (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    provider_id uuid NOT NULL REFERENCES providers(id) ON DELETE RESTRICT,
    applicant_user_id uuid NOT NULL,
    legal_name text NOT NULL CHECK (length(btrim(legal_name)) BETWEEN 1 AND 240),
    country_code char(2) NOT NULL REFERENCES countries(code) ON DELETE RESTRICT,
    registration_reference text,
    status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','submitted','in_review','approved','rejected','withdrawn')),
    submitted_at timestamptz,
    reviewed_by_user_id uuid REFERENCES users(id) ON DELETE RESTRICT,
    reviewed_at timestamptz,
    decision_notes text,
    created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE(id,provider_id),
    FOREIGN KEY(provider_id,applicant_user_id) REFERENCES provider_memberships(provider_id,user_id) ON DELETE RESTRICT,
    CHECK (status NOT IN ('approved','rejected') OR (reviewed_by_user_id IS NOT NULL AND reviewed_at IS NOT NULL)),
    CHECK (status<>'rejected' OR length(btrim(COALESCE(decision_notes,'')))>0)
);
CREATE UNIQUE INDEX provider_applications_open_idx ON provider_applications(provider_id) WHERE status IN ('draft','submitted','in_review');
CREATE INDEX provider_applications_applicant_idx ON provider_applications(provider_id,applicant_user_id);
CREATE INDEX provider_applications_reviewer_idx ON provider_applications(reviewed_by_user_id);

CREATE TABLE provider_application_documents (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    application_id uuid NOT NULL,provider_id uuid NOT NULL,
    asset_id uuid NOT NULL,uploaded_by_user_id uuid NOT NULL,
    document_kind text NOT NULL CHECK (document_kind IN ('registration','license','identity','insurance','other')),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE(application_id,asset_id),
    FOREIGN KEY(application_id,provider_id) REFERENCES provider_applications(id,provider_id) ON DELETE RESTRICT,
    FOREIGN KEY(provider_id,uploaded_by_user_id) REFERENCES provider_memberships(provider_id,user_id) ON DELETE RESTRICT,
    FOREIGN KEY(asset_id,uploaded_by_user_id) REFERENCES media_assets(id,owner_user_id) ON DELETE RESTRICT
);
CREATE INDEX provider_application_documents_provider_idx ON provider_application_documents(provider_id);
CREATE INDEX provider_application_documents_asset_owner_idx ON provider_application_documents(asset_id,uploaded_by_user_id);
CREATE INDEX provider_application_documents_uploader_idx ON provider_application_documents(provider_id,uploaded_by_user_id);

CREATE TABLE provider_license_types (
    code text PRIMARY KEY,
    name_ar text NOT NULL,name_en text NOT NULL,
    category_code text REFERENCES provider_categories(code) ON DELETE RESTRICT
);
INSERT INTO provider_license_types(code,name_ar,name_en,category_code) VALUES
 ('business_registration','السجل التجاري','Business registration',NULL),
 ('tourism_license','ترخيص سياحي','Tourism license','guide'),
 ('hotel_license','ترخيص إقامة','Accommodation license','hotel'),
 ('food_permit','ترخيص مطعم','Food permit','restaurant'),
 ('transport_license','ترخيص نقل','Transport license','transport'),
 ('delivery_license','ترخيص توصيل','Delivery license','delivery'),
 ('public_liability','تأمين المسؤولية','Public liability insurance',NULL);
CREATE INDEX provider_license_types_category_idx ON provider_license_types(category_code);

CREATE TABLE provider_licenses (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    provider_id uuid NOT NULL REFERENCES providers(id) ON DELETE RESTRICT,
    license_type_code text NOT NULL REFERENCES provider_license_types(code) ON DELETE RESTRICT,
    license_reference text NOT NULL CHECK (length(btrim(license_reference)) BETWEEN 1 AND 160),
    country_code char(2) NOT NULL REFERENCES countries(code) ON DELETE RESTRICT,
    issuing_authority text,
    asset_id uuid NOT NULL,uploaded_by_user_id uuid NOT NULL,
    issued_on date NOT NULL,expires_on date,
    status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','verified','rejected','expired','revoked')),
    reviewed_by_user_id uuid REFERENCES users(id) ON DELETE RESTRICT,
    reviewed_at timestamptz,decision_notes text,
    created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE(provider_id,license_type_code,license_reference,issued_on),
    FOREIGN KEY(provider_id,uploaded_by_user_id) REFERENCES provider_memberships(provider_id,user_id) ON DELETE RESTRICT,
    FOREIGN KEY(asset_id,uploaded_by_user_id) REFERENCES media_assets(id,owner_user_id) ON DELETE RESTRICT,
    CHECK (expires_on IS NULL OR expires_on>=issued_on),
    CHECK (status NOT IN ('verified','rejected') OR (reviewed_by_user_id IS NOT NULL AND reviewed_at IS NOT NULL))
);
CREATE INDEX provider_licenses_type_idx ON provider_licenses(license_type_code);
CREATE INDEX provider_licenses_country_idx ON provider_licenses(country_code);
CREATE INDEX provider_licenses_asset_owner_idx ON provider_licenses(asset_id,uploaded_by_user_id);
CREATE INDEX provider_licenses_uploader_idx ON provider_licenses(provider_id,uploaded_by_user_id);
CREATE INDEX provider_licenses_reviewer_idx ON provider_licenses(reviewed_by_user_id);
CREATE INDEX provider_licenses_expiry_idx ON provider_licenses(expires_on) WHERE status='verified';

CREATE TABLE driver_profiles (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id uuid NOT NULL UNIQUE REFERENCES users(id) ON DELETE RESTRICT,
    display_name text,
    license_media_id uuid,
    license_expires_on date,
    status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','active','suspended')),
    availability text NOT NULL DEFAULT 'offline' CHECK (availability IN ('offline','available','busy')),
    verified_by_user_id uuid REFERENCES users(id) ON DELETE RESTRICT,
    verified_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY(license_media_id,user_id) REFERENCES media_assets(id,owner_user_id) ON DELETE RESTRICT,
    CHECK (status<>'active' OR (verified_by_user_id IS NOT NULL AND verified_at IS NOT NULL)),
    CHECK (status='active' OR availability='offline')
);
CREATE INDEX driver_profiles_license_owner_idx ON driver_profiles(license_media_id,user_id);
CREATE INDEX driver_profiles_verifier_idx ON driver_profiles(verified_by_user_id);
CREATE INDEX driver_profiles_available_idx ON driver_profiles(availability) WHERE status='active';

CREATE TABLE provider_vehicles (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    provider_id uuid NOT NULL REFERENCES providers(id) ON DELETE RESTRICT,
    branch_id uuid,
    code text NOT NULL CHECK (length(btrim(code)) BETWEEN 1 AND 80),
    vehicle_type text NOT NULL CHECK (vehicle_type IN ('car','van','motorcycle','bicycle')),
    seats smallint NOT NULL CHECK (seats>0),
    luggage_capacity smallint NOT NULL DEFAULT 0 CHECK (luggage_capacity>=0),
    make text,model text,plate_reference text,
    status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','maintenance','retired')),
    created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE(id,provider_id),UNIQUE(provider_id,code),
    FOREIGN KEY(branch_id,provider_id) REFERENCES provider_branches(id,provider_id) ON DELETE RESTRICT
);
CREATE INDEX provider_vehicles_branch_idx ON provider_vehicles(branch_id,provider_id);

CREATE TABLE provider_payout_destinations (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    provider_id uuid NOT NULL REFERENCES providers(id) ON DELETE RESTRICT,
    currency char(3) NOT NULL REFERENCES currencies(code) ON DELETE RESTRICT,
    processor text NOT NULL CHECK (length(btrim(processor)) BETWEEN 1 AND 80),
    processor_account_ref text NOT NULL CHECK (length(btrim(processor_account_ref)) BETWEEN 1 AND 255),
    display_label text,
    account_last4 text CHECK (account_last4 IS NULL OR account_last4 ~ '^[0-9]{4}$'),
    created_by_user_id uuid REFERENCES users(id) ON DELETE RESTRICT,
    status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','active','disabled')),
    verified_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE(id,provider_id,currency),UNIQUE(processor,processor_account_ref,currency),
    CHECK (status<>'active' OR verified_at IS NOT NULL)
);
CREATE INDEX provider_payout_destinations_creator_idx ON provider_payout_destinations(provider_id,created_by_user_id);
CREATE INDEX provider_payout_destinations_creator_user_idx ON provider_payout_destinations(created_by_user_id);
COMMENT ON TABLE provider_payout_destinations IS 'Tokenized payment-processor destination metadata only. No IBAN, account secret, bank password, PAN, CVV or processor API key. Actual processor onboarding, verification and payout execution require backend integrations.';

CREATE TABLE provider_audit_events (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    provider_id uuid NOT NULL REFERENCES providers(id) ON DELETE RESTRICT,
    actor_user_id uuid REFERENCES users(id) ON DELETE RESTRICT,
    action text NOT NULL CHECK (length(btrim(action)) BETWEEN 1 AND 100),
    entity_type text NOT NULL CHECK (length(btrim(entity_type)) BETWEEN 1 AND 100),
    entity_id uuid,
    occurred_at timestamptz NOT NULL DEFAULT now(),
    summary text
);
CREATE INDEX provider_audit_events_provider_time_idx ON provider_audit_events(provider_id,occurred_at DESC);
CREATE INDEX provider_audit_events_actor_idx ON provider_audit_events(actor_user_id);

CREATE VIEW provider_current_verification AS
SELECT p.id AS provider_id,
 EXISTS(SELECT 1 FROM provider_applications a WHERE a.provider_id=p.id AND a.status='approved') AS application_approved,
 (SELECT count(*) FROM provider_licenses l WHERE l.provider_id=p.id AND l.status='verified'
  AND l.issued_on<=current_date AND (l.expires_on IS NULL OR l.expires_on>=current_date)) AS valid_license_count
FROM providers p;

CREATE FUNCTION business_guard_provider() RETURNS trigger LANGUAGE plpgsql SET search_path=travora,pg_temp AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Archive a provider; retain its organization history' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' THEN
  IF ROW(NEW.id,NEW.code) IS DISTINCT FROM ROW(OLD.id,OLD.code) THEN
   RAISE EXCEPTION 'Provider identity and code are immutable' USING ERRCODE='23514';
  END IF;
  IF OLD.owner_user_id IS NOT NULL AND NEW.owner_user_id IS DISTINCT FROM OLD.owner_user_id THEN
   RAISE EXCEPTION 'Claimed provider ownership is immutable; use a reviewed ownership-transfer migration' USING ERRCODE='23514';
  END IF;
 END IF;
 IF NEW.owner_user_id IS NOT NULL AND (TG_OP='INSERT' OR NEW.owner_user_id IS DISTINCT FROM OLD.owner_user_id) THEN
  IF NOT EXISTS(SELECT 1 FROM users WHERE id=NEW.owner_user_id AND status='active') THEN
   RAISE EXCEPTION 'Provider owner must be an active user' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NEW;
END; $$;
CREATE TRIGGER business_provider_identity BEFORE INSERT OR UPDATE OR DELETE ON providers FOR EACH ROW EXECUTE FUNCTION business_guard_provider();

CREATE FUNCTION business_guard_membership() RETURNS trigger LANGUAGE plpgsql SET search_path=travora,pg_temp AS $$
DECLARE own uuid;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Retain membership history; set status removed' USING ERRCODE='23514'; END IF;
 SELECT owner_user_id INTO own FROM providers WHERE id=NEW.provider_id FOR UPDATE;
 IF TG_OP='UPDATE' THEN
  IF ROW(NEW.id,NEW.provider_id,NEW.user_id,NEW.created_at) IS DISTINCT FROM ROW(OLD.id,OLD.provider_id,OLD.user_id,OLD.created_at) THEN
   RAISE EXCEPTION 'Membership identity is immutable' USING ERRCODE='23514';
  END IF;
  IF OLD.status='removed' AND NEW.status<>'removed' THEN RAISE EXCEPTION 'Removed memberships are terminal' USING ERRCODE='23514'; END IF;
  IF OLD.role_code='owner' AND (NEW.role_code<>'owner' OR NEW.status<>'active') THEN
   RAISE EXCEPTION 'The provider owner membership must remain active and retain its owner role' USING ERRCODE='23514';
  END IF;
 END IF;
 IF NEW.role_code='owner' AND (NEW.user_id IS DISTINCT FROM own OR NEW.status<>'active') THEN
  RAISE EXCEPTION 'Only the registered provider owner may hold an active owner membership' USING ERRCODE='23514';
 END IF;
 IF NEW.status='removed' THEN NEW.ended_at:=COALESCE(NEW.ended_at,now()); ELSE NEW.ended_at:=NULL; END IF;
 RETURN NEW;
END; $$;
CREATE TRIGGER business_membership_guard BEFORE INSERT OR UPDATE OR DELETE ON provider_memberships FOR EACH ROW EXECUTE FUNCTION business_guard_membership();

CREATE FUNCTION business_bootstrap_owner() RETURNS trigger LANGUAGE plpgsql SET search_path=travora,pg_temp AS $$
BEGIN
 IF NEW.owner_user_id IS NOT NULL THEN
  INSERT INTO provider_memberships(provider_id,user_id,role_code,status)
  VALUES(NEW.id,NEW.owner_user_id,'owner','active')
  ON CONFLICT(provider_id,user_id) DO UPDATE SET role_code='owner',status='active',ended_at=NULL;
 END IF;
 RETURN NEW;
END; $$;
CREATE TRIGGER business_provider_owner_insert AFTER INSERT ON providers FOR EACH ROW EXECUTE FUNCTION business_bootstrap_owner();
CREATE TRIGGER business_provider_owner_claim AFTER UPDATE OF owner_user_id ON providers FOR EACH ROW
WHEN(NEW.owner_user_id IS DISTINCT FROM OLD.owner_user_id) EXECUTE FUNCTION business_bootstrap_owner();
-- Existing imported owners receive the same scoped membership before writes.
INSERT INTO provider_memberships(provider_id,user_id,role_code,status)
SELECT id,owner_user_id,'owner','active' FROM providers WHERE owner_user_id IS NOT NULL;

CREATE FUNCTION business_guard_permission_override() RETURNS trigger LANGUAGE plpgsql SET search_path=travora,pg_temp AS $$
DECLARE m provider_memberships;
BEGIN
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 SELECT * INTO m FROM provider_memberships WHERE id=NEW.membership_id;
 IF m.role_code='owner' AND NOT NEW.allowed THEN RAISE EXCEPTION 'Owner permissions cannot be revoked by an override' USING ERRCODE='23514'; END IF;
 IF NOT provider_has_permission(NEW.provider_id,NEW.created_by_user_id,'members.manage') THEN
  RAISE EXCEPTION 'Declared actor lacks scoped member-management permission' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END; $$;
CREATE TRIGGER business_permission_override_guard BEFORE INSERT OR UPDATE OR DELETE ON provider_member_permission_overrides FOR EACH ROW EXECUTE FUNCTION business_guard_permission_override();

CREATE FUNCTION business_guard_invitation() RETURNS trigger LANGUAGE plpgsql SET search_path=travora,pg_temp AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Retain invitation history; revoke the invitation' USING ERRCODE='23514'; END IF;
 IF TG_OP='INSERT' AND NEW.status<>'pending' THEN RAISE EXCEPTION 'An invitation starts pending' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' THEN
  IF ROW(NEW.id,NEW.provider_id,NEW.email,NEW.role_code,NEW.token_hash,NEW.invited_by_user_id,NEW.expires_at,NEW.created_at)
   IS DISTINCT FROM ROW(OLD.id,OLD.provider_id,OLD.email,OLD.role_code,OLD.token_hash,OLD.invited_by_user_id,OLD.expires_at,OLD.created_at) THEN
   RAISE EXCEPTION 'Invitation identity, recipient, role and expiry are immutable' USING ERRCODE='23514';
  END IF;
  IF OLD.status<>'pending' AND ROW(NEW.status,NEW.accepted_by_user_id,NEW.accepted_at) IS DISTINCT FROM ROW(OLD.status,OLD.accepted_by_user_id,OLD.accepted_at) THEN
   RAISE EXCEPTION 'Terminal invitations are immutable' USING ERRCODE='23514';
  END IF;
 END IF;
 IF TG_OP='INSERT' AND NOT provider_has_permission(NEW.provider_id,NEW.invited_by_user_id,'members.manage') THEN
  RAISE EXCEPTION 'Declared inviter lacks scoped member-management permission' USING ERRCODE='23514';
 END IF;
 IF NEW.status='accepted' AND (TG_OP='INSERT' OR OLD.status<>'accepted') THEN
  IF NEW.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'Invitation has expired' USING ERRCODE='23514'; END IF;
  IF NOT EXISTS(SELECT 1 FROM users WHERE id=NEW.accepted_by_user_id AND email=NEW.email AND email_verified_at IS NOT NULL AND status='active') THEN
   RAISE EXCEPTION 'Invitation acceptance requires the matching verified active account' USING ERRCODE='23514';
  END IF;
  NEW.accepted_at:=COALESCE(NEW.accepted_at,clock_timestamp());
 END IF;
 RETURN NEW;
END; $$;
CREATE TRIGGER business_invitation_guard BEFORE INSERT OR UPDATE OR DELETE ON provider_invitations FOR EACH ROW EXECUTE FUNCTION business_guard_invitation();

CREATE FUNCTION accept_provider_invitation(p_invitation_id uuid,p_user_id uuid,p_token_hash bytea)
RETURNS uuid LANGUAGE plpgsql SET search_path=travora,pg_temp AS $$
DECLARE inv provider_invitations; org uuid; mid uuid;
BEGIN
 SELECT provider_id INTO org FROM provider_invitations WHERE id=p_invitation_id;
 PERFORM 1 FROM providers WHERE id=org FOR UPDATE;
 SELECT * INTO inv FROM provider_invitations WHERE id=p_invitation_id FOR UPDATE;
 IF NOT FOUND OR inv.status<>'pending' OR inv.token_hash IS DISTINCT FROM p_token_hash OR inv.expires_at<=clock_timestamp() THEN
  RAISE EXCEPTION 'Invitation token is invalid, used, revoked or expired' USING ERRCODE='23514';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM users WHERE id=p_user_id AND email=inv.email AND email_verified_at IS NOT NULL AND status='active') THEN
  RAISE EXCEPTION 'Invitation is addressed to another account or email is not verified' USING ERRCODE='23514';
 END IF;
 IF EXISTS(SELECT 1 FROM provider_memberships WHERE provider_id=org AND user_id=p_user_id AND status='removed') THEN
  RAISE EXCEPTION 'Removed memberships require a reviewed reinstatement workflow' USING ERRCODE='23514';
 END IF;
 INSERT INTO provider_memberships(provider_id,user_id,role_code,status)
 VALUES(org,p_user_id,inv.role_code,'active')
 ON CONFLICT(provider_id,user_id) DO UPDATE SET role_code=EXCLUDED.role_code,status='active',ended_at=NULL
 RETURNING id INTO mid;
 UPDATE provider_invitations SET status='accepted',accepted_by_user_id=p_user_id,accepted_at=clock_timestamp() WHERE id=p_invitation_id;
 RETURN mid;
END; $$;
COMMENT ON FUNCTION accept_provider_invitation(uuid,uuid,bytea) IS 'Atomic invitation consumption and scoped membership activation. API authenticates user and hashes the submitted random token before calling. Failed calls roll back; expiry marking is a separate worker task.';

CREATE FUNCTION business_guard_application() RETURNS trigger LANGUAGE plpgsql SET search_path=travora,pg_temp AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Retain provider application history' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' THEN
  IF ROW(NEW.id,NEW.provider_id,NEW.applicant_user_id,NEW.created_at) IS DISTINCT FROM ROW(OLD.id,OLD.provider_id,OLD.applicant_user_id,OLD.created_at) THEN
   RAISE EXCEPTION 'Application identity is immutable' USING ERRCODE='23514';
  END IF;
  IF OLD.status IN ('approved','rejected','withdrawn') AND (to_jsonb(NEW)-'updated_at') IS DISTINCT FROM (to_jsonb(OLD)-'updated_at') THEN
   RAISE EXCEPTION 'Decided applications are immutable; submit a new application' USING ERRCODE='23514';
  END IF;
  IF NEW.status<>OLD.status AND NOT (
   (OLD.status='draft' AND NEW.status IN ('submitted','withdrawn')) OR
   (OLD.status='submitted' AND NEW.status IN ('in_review','approved','rejected','withdrawn')) OR
   (OLD.status='in_review' AND NEW.status IN ('approved','rejected','withdrawn'))
  ) THEN RAISE EXCEPTION 'Invalid application status transition' USING ERRCODE='23514'; END IF;
 END IF;
 IF NEW.status IN ('submitted','in_review','approved','rejected') THEN NEW.submitted_at:=COALESCE(NEW.submitted_at,now()); END IF;
 IF NEW.status IN ('approved','rejected') AND (TG_OP='INSERT' OR NEW.status IS DISTINCT FROM OLD.status) THEN
  IF NOT EXISTS(SELECT 1 FROM users WHERE id=NEW.reviewed_by_user_id AND role='admin' AND status='active') THEN
   RAISE EXCEPTION 'A provider application decision requires an active admin reviewer' USING ERRCODE='23514';
  END IF;
  NEW.reviewed_at:=COALESCE(NEW.reviewed_at,now());
 END IF;
 RETURN NEW;
END; $$;
CREATE TRIGGER business_application_guard BEFORE INSERT OR UPDATE OR DELETE ON provider_applications FOR EACH ROW EXECUTE FUNCTION business_guard_application();

CREATE FUNCTION business_guard_private_evidence() RETURNS trigger LANGUAGE plpgsql SET search_path=travora,pg_temp AS $$
DECLARE asset media_assets;
BEGIN
 SELECT * INTO asset FROM media_assets WHERE id=NEW.asset_id;
 IF NOT FOUND OR asset.visibility<>'private' OR asset.status<>'ready'
    OR asset.byte_size<=0 OR asset.byte_size>20971520
    OR asset.mime_type NOT IN ('application/pdf','image/jpeg','image/png','image/webp') THEN
  RAISE EXCEPTION 'Verification evidence requires an owned ready private PDF/image of 1 byte to 20 MiB' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END; $$;
CREATE TRIGGER business_application_private_evidence BEFORE INSERT OR UPDATE ON provider_application_documents FOR EACH ROW EXECUTE FUNCTION business_guard_private_evidence();
CREATE TRIGGER business_license_private_evidence BEFORE INSERT OR UPDATE OF asset_id,uploaded_by_user_id ON provider_licenses FOR EACH ROW EXECUTE FUNCTION business_guard_private_evidence();

CREATE FUNCTION business_guard_application_document() RETURNS trigger LANGUAGE plpgsql SET search_path=travora,pg_temp AS $$
DECLARE parent_status text;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Verification documents are retained as evidence history' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'Document records are immutable; append a new document revision' USING ERRCODE='23514'; END IF;
 SELECT status INTO parent_status FROM provider_applications WHERE id=NEW.application_id FOR UPDATE;
 IF TG_OP='INSERT' AND parent_status IN ('approved','rejected','withdrawn') THEN
  RAISE EXCEPTION 'A decided application cannot receive replacement evidence; create a new application' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END; $$;
CREATE TRIGGER business_application_document_guard BEFORE INSERT OR UPDATE OR DELETE ON provider_application_documents FOR EACH ROW EXECUTE FUNCTION business_guard_application_document();

CREATE FUNCTION business_guard_license() RETURNS trigger LANGUAGE plpgsql SET search_path=travora,pg_temp AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Retain provider license history' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' THEN
  IF ROW(NEW.id,NEW.provider_id,NEW.license_type_code,NEW.license_reference,NEW.created_at)
    IS DISTINCT FROM ROW(OLD.id,OLD.provider_id,OLD.license_type_code,OLD.license_reference,OLD.created_at) THEN
   RAISE EXCEPTION 'License identity is immutable' USING ERRCODE='23514';
  END IF;
  IF OLD.status<>'pending' AND ROW(NEW.asset_id,NEW.uploaded_by_user_id,NEW.country_code,NEW.issued_on,NEW.expires_on,NEW.reviewed_by_user_id,NEW.reviewed_at)
    IS DISTINCT FROM ROW(OLD.asset_id,OLD.uploaded_by_user_id,OLD.country_code,OLD.issued_on,OLD.expires_on,OLD.reviewed_by_user_id,OLD.reviewed_at) THEN
   RAISE EXCEPTION 'Reviewed license evidence and dates are immutable; add a renewed license' USING ERRCODE='23514';
  END IF;
  IF NEW.status<>OLD.status AND NOT ((OLD.status='pending' AND NEW.status IN ('verified','rejected')) OR
    (OLD.status='verified' AND NEW.status IN ('expired','revoked'))) THEN
   RAISE EXCEPTION 'Invalid license transition' USING ERRCODE='23514';
  END IF;
 END IF;
 IF NEW.status IN ('verified','rejected') AND (TG_OP='INSERT' OR NEW.status IS DISTINCT FROM OLD.status) THEN
  IF NOT EXISTS(SELECT 1 FROM users WHERE id=NEW.reviewed_by_user_id AND role='admin' AND status='active') THEN
   RAISE EXCEPTION 'License review requires an active global admin reviewer' USING ERRCODE='23514';
  END IF;
  NEW.reviewed_at:=COALESCE(NEW.reviewed_at,now());
 END IF;
 IF NEW.status='verified' AND (NEW.issued_on>current_date OR NEW.expires_on<current_date) THEN
  RAISE EXCEPTION 'A verified license must currently be in its validity period' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END; $$;
CREATE TRIGGER business_license_guard BEFORE INSERT OR UPDATE OR DELETE ON provider_licenses FOR EACH ROW EXECUTE FUNCTION business_guard_license();

CREATE FUNCTION business_guard_driver() RETURNS trigger LANGUAGE plpgsql SET search_path=travora,pg_temp AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Retain driver identity; suspend the driver' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' AND ROW(NEW.id,NEW.user_id,NEW.created_at) IS DISTINCT FROM ROW(OLD.id,OLD.user_id,OLD.created_at) THEN
  RAISE EXCEPTION 'Driver identity is immutable' USING ERRCODE='23514';
 END IF;
 IF NEW.status='active' THEN
  IF TG_OP='INSERT' OR OLD.status<>'active' OR NEW.verified_by_user_id IS DISTINCT FROM OLD.verified_by_user_id OR NEW.verified_at IS DISTINCT FROM OLD.verified_at THEN
   IF NOT EXISTS(SELECT 1 FROM users WHERE id=NEW.verified_by_user_id AND role='admin' AND status='active') THEN
    RAISE EXCEPTION 'Activating a driver requires an active admin verifier' USING ERRCODE='23514';
   END IF;
  END IF;
  IF NEW.license_media_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM media_assets a WHERE a.id=NEW.license_media_id
   AND a.owner_user_id=NEW.user_id AND a.visibility='private' AND a.status='ready'
   AND a.byte_size BETWEEN 1 AND 20971520 AND a.mime_type IN ('application/pdf','image/jpeg','image/png','image/webp')) THEN
   RAISE EXCEPTION 'Driver license evidence must be an owned ready private PDF/image' USING ERRCODE='23514';
  END IF;
  IF NEW.license_expires_on<current_date THEN RAISE EXCEPTION 'Driver license has expired' USING ERRCODE='23514'; END IF;
  NEW.verified_at:=COALESCE(NEW.verified_at,now());
 ELSE NEW.availability:='offline'; END IF;
 RETURN NEW;
END; $$;
CREATE TRIGGER business_driver_guard BEFORE INSERT OR UPDATE OR DELETE ON driver_profiles FOR EACH ROW EXECUTE FUNCTION business_guard_driver();

CREATE FUNCTION business_guard_payout_destination() RETURNS trigger LANGUAGE plpgsql SET search_path=travora,pg_temp AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Retain payout destination history; disable it instead' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' AND ROW(NEW.id,NEW.provider_id,NEW.currency,NEW.processor,NEW.processor_account_ref,NEW.created_at)
  IS DISTINCT FROM ROW(OLD.id,OLD.provider_id,OLD.currency,OLD.processor,OLD.processor_account_ref,OLD.created_at) THEN
  RAISE EXCEPTION 'Tokenized payout destination ownership and processor identity are immutable' USING ERRCODE='23514';
 END IF;
 IF NEW.status='active' AND NEW.verified_at IS NULL THEN RAISE EXCEPTION 'Activate a payout destination only after processor verification' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END; $$;
CREATE TRIGGER business_payout_destination_guard BEFORE INSERT OR UPDATE OR DELETE ON provider_payout_destinations FOR EACH ROW EXECUTE FUNCTION business_guard_payout_destination();

CREATE FUNCTION business_guard_scoped_identity() RETURNS trigger LANGUAGE plpgsql SET search_path=travora,pg_temp AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Retain scoped organization records; archive or retire them' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' AND ROW(NEW.id,NEW.provider_id,NEW.created_at) IS DISTINCT FROM ROW(OLD.id,OLD.provider_id,OLD.created_at) THEN
  RAISE EXCEPTION 'Organization-scoped identity is immutable' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END; $$;
CREATE TRIGGER business_branch_identity BEFORE INSERT OR UPDATE OR DELETE ON provider_branches FOR EACH ROW EXECUTE FUNCTION business_guard_scoped_identity();
CREATE TRIGGER business_vehicle_identity BEFORE INSERT OR UPDATE OR DELETE ON provider_vehicles FOR EACH ROW EXECUTE FUNCTION business_guard_scoped_identity();

CREATE FUNCTION business_guard_audit() RETURNS trigger LANGUAGE plpgsql SET search_path=travora,pg_temp AS $$
BEGIN RAISE EXCEPTION 'Provider audit events are append-only' USING ERRCODE='23514'; END; $$;
CREATE TRIGGER business_audit_immutable BEFORE UPDATE OR DELETE ON provider_audit_events FOR EACH ROW EXECUTE FUNCTION business_guard_audit();

COMMENT ON TABLE provider_memberships IS 'Organization-scoped membership and role; one user may serve several providers. Global users.role does not grant membership. API checks provider_has_permission using the authenticated user, including assigned-job filtering for drivers/guides.';
COMMENT ON TABLE provider_applications IS 'Application and declared admin review data. Backend authenticates reviewers; submission, evidence review and legal compliance are application workflows, not automatic external verification.';
COMMENT ON TABLE driver_profiles IS 'Driver identity and declared admin verification. Assignments additionally require an active driver membership in the same provider. External license verification and background checks need backend integrations.';
COMMENT ON TABLE provider_audit_events IS 'Append-only organization events written by authorized backend workflows. Actor id is bound by the API; do not put secrets or private document contents into summary.';


-- Travora / trips, planning, AI execution, live replanning, budgets and documents.
-- PostgreSQL 16+. Executed inside the enclosing installation transaction.
-- UUID generation uses PostgreSQL's built-in gen_random_uuid(); no extension required.

CREATE TABLE trips (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    owner_user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    destination_id uuid REFERENCES destinations(id) ON DELETE RESTRICT,
    title text NOT NULL CHECK (length(btrim(title)) BETWEEN 1 AND 200),
    starts_on date,
    ends_on date,
    timezone text NOT NULL DEFAULT 'Africa/Cairo'
        CHECK (length(btrim(timezone)) BETWEEN 1 AND 128),
    status text NOT NULL DEFAULT 'draft'
        CHECK (status IN ('draft', 'planned', 'upcoming', 'active', 'completed', 'cancelled')),
    budget_minor bigint NOT NULL DEFAULT 0 CHECK (budget_minor >= 0),
    currency char(3) NOT NULL REFERENCES currencies(code) ON DELETE RESTRICT,
    active_itinerary_version_id uuid,
    saved_at timestamptz,
    archived_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT trips_dates_ck CHECK (
        (starts_on IS NULL AND ends_on IS NULL)
        OR (starts_on IS NOT NULL AND ends_on IS NOT NULL AND ends_on >= starts_on)
    ),
    CONSTRAINT trips_owner_uq UNIQUE (id, owner_user_id),
    CONSTRAINT trips_currency_uq UNIQUE (id, currency)
);
CREATE INDEX trips_owner_status_dates_idx ON trips(owner_user_id, status, starts_on DESC)
    WHERE archived_at IS NULL;
CREATE INDEX trips_destination_idx ON trips(destination_id) WHERE destination_id IS NOT NULL;
CREATE INDEX trips_owner_saved_idx ON trips(owner_user_id, saved_at DESC)
    WHERE saved_at IS NOT NULL AND archived_at IS NULL;
COMMENT ON COLUMN trips.budget_minor IS 'Integer minor units: EGP 500.00 = 50000. Currency exponent comes from currencies.';
COMMENT ON COLUMN trips.timezone IS 'IANA timezone checked by the API against supported tzdb names; all instants use timestamptz.';
COMMENT ON COLUMN trips.active_itinerary_version_id IS 'Composite deferred FK below prevents selecting another trip''s version.';
COMMENT ON COLUMN trips.saved_at IS 'Owner explicitly saved/bookmarked plan: saved trips tab filters non-null saved_at; planned status alone does not mean saved.';

CREATE TABLE trip_travelers (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    trip_id uuid NOT NULL REFERENCES trips(id) ON DELETE CASCADE,
    display_name text NOT NULL CHECK (length(btrim(display_name)) BETWEEN 1 AND 150),
    traveler_kind text NOT NULL DEFAULT 'adult' CHECK (traveler_kind IN ('adult', 'child', 'infant')),
    linked_user_id uuid REFERENCES users(id) ON DELETE SET NULL,
    contact_email text CHECK (contact_email IS NULL OR length(contact_email) <= 320),
    is_primary boolean NOT NULL DEFAULT false,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT trip_travelers_trip_uq UNIQUE (id, trip_id)
);
CREATE INDEX trip_travelers_trip_idx ON trip_travelers(trip_id);
CREATE UNIQUE INDEX trip_travelers_one_primary_uq ON trip_travelers(trip_id) WHERE is_primary;
CREATE INDEX trip_travelers_linked_user_idx ON trip_travelers(linked_user_id) WHERE linked_user_id IS NOT NULL;
COMMENT ON TABLE trip_travelers IS 'Travel party display/contact data only; no passport number, national ID or payment credentials.';

CREATE TABLE planner_requests (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    owner_user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    trip_id uuid,
    destination_id uuid NOT NULL REFERENCES destinations(id) ON DELETE RESTRICT,
    starts_on date NOT NULL,
    ends_on date NOT NULL CHECK (ends_on >= starts_on),
    traveler_count smallint NOT NULL CHECK (traveler_count BETWEEN 1 AND 99),
    budget_minor bigint NOT NULL CHECK (budget_minor >= 0),
    currency char(3) NOT NULL REFERENCES currencies(code) ON DELETE RESTRICT,
    preferences_schema_version smallint NOT NULL DEFAULT 1 CHECK (preferences_schema_version > 0),
    preferences jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(preferences) = 'object'),
    locale text NOT NULL DEFAULT 'ar' CHECK (locale IN ('ar', 'en')),
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT planner_requests_trip_owner_fk FOREIGN KEY (trip_id, owner_user_id)
        REFERENCES trips(id, owner_user_id) ON DELETE CASCADE,
    CONSTRAINT planner_requests_owner_uq UNIQUE (id, owner_user_id)
);
CREATE INDEX planner_requests_owner_created_idx ON planner_requests(owner_user_id, created_at DESC);
CREATE INDEX planner_requests_trip_idx ON planner_requests(trip_id) WHERE trip_id IS NOT NULL;
CREATE INDEX planner_requests_destination_idx ON planner_requests(destination_id);
COMMENT ON COLUMN planner_requests.preferences IS 'Versioned normalized JSON. v1: interest slugs, pace slow|balanced|fast, accessibility tags and transport preferences. Validate JSON Schema in API; never put traveler names/contact, prompts or secrets here.';

CREATE TABLE ai_jobs (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    owner_user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    trip_id uuid,
    planner_request_id uuid,
    job_type text NOT NULL CHECK (job_type IN ('plan', 'replan', 'summarize')),
    status text NOT NULL DEFAULT 'queued'
        CHECK (status IN ('queued', 'running', 'cancelling', 'cancelled', 'succeeded', 'failed')),
    idempotency_key text NOT NULL CHECK (length(btrim(idempotency_key)) BETWEEN 1 AND 160),
    trace_id uuid NOT NULL DEFAULT gen_random_uuid(),
    input_schema_version smallint NOT NULL DEFAULT 1 CHECK (input_schema_version > 0),
    input_payload jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(input_payload) = 'object'),
    output_schema_version smallint CHECK (output_schema_version > 0),
    output_payload jsonb CHECK (output_payload IS NULL OR jsonb_typeof(output_payload) = 'object'),
    priority smallint NOT NULL DEFAULT 0 CHECK (priority BETWEEN -10 AND 10),
    max_attempts smallint NOT NULL DEFAULT 3 CHECK (max_attempts BETWEEN 1 AND 10),
    available_at timestamptz NOT NULL DEFAULT now(),
    lease_expires_at timestamptz,
    heartbeat_at timestamptz,
    started_at timestamptz,
    cancel_requested_at timestamptz,
    finished_at timestamptz,
    error_code text CHECK (error_code IS NULL OR length(error_code) <= 100),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT ai_jobs_context_ck CHECK (trip_id IS NOT NULL OR planner_request_id IS NOT NULL),
    CONSTRAINT ai_jobs_replan_context_ck CHECK (job_type <> 'replan' OR trip_id IS NOT NULL),
    CONSTRAINT ai_jobs_output_version_ck CHECK ((output_payload IS NULL) = (output_schema_version IS NULL)),
    CONSTRAINT ai_jobs_terminal_time_ck CHECK (
        (status IN ('cancelled', 'succeeded', 'failed')) = (finished_at IS NOT NULL)
    ),
    CONSTRAINT ai_jobs_time_order_ck CHECK (started_at IS NULL OR finished_at IS NULL OR finished_at >= started_at),
    CONSTRAINT ai_jobs_trip_owner_fk FOREIGN KEY (trip_id, owner_user_id)
        REFERENCES trips(id, owner_user_id) ON DELETE CASCADE,
    CONSTRAINT ai_jobs_request_owner_fk FOREIGN KEY (planner_request_id, owner_user_id)
        REFERENCES planner_requests(id, owner_user_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT ai_jobs_owner_idempotency_uq UNIQUE (owner_user_id, idempotency_key),
    CONSTRAINT ai_jobs_owner_uq UNIQUE (id, owner_user_id),
    CONSTRAINT ai_jobs_trip_uq UNIQUE (id, trip_id)
);
CREATE INDEX ai_jobs_queue_idx ON ai_jobs(priority DESC, available_at, created_at) WHERE status = 'queued';
CREATE INDEX ai_jobs_expired_lease_idx ON ai_jobs(lease_expires_at) WHERE status IN ('running', 'cancelling');
CREATE INDEX ai_jobs_owner_created_idx ON ai_jobs(owner_user_id, created_at DESC);
CREATE INDEX ai_jobs_trip_idx ON ai_jobs(trip_id) WHERE trip_id IS NOT NULL;
CREATE INDEX ai_jobs_request_idx ON ai_jobs(planner_request_id) WHERE planner_request_id IS NOT NULL;
COMMENT ON TABLE ai_jobs IS 'Worker claims with SELECT ... FOR UPDATE SKIP LOCKED. Enforce lease ownership, cancellation, retry limits and transitions atomically in worker/API; CHECKs validate stored states but do not implement the worker.';
COMMENT ON COLUMN ai_jobs.input_payload IS 'Normalized planning context only. Do not store secrets or raw PII/prompts. Redact provider errors and apply retention to payloads.';
COMMENT ON COLUMN ai_jobs.output_payload IS 'Optional validated provider output. Canonical accepted plan is normalized into itinerary tables; prune raw output on retention expiry.';

CREATE TABLE ai_job_attempts (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    ai_job_id uuid NOT NULL REFERENCES ai_jobs(id) ON DELETE CASCADE,
    attempt_number smallint NOT NULL CHECK (attempt_number BETWEEN 1 AND 10),
    status text NOT NULL DEFAULT 'running' CHECK (status IN ('running', 'succeeded', 'failed', 'cancelled')),
    provider text NOT NULL CHECK (length(btrim(provider)) BETWEEN 1 AND 80),
    model text NOT NULL CHECK (length(btrim(model)) BETWEEN 1 AND 160),
    input_tokens bigint NOT NULL DEFAULT 0 CHECK (input_tokens >= 0),
    output_tokens bigint NOT NULL DEFAULT 0 CHECK (output_tokens >= 0),
    cost_minor bigint CHECK (cost_minor >= 0),
    cost_currency char(3) REFERENCES currencies(code) ON DELETE RESTRICT,
    provider_request_id text CHECK (provider_request_id IS NULL OR length(provider_request_id) <= 200),
    error_code text CHECK (error_code IS NULL OR length(error_code) <= 100),
    started_at timestamptz NOT NULL DEFAULT now(),
    finished_at timestamptz,
    CONSTRAINT ai_job_attempts_number_uq UNIQUE (ai_job_id, attempt_number),
    CONSTRAINT ai_job_attempts_cost_pair_ck CHECK ((cost_minor IS NULL) = (cost_currency IS NULL)),
    CONSTRAINT ai_job_attempts_terminal_ck CHECK ((status <> 'running') = (finished_at IS NOT NULL)),
    CONSTRAINT ai_job_attempts_time_ck CHECK (finished_at IS NULL OR finished_at >= started_at)
);
CREATE INDEX ai_job_attempts_cost_currency_idx ON ai_job_attempts(cost_currency) WHERE cost_currency IS NOT NULL;
CREATE UNIQUE INDEX ai_job_attempts_one_running_uq ON ai_job_attempts(ai_job_id) WHERE status = 'running';

CREATE TABLE itinerary_versions (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    trip_id uuid NOT NULL,
    owner_user_id uuid NOT NULL,
    version_number integer NOT NULL CHECK (version_number > 0),
    source text NOT NULL CHECK (source IN ('ai', 'manual', 'replan')),
    ai_job_id uuid,
    title text NOT NULL CHECK (length(btrim(title)) BETWEEN 1 AND 200),
    summary text CHECK (summary IS NULL OR length(summary) <= 4000),
    status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'ready', 'superseded', 'rejected')),
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT itinerary_versions_trip_owner_fk FOREIGN KEY (trip_id, owner_user_id)
        REFERENCES trips(id, owner_user_id) ON DELETE CASCADE,
    CONSTRAINT itinerary_versions_job_trip_fk FOREIGN KEY (ai_job_id, trip_id)
        REFERENCES ai_jobs(id, trip_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT itinerary_versions_number_uq UNIQUE (trip_id, version_number),
    CONSTRAINT itinerary_versions_trip_uq UNIQUE (id, trip_id)
);
CREATE INDEX itinerary_versions_job_idx ON itinerary_versions(ai_job_id) WHERE ai_job_id IS NOT NULL;
ALTER TABLE trips ADD CONSTRAINT trips_active_version_fk
    FOREIGN KEY (active_itinerary_version_id, id) REFERENCES itinerary_versions(id, trip_id)
    DEFERRABLE INITIALLY DEFERRED;
COMMENT ON TABLE itinerary_versions IS 'Keep accepted plans as versioned snapshots. Active pointer is owned by trips; explicit API edits create a new version rather than overwriting accepted history.';

CREATE TABLE itinerary_days (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    trip_id uuid NOT NULL,
    itinerary_version_id uuid NOT NULL,
    day_number smallint NOT NULL CHECK (day_number BETWEEN 1 AND 366),
    day_date date NOT NULL,
    title text NOT NULL CHECK (length(btrim(title)) BETWEEN 1 AND 200),
    summary text CHECK (summary IS NULL OR length(summary) <= 2000),
    CONSTRAINT itinerary_days_version_trip_fk FOREIGN KEY (itinerary_version_id, trip_id)
        REFERENCES itinerary_versions(id, trip_id) ON DELETE CASCADE,
    CONSTRAINT itinerary_days_number_uq UNIQUE (itinerary_version_id, day_number),
    CONSTRAINT itinerary_days_date_uq UNIQUE (itinerary_version_id, day_date),
    CONSTRAINT itinerary_days_parent_uq UNIQUE (id, trip_id, itinerary_version_id)
);
CREATE INDEX itinerary_days_trip_idx ON itinerary_days(trip_id, day_date);
COMMENT ON COLUMN itinerary_days.day_date IS 'API validates the day lies within trip dates and checks item times against trip timezone.';

CREATE FUNCTION valid_route_linestring(route jsonb)
RETURNS boolean LANGUAGE plpgsql IMMUTABLE STRICT AS $$
DECLARE coordinate jsonb;
BEGIN
    IF jsonb_typeof(route) IS DISTINCT FROM 'object'
       OR route->>'type' IS DISTINCT FROM 'LineString'
       OR jsonb_typeof(route->'coordinates') IS DISTINCT FROM 'array' THEN
        RETURN false;
    END IF;
    IF jsonb_array_length(route->'coordinates') < 2 THEN RETURN false; END IF;
    FOR coordinate IN SELECT value FROM jsonb_array_elements(route->'coordinates') LOOP
        IF jsonb_typeof(coordinate) IS DISTINCT FROM 'array' THEN RETURN false; END IF;
        IF jsonb_array_length(coordinate) <> 2 THEN RETURN false; END IF;
        IF jsonb_typeof(coordinate->0) IS DISTINCT FROM 'number'
           OR jsonb_typeof(coordinate->1) IS DISTINCT FROM 'number' THEN RETURN false; END IF;
        IF (coordinate->>0)::numeric NOT BETWEEN -180 AND 180
           OR (coordinate->>1)::numeric NOT BETWEEN -90 AND 90 THEN RETURN false; END IF;
    END LOOP;
    RETURN true;
END;
$$;
COMMENT ON FUNCTION valid_route_linestring(jsonb) IS 'Validates optional two-dimensional WGS84 GeoJSON LineString: [longitude, latitude], at least two valid points; no PostGIS dependency.';

CREATE TABLE itinerary_items (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    trip_id uuid NOT NULL,
    itinerary_version_id uuid NOT NULL,
    day_id uuid NOT NULL,
    destination_id uuid REFERENCES destinations(id) ON DELETE RESTRICT,
    activity_session_id uuid REFERENCES activity_sessions(id) ON DELETE RESTRICT,
    transport_offer_id uuid REFERENCES transport_offers(id) ON DELETE RESTRICT,
    position smallint NOT NULL CHECK (position >= 0),
    item_kind text NOT NULL CHECK (item_kind IN ('accommodation', 'activity', 'meal', 'transfer', 'free_time')),
    title text NOT NULL CHECK (length(btrim(title)) BETWEEN 1 AND 200),
    description text CHECK (description IS NULL OR length(description) <= 4000),
    starts_at timestamptz,
    ends_at timestamptz,
    location_label text CHECK (location_label IS NULL OR length(location_label) <= 200),
    latitude numeric(9,6) CHECK (latitude BETWEEN -90 AND 90),
    longitude numeric(9,6) CHECK (longitude BETWEEN -180 AND 180),
    route_geometry jsonb CHECK (valid_route_linestring(route_geometry)),
    estimated_cost_minor bigint NOT NULL DEFAULT 0 CHECK (estimated_cost_minor >= 0),
    currency char(3) NOT NULL,
    status text NOT NULL DEFAULT 'planned' CHECK (status IN ('planned', 'in_progress', 'completed', 'skipped')),
    completed_at timestamptz,
    notes text CHECK (notes IS NULL OR length(notes) <= 2000),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT itinerary_items_day_parent_fk FOREIGN KEY (day_id, trip_id, itinerary_version_id)
        REFERENCES itinerary_days(id, trip_id, itinerary_version_id) ON DELETE CASCADE,
    CONSTRAINT itinerary_items_currency_fk FOREIGN KEY (trip_id, currency)
        REFERENCES trips(id, currency) ON DELETE CASCADE,
    CONSTRAINT itinerary_items_position_uq UNIQUE (day_id, position),
    CONSTRAINT itinerary_items_trip_uq UNIQUE (id, trip_id),
    CONSTRAINT itinerary_items_times_ck CHECK (
        (starts_at IS NULL AND ends_at IS NULL)
        OR (starts_at IS NOT NULL AND ends_at IS NOT NULL AND ends_at > starts_at)
    ),
    CONSTRAINT itinerary_items_coordinate_pair_ck CHECK ((latitude IS NULL) = (longitude IS NULL)),
    CONSTRAINT itinerary_items_activity_kind_ck CHECK (activity_session_id IS NULL OR item_kind = 'activity'),
    CONSTRAINT itinerary_items_transport_kind_ck CHECK (transport_offer_id IS NULL OR item_kind = 'transfer'),
    CONSTRAINT itinerary_items_completed_ck CHECK ((status = 'completed') = (completed_at IS NOT NULL))
);
CREATE INDEX itinerary_items_trip_version_idx ON itinerary_items(trip_id, itinerary_version_id);
CREATE INDEX itinerary_items_activity_session_idx ON itinerary_items(activity_session_id) WHERE activity_session_id IS NOT NULL;
CREATE INDEX itinerary_items_transport_offer_idx ON itinerary_items(transport_offer_id) WHERE transport_offer_id IS NOT NULL;
CREATE INDEX itinerary_items_destination_idx ON itinerary_items(destination_id) WHERE destination_id IS NOT NULL;
COMMENT ON COLUMN itinerary_items.estimated_cost_minor IS 'Planning estimate in trip currency; not a reservation, expense or locked catalog price.';

CREATE TABLE trip_live_events (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    trip_id uuid NOT NULL REFERENCES trips(id) ON DELETE CASCADE,
    itinerary_item_id uuid,
    event_kind text NOT NULL CHECK (event_kind IN ('weather', 'closure', 'traffic', 'delay', 'budget', 'manual')),
    severity text NOT NULL DEFAULT 'info' CHECK (severity IN ('info', 'warning', 'critical')),
    title text NOT NULL CHECK (length(btrim(title)) BETWEEN 1 AND 200),
    details text CHECK (details IS NULL OR length(details) <= 2000),
    source_kind text NOT NULL CHECK (source_kind IN ('provider', 'staff', 'traveler', 'system')),
    source_name text NOT NULL CHECK (length(btrim(source_name)) BETWEEN 1 AND 150),
    source_reference text CHECK (source_reference IS NULL OR length(source_reference) <= 500),
    reliability text NOT NULL DEFAULT 'unverified' CHECK (reliability IN ('unverified', 'estimated', 'verified')),
    observed_at timestamptz NOT NULL,
    expires_at timestamptz,
    acknowledged_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT trip_live_events_item_trip_fk FOREIGN KEY (itinerary_item_id, trip_id)
        REFERENCES itinerary_items(id, trip_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT trip_live_events_expiry_ck CHECK (expires_at IS NULL OR expires_at > observed_at),
    CONSTRAINT trip_live_events_trip_uq UNIQUE (id, trip_id)
);
CREATE INDEX trip_live_events_trip_observed_idx ON trip_live_events(trip_id, observed_at DESC);
CREATE INDEX trip_live_events_item_idx ON trip_live_events(itinerary_item_id) WHERE itinerary_item_id IS NOT NULL;
COMMENT ON TABLE trip_live_events IS 'Source/reliability/freshness distinguish verified observations from estimates. An event does not confirm a booking cancellation or automatically change accepted plans.';

CREATE TABLE trip_replans (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    trip_id uuid NOT NULL,
    owner_user_id uuid NOT NULL,
    source_event_id uuid,
    base_version_id uuid NOT NULL,
    resulting_version_id uuid,
    ai_job_id uuid,
    reason_code text NOT NULL CHECK (reason_code IN ('weather', 'closure', 'delay', 'budget', 'user_edit', 'other')),
    reason text CHECK (reason IS NULL OR length(reason) <= 2000),
    status text NOT NULL DEFAULT 'suggested'
        CHECK (status IN ('suggested', 'accepted', 'running', 'applied', 'declined', 'cancelled', 'failed')),
    accepted_at timestamptz,
    applied_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT trip_replans_owner_fk FOREIGN KEY (trip_id, owner_user_id)
        REFERENCES trips(id, owner_user_id) ON DELETE CASCADE,
    CONSTRAINT trip_replans_event_trip_fk FOREIGN KEY (source_event_id, trip_id)
        REFERENCES trip_live_events(id, trip_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT trip_replans_base_trip_fk FOREIGN KEY (base_version_id, trip_id)
        REFERENCES itinerary_versions(id, trip_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT trip_replans_result_trip_fk FOREIGN KEY (resulting_version_id, trip_id)
        REFERENCES itinerary_versions(id, trip_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT trip_replans_job_trip_fk FOREIGN KEY (ai_job_id, trip_id)
        REFERENCES ai_jobs(id, trip_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT trip_replans_applied_ck CHECK (
        (status = 'applied') = (applied_at IS NOT NULL)
        AND (status <> 'applied' OR resulting_version_id IS NOT NULL)
    ),
    CONSTRAINT trip_replans_result_changed_ck CHECK (resulting_version_id IS NULL OR resulting_version_id <> base_version_id),
    CONSTRAINT trip_replans_time_ck CHECK (accepted_at IS NULL OR applied_at IS NULL OR applied_at >= accepted_at)
);
CREATE INDEX trip_replans_trip_created_idx ON trip_replans(trip_id, created_at DESC);
CREATE INDEX trip_replans_event_idx ON trip_replans(source_event_id) WHERE source_event_id IS NOT NULL;
CREATE INDEX trip_replans_base_version_idx ON trip_replans(base_version_id);
CREATE INDEX trip_replans_result_version_idx ON trip_replans(resulting_version_id) WHERE resulting_version_id IS NOT NULL;
CREATE INDEX trip_replans_job_idx ON trip_replans(ai_job_id) WHERE ai_job_id IS NOT NULL;
COMMENT ON TABLE trip_replans IS 'User accepts suggestion before applying. In one transaction, create ready version, move trip active pointer, mark applied; do not infer automatic refunds or actual reservations.';

CREATE TABLE trip_budget_categories (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    trip_id uuid NOT NULL,
    category text NOT NULL CHECK (category IN ('accommodation', 'transport', 'food', 'activities', 'shopping', 'other')),
    allocated_minor bigint NOT NULL DEFAULT 0 CHECK (allocated_minor >= 0),
    currency char(3) NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT trip_budget_categories_currency_fk FOREIGN KEY (trip_id, currency)
        REFERENCES trips(id, currency) ON DELETE CASCADE,
    CONSTRAINT trip_budget_categories_category_uq UNIQUE (trip_id, category)
);
COMMENT ON TABLE trip_budget_categories IS 'Optional allocations, not duplicated spending totals. API validates sum against budget if strict allocation is required; expenditures may exceed budget and must remain recordable.';

CREATE TABLE trip_expenses (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    trip_id uuid NOT NULL,
    owner_user_id uuid NOT NULL,
    itinerary_item_id uuid,
    category text NOT NULL CHECK (category IN ('accommodation', 'transport', 'food', 'activities', 'shopping', 'other')),
    entry_kind text NOT NULL DEFAULT 'expense' CHECK (entry_kind IN ('expense', 'refund')),
    title text NOT NULL CHECK (length(btrim(title)) BETWEEN 1 AND 200),
    amount_minor bigint NOT NULL CHECK (amount_minor > 0),
    currency char(3) NOT NULL,
    occurred_at timestamptz NOT NULL,
    receipt_asset_id uuid,
    idempotency_key text CHECK (idempotency_key IS NULL OR length(btrim(idempotency_key)) BETWEEN 1 AND 160),
    notes text CHECK (notes IS NULL OR length(notes) <= 2000),
    voided_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT trip_expenses_owner_fk FOREIGN KEY (trip_id, owner_user_id)
        REFERENCES trips(id, owner_user_id) ON DELETE CASCADE,
    CONSTRAINT trip_expenses_currency_fk FOREIGN KEY (trip_id, currency)
        REFERENCES trips(id, currency) ON DELETE CASCADE,
    CONSTRAINT trip_expenses_item_trip_fk FOREIGN KEY (itinerary_item_id, trip_id)
        REFERENCES itinerary_items(id, trip_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT trip_expenses_receipt_owner_fk FOREIGN KEY (receipt_asset_id, owner_user_id)
        REFERENCES media_assets(id, owner_user_id) ON DELETE RESTRICT,
    CONSTRAINT trip_expenses_idempotency_uq UNIQUE (trip_id, idempotency_key)
);
CREATE INDEX trip_expenses_trip_time_idx ON trip_expenses(trip_id, occurred_at DESC) WHERE voided_at IS NULL;
CREATE INDEX trip_expenses_item_idx ON trip_expenses(itinerary_item_id) WHERE itinerary_item_id IS NOT NULL;
CREATE INDEX trip_expenses_receipt_idx ON trip_expenses(receipt_asset_id) WHERE receipt_asset_id IS NOT NULL;
COMMENT ON TABLE trip_expenses IS 'Actual recorded spending. Refund rows use positive amount and entry_kind refund; net = expenses - refunds excluding voided entries. Booked totals must not be silently double counted as paid expenses.';

CREATE TABLE trip_documents (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    trip_id uuid NOT NULL,
    owner_user_id uuid NOT NULL,
    asset_id uuid NOT NULL,
    booking_id uuid,
    document_type text NOT NULL CHECK (document_type IN ('e_ticket', 'hotel_voucher', 'itinerary', 'identity', 'insurance', 'other')),
    title text NOT NULL CHECK (length(btrim(title)) BETWEEN 1 AND 200),
    original_filename text NOT NULL CHECK (length(btrim(original_filename)) BETWEEN 1 AND 255),
    expires_on date,
    created_at timestamptz NOT NULL DEFAULT now(),
    deleted_at timestamptz,
    CONSTRAINT trip_documents_owner_fk FOREIGN KEY (trip_id, owner_user_id)
        REFERENCES trips(id, owner_user_id) ON DELETE CASCADE,
    CONSTRAINT trip_documents_asset_owner_fk FOREIGN KEY (asset_id, owner_user_id)
        REFERENCES media_assets(id, owner_user_id) ON DELETE RESTRICT,
    CONSTRAINT trip_documents_trip_asset_uq UNIQUE (trip_id, asset_id)
);
CREATE INDEX trip_documents_trip_created_idx ON trip_documents(trip_id, created_at DESC) WHERE deleted_at IS NULL;
CREATE INDEX trip_documents_asset_idx ON trip_documents(asset_id);
CREATE INDEX trip_documents_booking_idx ON trip_documents(booking_id) WHERE booking_id IS NOT NULL;
COMMENT ON TABLE trip_documents IS 'Own private assets only; API enforces private storage, signed access and malware/type/size checks. Preserve original Arabic filename. booking_id receives composite ownership FK after bookings is created.';

CREATE TABLE trip_share_links (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    trip_id uuid NOT NULL,
    owner_user_id uuid NOT NULL,
    token_hash bytea NOT NULL UNIQUE CHECK (octet_length(token_hash) = 32),
    can_view_budget boolean NOT NULL DEFAULT false,
    expires_at timestamptz NOT NULL,
    revoked_at timestamptz,
    last_accessed_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT trip_share_links_owner_fk FOREIGN KEY (trip_id, owner_user_id)
        REFERENCES trips(id, owner_user_id) ON DELETE CASCADE,
    CONSTRAINT trip_share_links_expiry_ck CHECK (expires_at > created_at),
    CONSTRAINT trip_share_links_revoke_ck CHECK (revoked_at IS NULL OR revoked_at >= created_at)
);
CREATE INDEX trip_share_links_trip_idx ON trip_share_links(trip_id);
CREATE INDEX trip_share_links_active_expiry_idx ON trip_share_links(expires_at) WHERE revoked_at IS NULL;
COMMENT ON TABLE trip_share_links IS 'Read-only itinerary sharing. Generate a cryptographically random opaque token in API; store SHA-256 only. Check revocation/expiry on every access; never include documents, travelers, contact data or payment data in public projection.';

CREATE VIEW trip_budget_summary AS
SELECT t.id AS trip_id,
       t.owner_user_id,
       t.currency,
       t.budget_minor,
       COALESCE(e.net_spent_minor, 0::numeric) AS spent_minor,
       t.budget_minor::numeric - COALESCE(e.net_spent_minor, 0::numeric) AS remaining_minor
FROM trips t
LEFT JOIN (
    SELECT trip_id,
           SUM(CASE WHEN entry_kind = 'refund' THEN -amount_minor::numeric ELSE amount_minor::numeric END) AS net_spent_minor
    FROM trip_expenses
    WHERE voided_at IS NULL
    GROUP BY trip_id
) e ON e.trip_id = t.id;
COMMENT ON VIEW trip_budget_summary IS 'Derived net actual expenses; numeric SUM avoids bigint overflow. remaining_minor can be negative for overspend or above budget after net refunds. API filters by owner; this view grants no public access.';


-- Travora: restaurant, restaurant-menu, private-guide and delivery catalogs.
-- Bookings and food orders are created by later modules; this file is catalog only.
-- Amounts use integer currency minor units, never floating-point prices.

CREATE TABLE restaurants (
    id                      uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    provider_id             uuid NOT NULL REFERENCES providers(id) ON DELETE RESTRICT,
    destination_id          uuid NOT NULL REFERENCES destinations(id) ON DELETE RESTRICT,
    slug                    text NOT NULL UNIQUE,
    name_ar                 text NOT NULL,
    name_en                 text NOT NULL,
    description_ar          text,
    description_en          text,
    cuisine_ar              text,
    cuisine_en              text,
    address_ar              text,
    address_en              text,
    timezone                text NOT NULL DEFAULT 'Africa/Cairo',
    latitude                numeric(9,6),
    longitude               numeric(9,6),
    currency                char(3) NOT NULL DEFAULT 'EGP' REFERENCES currencies(code) ON DELETE RESTRICT,
    hero_media_id           uuid REFERENCES media_assets(id) ON DELETE SET NULL,
    cancellation_hours      integer NOT NULL DEFAULT 24,
    status                  text NOT NULL DEFAULT 'draft',
    created_at              timestamptz NOT NULL DEFAULT now(),
    updated_at              timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT restaurants_provider_scope UNIQUE (id, provider_id),
    CONSTRAINT restaurants_currency_scope UNIQUE (id, currency),
    CONSTRAINT restaurants_slug_format CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND length(slug) <= 120),
    CONSTRAINT restaurants_names_valid CHECK (length(btrim(name_ar)) BETWEEN 1 AND 200 AND length(btrim(name_en)) BETWEEN 1 AND 200),
    CONSTRAINT restaurants_timezone_nonempty CHECK (length(btrim(timezone)) BETWEEN 1 AND 100),
    CONSTRAINT restaurants_latitude_valid CHECK (latitude IS NULL OR latitude BETWEEN -90 AND 90),
    CONSTRAINT restaurants_longitude_valid CHECK (longitude IS NULL OR longitude BETWEEN -180 AND 180),
    CONSTRAINT restaurants_coordinates_paired CHECK ((latitude IS NULL) = (longitude IS NULL)),
    CONSTRAINT restaurants_cancellation_hours_valid CHECK (cancellation_hours >= 0),
    CONSTRAINT restaurants_status_valid CHECK (status IN ('draft', 'active', 'archived')),
    CONSTRAINT restaurants_updated_at_valid CHECK (updated_at >= created_at)
);
CREATE INDEX restaurants_destination_status ON restaurants(destination_id, status);
CREATE INDEX restaurants_provider_status ON restaurants(provider_id, status);
CREATE INDEX restaurants_hero_media ON restaurants(hero_media_id) WHERE hero_media_id IS NOT NULL;
COMMENT ON COLUMN restaurants.timezone IS 'IANA restaurant-local timezone validated against pg_timezone_names before catalog writes. Sessions persist absolute timestamptz instants.';
COMMENT ON COLUMN restaurants.hero_media_id IS 'Public, ready catalog artwork only. The API verifies authorized provider membership and media visibility; id-only media references do not grant private-asset access.';

CREATE TABLE restaurant_hours (
    restaurant_id           uuid NOT NULL REFERENCES restaurants(id) ON DELETE CASCADE,
    weekday                 smallint NOT NULL,
    opens_at                time NOT NULL,
    closes_at               time NOT NULL,
    created_at              timestamptz NOT NULL DEFAULT now(),
    updated_at              timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (restaurant_id, weekday, opens_at),
    CONSTRAINT restaurant_hours_weekday_valid CHECK (weekday BETWEEN 0 AND 6),
    CONSTRAINT restaurant_hours_window_valid CHECK (closes_at > opens_at),
    CONSTRAINT restaurant_hours_updated_at_valid CHECK (updated_at >= created_at)
);
COMMENT ON TABLE restaurant_hours IS 'Recurring opening windows in restaurants.timezone. Weekday follows PostgreSQL DOW: Sunday=0 through Saturday=6. Multiple windows per day are supported. Split overnight opening across two dates; the API prevents overlapping windows and validates session starts against local opening hours.';

CREATE TABLE restaurant_menu_categories (
    id                      uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    restaurant_id           uuid NOT NULL REFERENCES restaurants(id) ON DELETE RESTRICT,
    code                    text NOT NULL,
    name_ar                 text NOT NULL,
    name_en                 text NOT NULL,
    sort_order              integer NOT NULL DEFAULT 0,
    status                  text NOT NULL DEFAULT 'active',
    created_at              timestamptz NOT NULL DEFAULT now(),
    updated_at              timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT restaurant_menu_categories_restaurant_scope UNIQUE (id, restaurant_id),
    CONSTRAINT restaurant_menu_categories_code_unique UNIQUE (restaurant_id, code),
    CONSTRAINT restaurant_menu_categories_code_format CHECK (code ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND length(code) <= 80),
    CONSTRAINT restaurant_menu_categories_names_valid CHECK (length(btrim(name_ar)) BETWEEN 1 AND 120 AND length(btrim(name_en)) BETWEEN 1 AND 120),
    CONSTRAINT restaurant_menu_categories_sort_valid CHECK (sort_order >= 0),
    CONSTRAINT restaurant_menu_categories_status_valid CHECK (status IN ('draft', 'active', 'archived')),
    CONSTRAINT restaurant_menu_categories_updated_at_valid CHECK (updated_at >= created_at)
);
CREATE INDEX restaurant_menu_categories_order ON restaurant_menu_categories(restaurant_id, status, sort_order);

CREATE TABLE menu_items (
    id                      uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    restaurant_id           uuid NOT NULL,
    category_id             uuid NOT NULL,
    code                    text NOT NULL,
    name_ar                 text NOT NULL,
    name_en                 text NOT NULL,
    description_ar          text,
    description_en          text,
    price_minor             bigint NOT NULL,
    currency                char(3) NOT NULL DEFAULT 'EGP',
    hero_media_id           uuid REFERENCES media_assets(id) ON DELETE SET NULL,
    status                  text NOT NULL DEFAULT 'active',
    is_available            boolean NOT NULL DEFAULT true,
    sort_order              integer NOT NULL DEFAULT 0,
    created_at              timestamptz NOT NULL DEFAULT now(),
    updated_at              timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT menu_items_restaurant_scope UNIQUE (id, restaurant_id),
    CONSTRAINT menu_items_currency_scope UNIQUE (id, currency),
    CONSTRAINT menu_items_restaurant_currency_scope UNIQUE (id, restaurant_id, currency),
    CONSTRAINT menu_items_code_unique UNIQUE (restaurant_id, code),
    CONSTRAINT menu_items_restaurant_currency_fk FOREIGN KEY (restaurant_id, currency) REFERENCES restaurants(id, currency) ON DELETE RESTRICT,
    CONSTRAINT menu_items_category_scope_fk FOREIGN KEY (category_id, restaurant_id) REFERENCES restaurant_menu_categories(id, restaurant_id) ON DELETE RESTRICT,
    CONSTRAINT menu_items_code_format CHECK (code ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND length(code) <= 80),
    CONSTRAINT menu_items_names_valid CHECK (length(btrim(name_ar)) BETWEEN 1 AND 200 AND length(btrim(name_en)) BETWEEN 1 AND 200),
    CONSTRAINT menu_items_price_nonnegative CHECK (price_minor >= 0),
    CONSTRAINT menu_items_status_valid CHECK (status IN ('draft', 'active', 'archived')),
    CONSTRAINT menu_items_sort_valid CHECK (sort_order >= 0),
    CONSTRAINT menu_items_updated_at_valid CHECK (updated_at >= created_at)
);
CREATE INDEX menu_items_restaurant_available ON menu_items(restaurant_id, status, sort_order) WHERE is_available;
CREATE INDEX menu_items_category ON menu_items(category_id, restaurant_id);
CREATE INDEX menu_items_hero_media ON menu_items(hero_media_id) WHERE hero_media_id IS NOT NULL;
COMMENT ON COLUMN menu_items.price_minor IS 'Current price of one menu-item unit in restaurant currency. Food-order lines persist their own immutable quoted price and text snapshots; historical totals never depend on later menu edits.';

CREATE TABLE menu_item_inventory (
    menu_item_id            uuid NOT NULL,
    inventory_date          date NOT NULL,
    currency                char(3) NOT NULL DEFAULT 'EGP',
    total_units             integer NOT NULL,
    held_units              integer NOT NULL DEFAULT 0,
    booked_units            integer NOT NULL DEFAULT 0,
    is_closed               boolean NOT NULL DEFAULT false,
    updated_at              timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (menu_item_id, inventory_date),
    CONSTRAINT menu_item_inventory_currency_scope UNIQUE (menu_item_id, inventory_date, currency),
    CONSTRAINT menu_item_inventory_item_currency_fk FOREIGN KEY (menu_item_id, currency) REFERENCES menu_items(id, currency) ON DELETE RESTRICT,
    CONSTRAINT menu_item_inventory_capacity_valid CHECK (total_units >= 0 AND held_units >= 0 AND booked_units >= 0 AND held_units::bigint + booked_units::bigint <= total_units::bigint)
);
CREATE INDEX menu_item_inventory_date_open ON menu_item_inventory(inventory_date, menu_item_id) WHERE NOT is_closed;
COMMENT ON TABLE menu_item_inventory IS 'Finite daily menu stock for the restaurant-local inventory_date. Every delivered order line needs a published inventory row. Extended order-allocation triggers lock rows and maintain held_units/booked_units by quantity; the application does not write counters directly. Availability is total_units - held_units - booked_units.';

CREATE TABLE restaurant_reservation_sessions (
    id                      uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    restaurant_id           uuid NOT NULL,
    starts_at               timestamptz NOT NULL,
    ends_at                 timestamptz NOT NULL,
    capacity                integer NOT NULL,
    held_count              integer NOT NULL DEFAULT 0,
    booked_count            integer NOT NULL DEFAULT 0,
    price_minor             bigint NOT NULL,
    currency                char(3) NOT NULL DEFAULT 'EGP',
    pricing_model           text NOT NULL DEFAULT 'per_reservation',
    status                  text NOT NULL DEFAULT 'scheduled',
    created_at              timestamptz NOT NULL DEFAULT now(),
    updated_at              timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT restaurant_reservation_sessions_restaurant_start_unique UNIQUE (restaurant_id, starts_at),
    CONSTRAINT restaurant_reservation_sessions_restaurant_scope UNIQUE (id, restaurant_id),
    CONSTRAINT restaurant_reservation_sessions_currency_scope UNIQUE (id, currency),
    CONSTRAINT restaurant_reservation_sessions_restaurant_currency_scope UNIQUE (id, restaurant_id, currency),
    CONSTRAINT restaurant_reservation_sessions_restaurant_currency_fk FOREIGN KEY (restaurant_id, currency) REFERENCES restaurants(id, currency) ON DELETE RESTRICT,
    CONSTRAINT restaurant_reservation_sessions_times_ordered CHECK (ends_at > starts_at),
    CONSTRAINT restaurant_reservation_sessions_capacity_valid CHECK (capacity >= 0 AND held_count >= 0 AND booked_count >= 0 AND held_count::bigint + booked_count::bigint <= capacity::bigint),
    CONSTRAINT restaurant_reservation_sessions_price_nonnegative CHECK (price_minor >= 0),
    CONSTRAINT restaurant_reservation_sessions_pricing_model_valid CHECK (pricing_model = 'per_reservation'),
    CONSTRAINT restaurant_reservation_sessions_status_valid CHECK (status IN ('scheduled', 'cancelled', 'completed')),
    CONSTRAINT restaurant_reservation_sessions_updated_at_valid CHECK (updated_at >= created_at)
);
CREATE INDEX restaurant_reservation_sessions_available ON restaurant_reservation_sessions(starts_at, restaurant_id) WHERE status = 'scheduled';
COMMENT ON TABLE restaurant_reservation_sessions IS 'Capacity and allocation counters count guests/seats, not reservation records. Booking allocation triggers lock the session and maintain held_count/booked_count by guest_count; applications do not write the counters directly. The fixed price_minor is the entire reservation deposit/base charge and is not multiplied by guest_count. Meal purchases remain separate food orders.';
COMMENT ON COLUMN restaurant_reservation_sessions.price_minor IS 'Fixed total deposit/base charge per reservation in currency minor units; zero is allowed. Do not multiply by guest count.';

CREATE TABLE restaurant_tables (
    id                      uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    restaurant_id           uuid NOT NULL REFERENCES restaurants(id) ON DELETE RESTRICT,
    label                   text NOT NULL,
    seats                   smallint NOT NULL,
    status                  text NOT NULL DEFAULT 'active',
    created_at              timestamptz NOT NULL DEFAULT now(),
    updated_at              timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT restaurant_tables_restaurant_scope UNIQUE (id, restaurant_id),
    CONSTRAINT restaurant_tables_label_unique UNIQUE (restaurant_id, label),
    CONSTRAINT restaurant_tables_label_valid CHECK (label = btrim(label) AND length(label) BETWEEN 1 AND 80),
    CONSTRAINT restaurant_tables_seats_valid CHECK (seats > 0),
    CONSTRAINT restaurant_tables_status_valid CHECK (status IN ('active', 'archived')),
    CONSTRAINT restaurant_tables_updated_at_valid CHECK (updated_at >= created_at)
);
CREATE INDEX restaurant_tables_restaurant_status ON restaurant_tables(restaurant_id, status);
COMMENT ON TABLE restaurant_tables IS 'Physical restaurant tables. The reservation MVP allocates one whole table per party; guest_count must fit seats. Combining tables requires an explicit future allocation migration.';

CREATE TABLE restaurant_table_inventory (
    session_id              uuid NOT NULL,
    table_id                uuid NOT NULL,
    restaurant_id           uuid NOT NULL,
    currency                char(3) NOT NULL DEFAULT 'EGP',
    capacity                integer NOT NULL DEFAULT 1,
    held_count              integer NOT NULL DEFAULT 0,
    booked_count            integer NOT NULL DEFAULT 0,
    updated_at              timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (session_id, table_id),
    CONSTRAINT restaurant_table_inventory_currency_scope UNIQUE (session_id, table_id, currency),
    CONSTRAINT restaurant_table_inventory_session_scope_fk FOREIGN KEY (session_id, restaurant_id, currency) REFERENCES restaurant_reservation_sessions(id, restaurant_id, currency) ON DELETE RESTRICT,
    CONSTRAINT restaurant_table_inventory_table_scope_fk FOREIGN KEY (table_id, restaurant_id) REFERENCES restaurant_tables(id, restaurant_id) ON DELETE RESTRICT,
    CONSTRAINT restaurant_table_inventory_capacity_valid CHECK (capacity = 1 AND held_count >= 0 AND booked_count >= 0 AND held_count::bigint + booked_count::bigint <= capacity::bigint)
);
CREATE INDEX restaurant_table_inventory_table ON restaurant_table_inventory(table_id, restaurant_id);
COMMENT ON TABLE restaurant_table_inventory IS 'One physical table published for one reservation session, in the same restaurant and currency. Capacity is exactly one whole table. Extended booking allocation guards lock both this row and the session guest-capacity row and maintain counters. The API must publish nonoverlapping session windows for each physical table.';

CREATE TABLE guide_profiles (
    id                      uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    provider_id             uuid NOT NULL UNIQUE REFERENCES providers(id) ON DELETE RESTRICT,
    destination_id          uuid NOT NULL REFERENCES destinations(id) ON DELETE RESTRICT,
    slug                    text NOT NULL UNIQUE,
    name_ar                 text NOT NULL,
    name_en                 text NOT NULL,
    bio_ar                  text,
    bio_en                  text,
    license_reference       text,
    hero_media_id           uuid REFERENCES media_assets(id) ON DELETE SET NULL,
    currency                char(3) NOT NULL DEFAULT 'EGP' REFERENCES currencies(code) ON DELETE RESTRICT,
    cancellation_hours      integer NOT NULL DEFAULT 24,
    status                  text NOT NULL DEFAULT 'draft',
    created_at              timestamptz NOT NULL DEFAULT now(),
    updated_at              timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT guide_profiles_provider_scope UNIQUE (id, provider_id),
    CONSTRAINT guide_profiles_currency_scope UNIQUE (id, currency),
    CONSTRAINT guide_profiles_slug_format CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND length(slug) <= 120),
    CONSTRAINT guide_profiles_names_valid CHECK (length(btrim(name_ar)) BETWEEN 1 AND 200 AND length(btrim(name_en)) BETWEEN 1 AND 200),
    CONSTRAINT guide_profiles_license_reference_valid CHECK (license_reference IS NULL OR length(btrim(license_reference)) BETWEEN 1 AND 180),
    CONSTRAINT guide_profiles_cancellation_hours_valid CHECK (cancellation_hours >= 0),
    CONSTRAINT guide_profiles_status_valid CHECK (status IN ('draft', 'active', 'archived')),
    CONSTRAINT guide_profiles_updated_at_valid CHECK (updated_at >= created_at)
);
CREATE INDEX guide_profiles_destination_status ON guide_profiles(destination_id, status);
CREATE INDEX guide_profiles_hero_media ON guide_profiles(hero_media_id) WHERE hero_media_id IS NOT NULL;
COMMENT ON TABLE guide_profiles IS 'One personal guide profile per provider. Names and biographies are public service presentation, not authentication identities. Provider authorization is enforced by the API before edits or booking fulfillment.';
COMMENT ON COLUMN guide_profiles.license_reference IS 'Opaque non-secret verification reference issued by the provider or verification service. Never store government identity numbers, raw license scans, or secret verification tokens in this public catalog column.';

CREATE TABLE guide_languages (
    guide_id                uuid NOT NULL REFERENCES guide_profiles(id) ON DELETE CASCADE,
    language_code           text NOT NULL,
    PRIMARY KEY (guide_id, language_code),
    CONSTRAINT guide_languages_code_format CHECK (length(language_code) BETWEEN 2 AND 8 AND language_code ~ '^[a-z]{2,3}(-[A-Z]{2}|-[A-Z][a-z]{3})?$')
);
CREATE INDEX guide_languages_language ON guide_languages(language_code, guide_id);
COMMENT ON COLUMN guide_languages.language_code IS 'Canonical language code with optional region or script: ar, en, fr, ar-EG or zh-Hans. The API checks supported languages; the format check is not a registry of all BCP 47 tags.';

CREATE TABLE guide_availability_slots (
    id                      uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    guide_id                uuid NOT NULL,
    starts_at               timestamptz NOT NULL,
    ends_at                 timestamptz NOT NULL,
    max_party_size          smallint NOT NULL,
    capacity                integer NOT NULL DEFAULT 1,
    held_count              integer NOT NULL DEFAULT 0,
    booked_count            integer NOT NULL DEFAULT 0,
    price_minor             bigint NOT NULL,
    currency                char(3) NOT NULL DEFAULT 'EGP',
    pricing_model           text NOT NULL DEFAULT 'per_appointment',
    status                  text NOT NULL DEFAULT 'scheduled',
    created_at              timestamptz NOT NULL DEFAULT now(),
    updated_at              timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT guide_availability_slots_guide_start_unique UNIQUE (guide_id, starts_at),
    CONSTRAINT guide_availability_slots_guide_scope UNIQUE (id, guide_id),
    CONSTRAINT guide_availability_slots_currency_scope UNIQUE (id, currency),
    CONSTRAINT guide_availability_slots_guide_currency_scope UNIQUE (id, guide_id, currency),
    CONSTRAINT guide_availability_slots_guide_currency_fk FOREIGN KEY (guide_id, currency) REFERENCES guide_profiles(id, currency) ON DELETE RESTRICT,
    CONSTRAINT guide_availability_slots_times_ordered CHECK (ends_at > starts_at),
    CONSTRAINT guide_availability_slots_party_size_valid CHECK (max_party_size > 0),
    CONSTRAINT guide_availability_slots_capacity_valid CHECK (capacity = 1 AND held_count >= 0 AND booked_count >= 0 AND held_count::bigint + booked_count::bigint <= capacity::bigint),
    CONSTRAINT guide_availability_slots_price_nonnegative CHECK (price_minor >= 0),
    CONSTRAINT guide_availability_slots_pricing_model_valid CHECK (pricing_model = 'per_appointment'),
    CONSTRAINT guide_availability_slots_status_valid CHECK (status IN ('scheduled', 'cancelled', 'completed')),
    CONSTRAINT guide_availability_slots_updated_at_valid CHECK (updated_at >= created_at)
);
CREATE INDEX guide_availability_slots_available ON guide_availability_slots(starts_at, guide_id) WHERE status = 'scheduled';
COMMENT ON TABLE guide_availability_slots IS 'One personal guide offers one appointment per slot: capacity is fixed to 1, and held/booked counters count whole appointments, not travelers. party_size must fit max_party_size. Extended allocation triggers lock slots and maintain counters; a serialized scheduling guard rejects overlapping scheduled slots for the same personal guide.';
COMMENT ON COLUMN guide_availability_slots.price_minor IS 'Fixed charge for one entire appointment in currency minor units. Do not multiply by party_size.';

CREATE TABLE restaurant_delivery_settings (
    restaurant_id           uuid PRIMARY KEY,
    is_enabled              boolean NOT NULL DEFAULT false,
    accepts_orders          boolean NOT NULL DEFAULT true,
    base_fee_minor          bigint NOT NULL DEFAULT 0,
    min_order_minor         bigint NOT NULL DEFAULT 0,
    currency                char(3) NOT NULL DEFAULT 'EGP',
    max_distance_km         numeric(7,2),
    estimated_minutes       integer,
    created_at              timestamptz NOT NULL DEFAULT now(),
    updated_at              timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT restaurant_delivery_settings_currency_scope UNIQUE (restaurant_id, currency),
    CONSTRAINT restaurant_delivery_settings_restaurant_currency_fk FOREIGN KEY (restaurant_id, currency) REFERENCES restaurants(id, currency) ON DELETE CASCADE,
    CONSTRAINT restaurant_delivery_settings_amounts_nonnegative CHECK (base_fee_minor >= 0 AND min_order_minor >= 0),
    CONSTRAINT restaurant_delivery_settings_distance_valid CHECK (max_distance_km IS NULL OR max_distance_km > 0),
    CONSTRAINT restaurant_delivery_settings_estimate_valid CHECK (estimated_minutes IS NULL OR estimated_minutes > 0),
    CONSTRAINT restaurant_delivery_settings_updated_at_valid CHECK (updated_at >= created_at)
);
COMMENT ON TABLE restaurant_delivery_settings IS 'Restaurant-owned delivery configuration only; drivers, order delivery addresses and status history live in later operational modules. Food-order checkout snapshots fees, menu prices and minimum-order eligibility so later configuration edits cannot change existing order totals.';

-- Shared timestamp-maintenance triggers are installed by 50_invariants.sql.
-- Provider memberships, public-ready hero/menu artwork, IANA timezones,
-- and recurring opening-window overlap are API checks. Personal-guide slot
-- overlap is enforced by the serialized guard in 52_extra_service_guards.sql.
-- Allocation counters are owned by the extended booking allocation triggers.


-- Shared order header; a deferred guard below requires exactly one matching subtype.
CREATE TABLE bookings (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    reference text NOT NULL UNIQUE,
    user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    trip_id uuid,
    kind text NOT NULL CHECK (kind IN ('HOTEL','ACTIVITY','TRANSPORT')),
    status text NOT NULL DEFAULT 'draft'
        CHECK (status IN ('draft','pending_payment','confirmed','cancelled','expired','completed')),
    payment_terms text NOT NULL DEFAULT 'prepaid' CHECK (payment_terms IN ('prepaid','pay_on_service')),
    currency char(3) NOT NULL REFERENCES currencies(code),
    subtotal_minor bigint NOT NULL CHECK (subtotal_minor >= 0),
    tax_minor bigint NOT NULL DEFAULT 0 CHECK (tax_minor >= 0),
    fee_minor bigint NOT NULL DEFAULT 0 CHECK (fee_minor >= 0),
    discount_minor bigint NOT NULL DEFAULT 0 CHECK (discount_minor >= 0),
    total_minor bigint GENERATED ALWAYS AS
        (subtotal_minor + tax_minor + fee_minor - discount_minor) STORED,
    service_title_snapshot text NOT NULL,
    cancellation_policy_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb
        CHECK (jsonb_typeof(cancellation_policy_snapshot) = 'object'),
    contact_name text NOT NULL,
    contact_email text NOT NULL,
    contact_phone text,
    hold_expires_at timestamptz,
    confirmed_at timestamptz,
    cancelled_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (id,user_id),
    UNIQUE (id,currency),
    FOREIGN KEY (trip_id,user_id) REFERENCES trips(id,owner_user_id) ON DELETE RESTRICT,
    FOREIGN KEY (trip_id,currency) REFERENCES trips(id,currency) ON DELETE RESTRICT,
    CHECK (total_minor >= 0),
    CHECK (status <> 'pending_payment' OR hold_expires_at IS NOT NULL),
    CHECK (hold_expires_at IS NULL OR hold_expires_at > created_at),
    CHECK (status NOT IN ('confirmed','completed') OR confirmed_at IS NOT NULL),
    CHECK (status <> 'cancelled' OR cancelled_at IS NOT NULL)
);
CREATE INDEX bookings_user_created_idx ON bookings(user_id,created_at DESC);
CREATE INDEX bookings_trip_idx ON bookings(trip_id);
CREATE INDEX bookings_expiry_idx ON bookings(hold_expires_at) WHERE status='pending_payment';

CREATE TABLE booking_travelers (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    booking_id uuid NOT NULL REFERENCES bookings(id) ON DELETE CASCADE,
    full_name text NOT NULL,
    age_group text NOT NULL DEFAULT 'adult' CHECK (age_group IN ('adult','child','infant')),
    email text,
    phone text,
    special_requests text,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX booking_travelers_booking_idx ON booking_travelers(booking_id);

CREATE TABLE hotel_booking_details (
    booking_id uuid PRIMARY KEY REFERENCES bookings(id) ON DELETE CASCADE,
    hotel_id uuid NOT NULL REFERENCES hotels(id) ON DELETE RESTRICT,
    room_type_id uuid NOT NULL,
    check_in date NOT NULL,
    check_out date NOT NULL,
    room_count integer NOT NULL CHECK (room_count > 0),
    adult_count integer NOT NULL CHECK (adult_count > 0),
    child_count integer NOT NULL DEFAULT 0 CHECK (child_count >= 0),
    room_name_snapshot text NOT NULL,
    meal_plan_snapshot text,
    FOREIGN KEY (room_type_id,hotel_id) REFERENCES room_types(id,hotel_id) ON DELETE RESTRICT,
    CHECK (check_out > check_in)
);
CREATE INDEX hotel_booking_details_room_idx ON hotel_booking_details(room_type_id);

CREATE TABLE activity_booking_details (
    booking_id uuid PRIMARY KEY REFERENCES bookings(id) ON DELETE CASCADE,
    activity_id uuid NOT NULL REFERENCES activities(id) ON DELETE RESTRICT,
    session_id uuid NOT NULL,
    participant_count integer NOT NULL CHECK (participant_count > 0),
    unit_price_minor bigint NOT NULL CHECK (unit_price_minor >= 0),
    service_starts_at_snapshot timestamptz NOT NULL,
    service_ends_at_snapshot timestamptz NOT NULL,
    FOREIGN KEY (session_id,activity_id) REFERENCES activity_sessions(id,activity_id) ON DELETE RESTRICT,
    CHECK (service_ends_at_snapshot > service_starts_at_snapshot)
);
CREATE INDEX activity_booking_details_session_idx ON activity_booking_details(session_id);

CREATE TABLE transport_booking_details (
    booking_id uuid PRIMARY KEY REFERENCES bookings(id) ON DELETE CASCADE,
    transport_service_id uuid NOT NULL REFERENCES transport_services(id) ON DELETE RESTRICT,
    offer_id uuid NOT NULL,
    passenger_count integer NOT NULL CHECK (passenger_count > 0),
    luggage_count integer NOT NULL DEFAULT 0 CHECK (luggage_count >= 0),
    unit_price_minor bigint NOT NULL CHECK (unit_price_minor >= 0),
    pickup_label text NOT NULL,
    dropoff_label text NOT NULL,
    pickup_at_snapshot timestamptz NOT NULL,
    FOREIGN KEY (offer_id,transport_service_id)
        REFERENCES transport_offers(id,transport_service_id) ON DELETE RESTRICT
);
CREATE INDEX transport_booking_details_offer_idx ON transport_booking_details(offer_id);

-- Every room night has its own frozen price and allocation. Checkout date is excluded.
CREATE TABLE room_night_allocations (
    booking_id uuid NOT NULL REFERENCES hotel_booking_details(booking_id) ON DELETE CASCADE,
    room_type_id uuid NOT NULL,
    inventory_date date NOT NULL,
    currency char(3) NOT NULL,
    units integer NOT NULL CHECK (units > 0),
    unit_price_minor bigint NOT NULL CHECK (unit_price_minor >= 0),
    state text NOT NULL DEFAULT 'held' CHECK (state IN ('held','committed','released')),
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (booking_id,inventory_date),
    FOREIGN KEY (room_type_id,inventory_date,currency)
        REFERENCES room_inventory(room_type_id,inventory_date,currency) ON DELETE RESTRICT,
    FOREIGN KEY (booking_id,currency) REFERENCES bookings(id,currency) ON DELETE RESTRICT
);
CREATE INDEX room_night_inventory_idx ON room_night_allocations(room_type_id,inventory_date);

CREATE TABLE activity_allocations (
    booking_id uuid PRIMARY KEY REFERENCES activity_booking_details(booking_id) ON DELETE CASCADE,
    session_id uuid NOT NULL,
    currency char(3) NOT NULL,
    units integer NOT NULL CHECK (units > 0),
    state text NOT NULL DEFAULT 'held' CHECK (state IN ('held','committed','released')),
    FOREIGN KEY (session_id,currency) REFERENCES activity_sessions(id,currency) ON DELETE RESTRICT,
    FOREIGN KEY (booking_id,currency) REFERENCES bookings(id,currency) ON DELETE RESTRICT
);
CREATE INDEX activity_allocations_session_idx ON activity_allocations(session_id);

CREATE TABLE transport_allocations (
    booking_id uuid PRIMARY KEY REFERENCES transport_booking_details(booking_id) ON DELETE CASCADE,
    offer_id uuid NOT NULL,
    currency char(3) NOT NULL,
    units integer NOT NULL CHECK (units > 0),
    state text NOT NULL DEFAULT 'held' CHECK (state IN ('held','committed','released')),
    FOREIGN KEY (offer_id,currency) REFERENCES transport_offers(id,currency) ON DELETE RESTRICT,
    FOREIGN KEY (booking_id,currency) REFERENCES bookings(id,currency) ON DELETE RESTRICT
);
CREATE INDEX transport_allocations_offer_idx ON transport_allocations(offer_id);

CREATE TABLE payment_attempts (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    booking_id uuid NOT NULL,
    currency char(3) NOT NULL,
    method text NOT NULL CHECK (method IN ('card','wallet','onsite')),
    provider text NOT NULL,
    idempotency_key text NOT NULL,
    provider_payment_id text,
    status text NOT NULL DEFAULT 'pending'
        CHECK (status IN ('pending','processing','authorized','succeeded','failed','cancelled')),
    amount_minor bigint NOT NULL CHECK (amount_minor > 0),
    failure_code text,
    succeeded_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (provider,idempotency_key),
    UNIQUE (provider,provider_payment_id),
    UNIQUE (id,currency),
    FOREIGN KEY (booking_id,currency) REFERENCES bookings(id,currency) ON DELETE RESTRICT,
    CHECK (status <> 'succeeded' OR succeeded_at IS NOT NULL)
);
CREATE INDEX payment_attempts_booking_idx ON payment_attempts(booking_id,status);

CREATE TABLE payment_webhook_events (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    provider text NOT NULL,
    provider_event_id text NOT NULL,
    payment_attempt_id uuid REFERENCES payment_attempts(id) ON DELETE RESTRICT,
    event_type text NOT NULL,
    payload_digest text NOT NULL,
    signature_verified boolean NOT NULL DEFAULT false,
    status text NOT NULL DEFAULT 'received' CHECK (status IN ('received','processed','failed','ignored')),
    received_at timestamptz NOT NULL DEFAULT now(),
    processed_at timestamptz,
    error_code text,
    UNIQUE (provider,provider_event_id),
    CHECK (status <> 'processed' OR (signature_verified AND processed_at IS NOT NULL))
);
CREATE INDEX payment_webhook_attempt_idx ON payment_webhook_events(payment_attempt_id);

CREATE TABLE refunds (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    payment_attempt_id uuid NOT NULL,
    currency char(3) NOT NULL,
    amount_minor bigint NOT NULL CHECK (amount_minor > 0),
    status text NOT NULL DEFAULT 'requested'
        CHECK (status IN ('requested','processing','succeeded','failed','cancelled')),
    idempotency_key text NOT NULL UNIQUE,
    provider_refund_id text UNIQUE,
    reason text NOT NULL,
    requested_by uuid REFERENCES users(id) ON DELETE RESTRICT,
    succeeded_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (payment_attempt_id,currency) REFERENCES payment_attempts(id,currency) ON DELETE RESTRICT,
    CHECK (status <> 'succeeded' OR succeeded_at IS NOT NULL)
);
CREATE INDEX refunds_payment_idx ON refunds(payment_attempt_id,status);

CREATE TABLE booking_cancellations (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    booking_id uuid NOT NULL UNIQUE,
    requested_by uuid NOT NULL,
    reason text NOT NULL,
    status text NOT NULL DEFAULT 'requested'
        CHECK (status IN ('requested','approved','rejected')),
    requested_at timestamptz NOT NULL DEFAULT now(),
    decided_at timestamptz,
    FOREIGN KEY (booking_id,requested_by) REFERENCES bookings(id,user_id) ON DELETE RESTRICT,
    CHECK (status='requested' OR decided_at IS NOT NULL)
);

CREATE TABLE booking_status_history (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    booking_id uuid NOT NULL REFERENCES bookings(id) ON DELETE RESTRICT,
    from_status text,
    to_status text NOT NULL,
    changed_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX booking_status_history_booking_idx ON booking_status_history(booking_id,changed_at);

-- A cached paid/due display is computed, never a mutable second financial truth.
CREATE VIEW booking_balances AS
SELECT b.id AS booking_id, b.user_id, b.currency, b.total_minor,
       COALESCE(p.captured_minor,0)::bigint AS captured_minor,
       COALESCE(r.refunded_minor,0)::bigint AS refunded_minor,
       (COALESCE(p.captured_minor,0)-COALESCE(r.refunded_minor,0))::bigint AS net_paid_minor,
       CASE WHEN b.status IN ('cancelled','expired') THEN 0::bigint
         ELSE GREATEST(b.total_minor-COALESCE(p.captured_minor,0),0)::bigint END AS outstanding_minor
FROM bookings b
LEFT JOIN (SELECT booking_id,SUM(amount_minor) AS captured_minor
           FROM payment_attempts WHERE status='succeeded' GROUP BY booking_id) p ON p.booking_id=b.id
LEFT JOIN (SELECT p.booking_id,SUM(r.amount_minor) AS refunded_minor FROM refunds r
           JOIN payment_attempts p ON p.id=r.payment_attempt_id
           WHERE r.status='succeeded' GROUP BY p.booking_id) r ON r.booking_id=b.id;


-- Travora: favorites, verified-owner reviews, notification inbox, support and CMS.
-- Requires 10_identity_catalog.sql, 20_trips.sql and 30_bookings.sql.
SET search_path TO travora, public;

CREATE TABLE favorites (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    destination_id uuid REFERENCES destinations(id) ON DELETE CASCADE,
    hotel_id uuid REFERENCES hotels(id) ON DELETE CASCADE,
    activity_id uuid REFERENCES activities(id) ON DELETE CASCADE,
    transport_service_id uuid REFERENCES transport_services(id) ON DELETE CASCADE,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT favorite_exactly_one_target CHECK (
        num_nonnulls(destination_id, hotel_id, activity_id, transport_service_id) = 1
    )
);
CREATE UNIQUE INDEX favorites_destination_unique ON favorites(user_id, destination_id)
    WHERE destination_id IS NOT NULL;
CREATE UNIQUE INDEX favorites_hotel_unique ON favorites(user_id, hotel_id)
    WHERE hotel_id IS NOT NULL;
CREATE UNIQUE INDEX favorites_activity_unique ON favorites(user_id, activity_id)
    WHERE activity_id IS NOT NULL;
CREATE UNIQUE INDEX favorites_transport_unique ON favorites(user_id, transport_service_id)
    WHERE transport_service_id IS NOT NULL;
CREATE INDEX favorites_user_created_idx ON favorites(user_id, created_at DESC);

CREATE TABLE reviews (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    booking_id uuid NOT NULL,
    user_id uuid NOT NULL,
    rating smallint NOT NULL CHECK (rating BETWEEN 1 AND 5),
    title varchar(180),
    body text NOT NULL CHECK (length(btrim(body)) BETWEEN 1 AND 10000),
    moderation_status varchar(16) NOT NULL DEFAULT 'PENDING'
        CHECK (moderation_status IN ('PENDING', 'PUBLISHED', 'HIDDEN')),
    moderated_by_user_id uuid REFERENCES users(id) ON DELETE RESTRICT,
    moderated_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT review_booking_owner_fk FOREIGN KEY (booking_id, user_id)
        REFERENCES bookings(id, user_id) ON DELETE RESTRICT,
    CONSTRAINT review_one_per_booking UNIQUE (booking_id),
    CONSTRAINT review_moderation_pair CHECK (
        (moderated_by_user_id IS NULL) = (moderated_at IS NULL)
    )
);
CREATE INDEX reviews_user_created_idx ON reviews(user_id, created_at DESC);
CREATE INDEX reviews_public_booking_idx ON reviews(booking_id)
    WHERE moderation_status = 'PUBLISHED';
-- The reviewed hotel/activity/transport is derived from the booking subtype.
-- 50_invariants.sql requires a completed booking before accepting a review.
-- The API additionally authenticates the caller and checks moderation permissions.

CREATE TABLE notifications (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    notification_type varchar(60) NOT NULL,
    title varchar(220) NOT NULL,
    body text NOT NULL,
    payload jsonb NOT NULL DEFAULT '{}'::jsonb
        CHECK (jsonb_typeof(payload) = 'object'),
    source_event_key varchar(180),
    read_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT notification_read_time CHECK (read_at IS NULL OR read_at >= created_at)
);
CREATE INDEX notifications_inbox_idx ON notifications(user_id, created_at DESC);
CREATE INDEX notifications_unread_idx ON notifications(user_id, created_at DESC)
    WHERE read_at IS NULL;
CREATE UNIQUE INDEX notifications_event_unique ON notifications(user_id, source_event_key)
    WHERE source_event_key IS NOT NULL;

CREATE TABLE support_tickets (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    booking_id uuid,
    assigned_to_user_id uuid REFERENCES users(id) ON DELETE RESTRICT,
    subject varchar(220) NOT NULL CHECK (length(btrim(subject)) > 0),
    category varchar(32) NOT NULL DEFAULT 'GENERAL'
        CHECK (category IN ('GENERAL', 'BOOKING', 'PAYMENT', 'TRIP', 'ACCOUNT', 'TECHNICAL')),
    status varchar(24) NOT NULL DEFAULT 'OPEN'
        CHECK (status IN ('OPEN', 'WAITING_CUSTOMER', 'WAITING_AGENT', 'RESOLVED', 'CLOSED')),
    priority varchar(12) NOT NULL DEFAULT 'NORMAL'
        CHECK (priority IN ('LOW', 'NORMAL', 'HIGH', 'URGENT')),
    resolved_at timestamptz,
    closed_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT support_ticket_owner_unique UNIQUE (id, user_id),
    CONSTRAINT support_ticket_booking_owner_fk FOREIGN KEY (booking_id, user_id)
        REFERENCES bookings(id, user_id) ON DELETE RESTRICT,
    CONSTRAINT support_ticket_resolution CHECK (
        (status IN ('RESOLVED', 'CLOSED')) = (resolved_at IS NOT NULL)
    ),
    CONSTRAINT support_ticket_closed CHECK ((status = 'CLOSED') = (closed_at IS NOT NULL)),
    CONSTRAINT support_ticket_time_order CHECK (
        (resolved_at IS NULL OR resolved_at >= created_at)
        AND (closed_at IS NULL OR closed_at >= resolved_at)
    )
);
CREATE INDEX support_tickets_user_idx ON support_tickets(user_id, created_at DESC);
CREATE INDEX support_tickets_queue_idx ON support_tickets(status, priority, created_at);
CREATE INDEX support_tickets_assignee_idx ON support_tickets(assigned_to_user_id, status)
    WHERE assigned_to_user_id IS NOT NULL;

CREATE TABLE support_messages (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    ticket_id uuid NOT NULL,
    ticket_user_id uuid NOT NULL,
    author_user_id uuid REFERENCES users(id) ON DELETE RESTRICT,
    sender_role varchar(12) NOT NULL CHECK (sender_role IN ('CUSTOMER', 'AGENT', 'SYSTEM')),
    body text NOT NULL CHECK (length(btrim(body)) BETWEEN 1 AND 20000),
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT support_message_ticket_owner_fk FOREIGN KEY (ticket_id, ticket_user_id)
        REFERENCES support_tickets(id, user_id) ON DELETE RESTRICT,
    CONSTRAINT support_message_author_unique UNIQUE (id, author_user_id),
    CONSTRAINT support_message_sender CHECK (
        (sender_role = 'CUSTOMER' AND author_user_id IS NOT NULL AND author_user_id = ticket_user_id)
        OR (sender_role = 'AGENT' AND author_user_id IS NOT NULL)
        OR (sender_role = 'SYSTEM' AND author_user_id IS NULL)
    )
);
CREATE INDEX support_messages_thread_idx ON support_messages(ticket_id, created_at, id);
-- AGENT authorization is checked against user roles by the API.

CREATE TABLE support_attachments (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    message_id uuid NOT NULL,
    media_asset_id uuid NOT NULL,
    uploader_user_id uuid NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT support_attachment_message_author_fk FOREIGN KEY (message_id, uploader_user_id)
        REFERENCES support_messages(id, author_user_id) ON DELETE RESTRICT,
    CONSTRAINT support_attachment_media_owner_fk FOREIGN KEY (media_asset_id, uploader_user_id)
        REFERENCES media_assets(id, owner_user_id) ON DELETE RESTRICT,
    CONSTRAINT support_attachment_unique UNIQUE (message_id, media_asset_id)
);
CREATE INDEX support_attachments_asset_idx ON support_attachments(media_asset_id);

CREATE TABLE newsletter_subscriptions (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id uuid REFERENCES users(id) ON DELETE SET NULL,
    email varchar(254) NOT NULL CHECK (email = btrim(email) AND position('@' IN email) > 1),
    locale varchar(10) NOT NULL DEFAULT 'ar',
    status varchar(16) NOT NULL DEFAULT 'PENDING'
        CHECK (status IN ('PENDING', 'ACTIVE', 'UNSUBSCRIBED')),
    confirmation_token_hash varchar(64)
        CHECK (confirmation_token_hash IS NULL OR confirmation_token_hash ~ '^[0-9a-f]{64}$'),
    unsubscribe_token_hash varchar(64)
        CHECK (unsubscribe_token_hash IS NULL OR unsubscribe_token_hash ~ '^[0-9a-f]{64}$'),
    confirmation_expires_at timestamptz,
    consent_accepted_at timestamptz,
    confirmed_at timestamptz,
    unsubscribed_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT newsletter_confirmation_time CHECK (
        confirmed_at IS NULL OR confirmed_at >= created_at
    ),
    CONSTRAINT newsletter_active_confirmed CHECK (status <> 'ACTIVE' OR confirmed_at IS NOT NULL),
    CONSTRAINT newsletter_unsubscribed_time CHECK (
        (status = 'UNSUBSCRIBED') = (unsubscribed_at IS NOT NULL)
    ),
    CONSTRAINT newsletter_confirmation_expiry CHECK (
        (confirmation_token_hash IS NULL) = (confirmation_expires_at IS NULL)
    )
);
CREATE UNIQUE INDEX newsletter_email_unique ON newsletter_subscriptions(lower(email));
CREATE UNIQUE INDEX newsletter_confirmation_hash_unique
    ON newsletter_subscriptions(confirmation_token_hash) WHERE confirmation_token_hash IS NOT NULL;
CREATE UNIQUE INDEX newsletter_unsubscribe_hash_unique
    ON newsletter_subscriptions(unsubscribe_token_hash) WHERE unsubscribe_token_hash IS NOT NULL;
CREATE INDEX newsletter_delivery_idx ON newsletter_subscriptions(status, locale)
    WHERE status = 'ACTIVE';

CREATE TABLE content_pages (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    slug varchar(80) NOT NULL CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
    locale varchar(10) NOT NULL DEFAULT 'ar',
    title varchar(220) NOT NULL,
    body_markdown text NOT NULL,
    publication_status varchar(16) NOT NULL DEFAULT 'DRAFT'
        CHECK (publication_status IN ('DRAFT', 'PUBLISHED', 'ARCHIVED')),
    authored_by_user_id uuid REFERENCES users(id) ON DELETE RESTRICT,
    published_at timestamptz,
    revision integer NOT NULL DEFAULT 1 CHECK (revision > 0),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT content_page_locale_unique UNIQUE (slug, locale),
    CONSTRAINT content_page_published CHECK (
        publication_status <> 'PUBLISHED' OR published_at IS NOT NULL
    )
);
CREATE INDEX content_pages_public_idx ON content_pages(slug, locale)
    WHERE publication_status = 'PUBLISHED';
-- Store content, not unsanitized rendered HTML. Sanitize on the rendering boundary.

CREATE TABLE faq_entries (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    locale varchar(10) NOT NULL DEFAULT 'ar',
    category varchar(60) NOT NULL DEFAULT 'GENERAL',
    question varchar(600) NOT NULL CHECK (length(btrim(question)) > 0),
    answer_markdown text NOT NULL CHECK (length(btrim(answer_markdown)) > 0),
    sort_order integer NOT NULL DEFAULT 0 CHECK (sort_order >= 0),
    is_published boolean NOT NULL DEFAULT false,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT faq_question_locale_unique UNIQUE (locale, question)
);
CREATE INDEX faq_entries_public_idx ON faq_entries(locale, category, sort_order)
    WHERE is_published;


-- Transactional invariants. Functions are invoker-rights; API authorization remains required.
CREATE FUNCTION touch_updated_at() RETURNS trigger LANGUAGE plpgsql
SET search_path = travora, pg_temp AS $$
BEGIN NEW.updated_at := now(); RETURN NEW; END;
$$;
DO $$
DECLARE t record;
BEGIN
  FOR t IN SELECT table_name FROM information_schema.columns
           WHERE table_schema='travora' AND column_name='updated_at' LOOP
    EXECUTE format('CREATE TRIGGER touch_updated_at BEFORE UPDATE ON travora.%I FOR EACH ROW EXECUTE FUNCTION travora.touch_updated_at()', t.table_name);
  END LOOP;
END;
$$;

ALTER TABLE trip_documents ADD CONSTRAINT trip_documents_booking_owner_fk
  FOREIGN KEY (booking_id,owner_user_id) REFERENCES bookings(id,user_id) ON DELETE RESTRICT;

CREATE FUNCTION guard_booking_lifecycle() RETURNS trigger LANGUAGE plpgsql
SET search_path = travora, pg_temp AS $$
DECLARE captured numeric; reserved_refunds numeric; new_total numeric;
BEGIN
  IF TG_OP='DELETE' THEN
    RAISE EXCEPTION 'Booking history must be retained; cancel or expire the booking' USING ERRCODE='23514';
  END IF;
  IF TG_OP='INSERT' AND NEW.status NOT IN ('draft','pending_payment') THEN
    RAISE EXCEPTION 'A booking must start as draft or pending_payment' USING ERRCODE='23514';
  END IF;
  IF TG_OP='UPDATE' THEN
    IF ROW(NEW.id,NEW.user_id,NEW.kind,NEW.reference) IS DISTINCT FROM ROW(OLD.id,OLD.user_id,OLD.kind,OLD.reference) THEN
      RAISE EXCEPTION 'Booking identity is immutable' USING ERRCODE='23514';
    END IF;
    IF OLD.status<>'draft' AND ROW(NEW.trip_id,NEW.currency,NEW.subtotal_minor,NEW.tax_minor,NEW.fee_minor,
      NEW.discount_minor,NEW.payment_terms,NEW.service_title_snapshot,NEW.cancellation_policy_snapshot)
      IS DISTINCT FROM ROW(OLD.trip_id,OLD.currency,OLD.subtotal_minor,OLD.tax_minor,OLD.fee_minor,
      OLD.discount_minor,OLD.payment_terms,OLD.service_title_snapshot,OLD.cancellation_policy_snapshot) THEN
      RAISE EXCEPTION 'Reserved booking amounts and service snapshots are immutable' USING ERRCODE='23514';
    END IF;
    IF NEW.status<>OLD.status AND NOT (
      (OLD.status='draft' AND NEW.status IN ('pending_payment','cancelled','expired')) OR
      (OLD.status='pending_payment' AND NEW.status IN ('confirmed','cancelled','expired')) OR
      (OLD.status='confirmed' AND NEW.status IN ('completed','cancelled'))
    ) THEN RAISE EXCEPTION 'Invalid booking transition: % -> %',OLD.status,NEW.status USING ERRCODE='23514'; END IF;
    IF OLD.status<>'draft' AND NEW.hold_expires_at IS DISTINCT FROM OLD.hold_expires_at THEN
      RAISE EXCEPTION 'Existing booking hold deadline is immutable' USING ERRCODE='23514';
    END IF;
  END IF;
  IF NEW.status='pending_payment' AND (TG_OP='INSERT' OR OLD.status<>'pending_payment')
     AND NEW.hold_expires_at IS NOT NULL AND NEW.hold_expires_at<=now() THEN
    RAISE EXCEPTION 'A new or updated pending hold must be unexpired' USING ERRCODE='23514';
  END IF;
  IF NEW.status='confirmed' AND (TG_OP='INSERT' OR OLD.status<>'confirmed') THEN
    IF NEW.hold_expires_at<=now() THEN
      RAISE EXCEPTION 'Expired holds cannot be confirmed' USING ERRCODE='23514';
    END IF;
    new_total := NEW.subtotal_minor::numeric+NEW.tax_minor+NEW.fee_minor-NEW.discount_minor;
    SELECT COALESCE(sum(amount_minor),0) INTO captured FROM payment_attempts
      WHERE booking_id=NEW.id AND status='succeeded';
    SELECT COALESCE(sum(r.amount_minor),0) INTO reserved_refunds FROM refunds r
      JOIN payment_attempts p ON p.id=r.payment_attempt_id
      WHERE p.booking_id=NEW.id AND r.status IN ('requested','processing','succeeded');
    IF NEW.payment_terms='prepaid' AND captured-reserved_refunds<new_total THEN
      RAISE EXCEPTION 'Prepaid booking needs successful payment before confirmation' USING ERRCODE='23514';
    END IF;
    NEW.confirmed_at:=COALESCE(NEW.confirmed_at,now());
  END IF;
  IF NEW.status='cancelled' THEN NEW.cancelled_at:=COALESCE(NEW.cancelled_at,now()); END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER booking_lifecycle BEFORE INSERT OR UPDATE OR DELETE ON bookings
FOR EACH ROW EXECUTE FUNCTION guard_booking_lifecycle();

CREATE FUNCTION guard_booking_detail() RETURNS trigger LANGUAGE plpgsql
SET search_path = travora, pg_temp AS $$
DECLARE parent bookings; bid uuid;
BEGIN
  bid:=CASE WHEN TG_OP='DELETE' THEN OLD.booking_id ELSE NEW.booking_id END;
  SELECT * INTO parent FROM bookings WHERE id=bid FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Booking parent is missing' USING ERRCODE='23503'; END IF;
  IF TG_OP='UPDATE' AND NEW.booking_id IS DISTINCT FROM OLD.booking_id THEN
    RAISE EXCEPTION 'Detail booking identity is immutable' USING ERRCODE='23514';
  END IF;
  IF TG_OP IN ('UPDATE','DELETE') AND parent.status<>'draft' THEN
    RAISE EXCEPTION 'Reserved service details are immutable' USING ERRCODE='23514';
  END IF;
  IF TG_OP='INSERT' AND parent.status NOT IN ('draft','pending_payment') THEN
    RAISE EXCEPTION 'Cannot add details to a terminal or confirmed booking' USING ERRCODE='23514';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER immutable_hotel_detail BEFORE INSERT OR UPDATE OR DELETE ON hotel_booking_details FOR EACH ROW EXECUTE FUNCTION guard_booking_detail();
CREATE TRIGGER immutable_activity_detail BEFORE INSERT OR UPDATE OR DELETE ON activity_booking_details FOR EACH ROW EXECUTE FUNCTION guard_booking_detail();
CREATE TRIGGER immutable_transport_detail BEFORE INSERT OR UPDATE OR DELETE ON transport_booking_details FOR EACH ROW EXECUTE FUNCTION guard_booking_detail();

-- Inventory counters are a materialized ledger maintained only through allocations.
CREATE FUNCTION guard_inventory_counters() RETURNS trigger LANGUAGE plpgsql
SET search_path = travora, pg_temp AS $$
DECLARE h text; b text;
BEGIN
  h:=CASE WHEN TG_TABLE_NAME='room_inventory' THEN 'held_units' ELSE 'held_count' END;
  b:=CASE WHEN TG_TABLE_NAME='room_inventory' THEN 'booked_units' ELSE 'booked_count' END;
  IF TG_OP='INSERT' AND ((to_jsonb(NEW)->>h)::integer<>0 OR (to_jsonb(NEW)->>b)::integer<>0) THEN
    RAISE EXCEPTION 'New inventory counters must start at zero' USING ERRCODE='23514';
  END IF;
  IF TG_OP='UPDATE' AND pg_trigger_depth()<=1 AND
    ROW(to_jsonb(NEW)->h,to_jsonb(NEW)->b) IS DISTINCT FROM ROW(to_jsonb(OLD)->h,to_jsonb(OLD)->b) THEN
    RAISE EXCEPTION 'Inventory counters are maintained by allocation triggers' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER inventory_counter_guard BEFORE INSERT OR UPDATE ON room_inventory FOR EACH ROW EXECUTE FUNCTION guard_inventory_counters();
CREATE TRIGGER inventory_counter_guard BEFORE INSERT OR UPDATE ON activity_sessions FOR EACH ROW EXECUTE FUNCTION guard_inventory_counters();
CREATE TRIGGER inventory_counter_guard BEFORE INSERT OR UPDATE ON transport_offers FOR EACH ROW EXECUTE FUNCTION guard_inventory_counters();

CREATE FUNCTION maintain_allocation() RETURNS trigger LANGUAGE plpgsql
SET search_path = travora, pg_temp AS $$
DECLARE parent bookings; bid uuid; old_h integer:=0; old_b integer:=0;
  new_h integer:=0; new_b integer:=0; hd hotel_booking_details; rt room_types; ad activity_booking_details;
  td transport_booking_details; ri room_inventory; act activity_sessions; tr transport_offers;
  svc transport_services;
BEGIN
  bid:=CASE WHEN TG_OP='DELETE' THEN OLD.booking_id ELSE NEW.booking_id END;
  SELECT * INTO parent FROM bookings WHERE id=bid FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Allocation booking is missing' USING ERRCODE='23503'; END IF;
  IF TG_OP='DELETE' THEN
    RAISE EXCEPTION 'Release allocations by changing booking status; retain ledger rows' USING ERRCODE='23514';
  END IF;
  IF TG_OP='UPDATE' THEN
    IF (to_jsonb(NEW)-'state') IS DISTINCT FROM (to_jsonb(OLD)-'state') THEN
      RAISE EXCEPTION 'Allocation identity, quantity and quote are immutable' USING ERRCODE='23514';
    END IF;
    IF NEW.state<>OLD.state AND NOT (
      (OLD.state='held' AND NEW.state IN ('committed','released')) OR
      (OLD.state='committed' AND NEW.state='released')
    ) THEN RAISE EXCEPTION 'Invalid allocation state transition' USING ERRCODE='23514'; END IF;
    old_h:=CASE WHEN OLD.state='held' THEN OLD.units ELSE 0 END;
    old_b:=CASE WHEN OLD.state='committed' THEN OLD.units ELSE 0 END;
  ELSE
    IF NEW.state<>'held' THEN RAISE EXCEPTION 'An allocation starts held' USING ERRCODE='23514'; END IF;
  END IF;
  IF NEW.state='held' AND (parent.status<>'pending_payment' OR parent.hold_expires_at<=now()) THEN
    RAISE EXCEPTION 'Held allocation needs an unexpired pending booking' USING ERRCODE='23514';
  END IF;
  IF NEW.state='committed' AND parent.status NOT IN ('confirmed','completed') THEN
    RAISE EXCEPTION 'Committed allocation needs confirmed booking' USING ERRCODE='23514';
  END IF;
  IF NEW.state='released' AND parent.status NOT IN ('cancelled','expired') THEN
    RAISE EXCEPTION 'Release requires a cancelled or expired booking' USING ERRCODE='23514';
  END IF;
  new_h:=CASE WHEN NEW.state='held' THEN NEW.units ELSE 0 END;
  new_b:=CASE WHEN NEW.state='committed' THEN NEW.units ELSE 0 END;
  IF TG_TABLE_NAME='room_night_allocations' THEN
    SELECT * INTO hd FROM hotel_booking_details WHERE booking_id=bid;
    IF NEW.room_type_id<>hd.room_type_id OR NEW.inventory_date<hd.check_in OR NEW.inventory_date>=hd.check_out OR NEW.units<>hd.room_count THEN
      RAISE EXCEPTION 'Room night must match booking room, dates and quantity' USING ERRCODE='23514';
    END IF;
    IF TG_OP='INSERT' THEN
      SELECT * INTO rt FROM room_types WHERE id=hd.room_type_id;
      IF hd.adult_count::bigint>rt.max_adults::bigint*hd.room_count OR
         hd.child_count::bigint>rt.max_children::bigint*hd.room_count OR
         hd.adult_count::bigint+hd.child_count>rt.max_occupancy::bigint*hd.room_count THEN
        RAISE EXCEPTION 'Guest counts exceed the selected rooms occupancy' USING ERRCODE='23514';
      END IF;
    END IF;
    SELECT * INTO ri FROM room_inventory WHERE room_type_id=NEW.room_type_id AND inventory_date=NEW.inventory_date FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Room night inventory is missing' USING ERRCODE='23503'; END IF;
    IF TG_OP='INSERT' AND NEW.unit_price_minor<>ri.price_minor THEN
      RAISE EXCEPTION 'Room quote must match current dated inventory' USING ERRCODE='23514';
    END IF;
    IF new_h+new_b>old_h+old_b AND ri.is_closed THEN
      RAISE EXCEPTION 'Room inventory is closed' USING ERRCODE='23514';
    END IF;
    UPDATE room_inventory SET held_units=held_units+new_h-old_h,booked_units=booked_units+new_b-old_b
      WHERE room_type_id=NEW.room_type_id AND inventory_date=NEW.inventory_date;
  ELSIF TG_TABLE_NAME='activity_allocations' THEN
    SELECT * INTO ad FROM activity_booking_details WHERE booking_id=bid;
    IF NEW.session_id<>ad.session_id OR NEW.units<>ad.participant_count THEN
      RAISE EXCEPTION 'Activity allocation must match session and participants' USING ERRCODE='23514';
    END IF;
    SELECT * INTO act FROM activity_sessions WHERE id=NEW.session_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Activity session is missing' USING ERRCODE='23503'; END IF;
    IF TG_OP='INSERT' AND (ad.unit_price_minor<>act.price_minor OR ad.service_starts_at_snapshot<>act.starts_at OR ad.service_ends_at_snapshot<>act.ends_at) THEN
      RAISE EXCEPTION 'Activity quote and times must match selected session' USING ERRCODE='23514';
    END IF;
    IF (new_h+new_b>old_h+old_b OR (TG_OP='UPDATE' AND OLD.state='held' AND NEW.state='committed'))
       AND act.status<>'scheduled' THEN
      RAISE EXCEPTION 'Activity session is unavailable' USING ERRCODE='23514';
    END IF;
    UPDATE activity_sessions SET held_count=held_count+new_h-old_h,booked_count=booked_count+new_b-old_b WHERE id=NEW.session_id;
  ELSE
    SELECT * INTO td FROM transport_booking_details WHERE booking_id=bid;
    SELECT * INTO svc FROM transport_services WHERE id=td.transport_service_id;
    IF NEW.offer_id<>td.offer_id OR NEW.units<>1 OR
       (TG_OP='INSERT' AND (td.passenger_count>svc.seats OR td.luggage_count>svc.luggage_capacity)) THEN
      RAISE EXCEPTION 'Vehicle allocation or passenger/luggage capacity is invalid' USING ERRCODE='23514';
    END IF;
    SELECT * INTO tr FROM transport_offers WHERE id=NEW.offer_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Transport offer is missing' USING ERRCODE='23503'; END IF;
    IF TG_OP='INSERT' AND (td.unit_price_minor<>tr.price_minor OR td.pickup_at_snapshot<>tr.departure_at) THEN
      RAISE EXCEPTION 'Transport quote and pickup time must match selected offer' USING ERRCODE='23514';
    END IF;
    IF (new_h+new_b>old_h+old_b OR (TG_OP='UPDATE' AND OLD.state='held' AND NEW.state='committed'))
       AND tr.status<>'scheduled' THEN
      RAISE EXCEPTION 'Transport offer is unavailable' USING ERRCODE='23514';
    END IF;
    UPDATE transport_offers SET held_count=held_count+new_h-old_h,booked_count=booked_count+new_b-old_b WHERE id=NEW.offer_id;
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER room_allocation_ledger BEFORE INSERT OR UPDATE OR DELETE ON room_night_allocations FOR EACH ROW EXECUTE FUNCTION maintain_allocation();
CREATE TRIGGER activity_allocation_ledger BEFORE INSERT OR UPDATE OR DELETE ON activity_allocations FOR EACH ROW EXECUTE FUNCTION maintain_allocation();
CREATE TRIGGER transport_allocation_ledger BEFORE INSERT OR UPDATE OR DELETE ON transport_allocations FOR EACH ROW EXECUTE FUNCTION maintain_allocation();

CREATE FUNCTION apply_booking_status() RETURNS trigger LANGUAGE plpgsql
SET search_path = travora, pg_temp AS $$
BEGIN
  IF TG_OP='INSERT' OR NEW.status IS DISTINCT FROM OLD.status THEN
    INSERT INTO booking_status_history(booking_id,from_status,to_status)
      VALUES(NEW.id,CASE WHEN TG_OP='INSERT' THEN NULL ELSE OLD.status END,NEW.status);
    IF NEW.status='confirmed' THEN
      UPDATE room_night_allocations SET state='committed' WHERE booking_id=NEW.id AND state='held';
      UPDATE activity_allocations SET state='committed' WHERE booking_id=NEW.id AND state='held';
      UPDATE transport_allocations SET state='committed' WHERE booking_id=NEW.id AND state='held';
    ELSIF NEW.status IN ('cancelled','expired') THEN
      UPDATE room_night_allocations SET state='released' WHERE booking_id=NEW.id AND state<>'released';
      UPDATE activity_allocations SET state='released' WHERE booking_id=NEW.id AND state<>'released';
      UPDATE transport_allocations SET state='released' WHERE booking_id=NEW.id AND state<>'released';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER booking_status_effects AFTER INSERT OR UPDATE ON bookings FOR EACH ROW EXECUTE FUNCTION apply_booking_status();

CREATE FUNCTION validate_booking_complete() RETURNS trigger LANGUAGE plpgsql
SET search_path = travora, pg_temp AS $$
DECLARE bid uuid; parent bookings; subtype_count integer; matching boolean;
  hd hotel_booking_details; ad activity_booking_details; td transport_booking_details;
  active_count bigint; line_total numeric; desired text;
BEGIN
  IF TG_TABLE_NAME='bookings' THEN
    bid:=COALESCE(NEW.id,OLD.id);
  ELSE
    bid:=COALESCE(NEW.booking_id,OLD.booking_id);
  END IF;
  SELECT * INTO parent FROM bookings WHERE id=bid;
  IF NOT FOUND THEN RETURN NULL; END IF;
  SELECT (EXISTS(SELECT 1 FROM hotel_booking_details WHERE booking_id=bid))::integer+
    (EXISTS(SELECT 1 FROM activity_booking_details WHERE booking_id=bid))::integer+
    (EXISTS(SELECT 1 FROM transport_booking_details WHERE booking_id=bid))::integer INTO subtype_count;
  matching:=CASE parent.kind WHEN 'HOTEL' THEN EXISTS(SELECT 1 FROM hotel_booking_details WHERE booking_id=bid)
    WHEN 'ACTIVITY' THEN EXISTS(SELECT 1 FROM activity_booking_details WHERE booking_id=bid)
    ELSE EXISTS(SELECT 1 FROM transport_booking_details WHERE booking_id=bid) END;
  IF subtype_count<>1 OR NOT matching THEN
    RAISE EXCEPTION 'Booking % needs exactly one matching service subtype',bid USING ERRCODE='23514';
  END IF;
  IF parent.status IN ('draft','cancelled','expired') THEN
    IF EXISTS(SELECT 1 FROM room_night_allocations WHERE booking_id=bid AND state<>'released') OR
       EXISTS(SELECT 1 FROM activity_allocations WHERE booking_id=bid AND state<>'released') OR
       EXISTS(SELECT 1 FROM transport_allocations WHERE booking_id=bid AND state<>'released') THEN
      RAISE EXCEPTION 'Draft/cancelled/expired booking cannot retain active allocations' USING ERRCODE='23514';
    END IF;
    RETURN NULL;
  END IF;
  desired:=CASE WHEN parent.status='pending_payment' THEN 'held' ELSE 'committed' END;
  IF parent.kind='HOTEL' THEN
    SELECT * INTO hd FROM hotel_booking_details WHERE booking_id=bid;
    SELECT count(*),COALESCE(sum(units::numeric*unit_price_minor),0) INTO active_count,line_total
      FROM room_night_allocations WHERE booking_id=bid AND state=desired;
    IF active_count<>(hd.check_out-hd.check_in) THEN
      RAISE EXCEPTION 'Hotel booking must allocate every night, excluding checkout date' USING ERRCODE='23514';
    END IF;
  ELSIF parent.kind='ACTIVITY' THEN
    SELECT * INTO ad FROM activity_booking_details WHERE booking_id=bid;
    SELECT count(*) INTO active_count FROM activity_allocations WHERE booking_id=bid AND state=desired;
    line_total:=ad.unit_price_minor::numeric*ad.participant_count;
    IF active_count<>1 THEN RAISE EXCEPTION 'Activity booking needs one participant allocation' USING ERRCODE='23514'; END IF;
  ELSE
    SELECT * INTO td FROM transport_booking_details WHERE booking_id=bid;
    SELECT count(*) INTO active_count FROM transport_allocations WHERE booking_id=bid AND state=desired;
    line_total:=td.unit_price_minor;
    IF active_count<>1 THEN RAISE EXCEPTION 'Transport booking needs one vehicle allocation' USING ERRCODE='23514'; END IF;
  END IF;
  IF line_total<>parent.subtotal_minor THEN
    RAISE EXCEPTION 'Booking subtotal must equal frozen service line amounts' USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END;
$$;
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['bookings','hotel_booking_details','activity_booking_details','transport_booking_details',
    'room_night_allocations','activity_allocations','transport_allocations'] LOOP
    EXECUTE format('CREATE CONSTRAINT TRIGGER booking_complete AFTER INSERT OR UPDATE OR DELETE ON travora.%I DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION travora.validate_booking_complete()',t);
  END LOOP;
END;
$$;

CREATE FUNCTION guard_completed_review() RETURNS trigger LANGUAGE plpgsql
SET search_path = travora, pg_temp AS $$
DECLARE s text;
BEGIN
  SELECT status INTO s FROM bookings WHERE id=NEW.booking_id FOR UPDATE;
  IF s IS DISTINCT FROM 'completed' THEN
    RAISE EXCEPTION 'Only completed owned bookings may be reviewed' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER review_completed_booking BEFORE INSERT OR UPDATE ON reviews FOR EACH ROW EXECUTE FUNCTION guard_completed_review();

COMMENT ON FUNCTION maintain_allocation() IS 'Locks booking first, then dated inventory; all held/booked changes and booking status changes roll back together. The API acquires room nights in ascending date order and retries deadlock/serialization failures.';
COMMENT ON FUNCTION validate_booking_complete() IS 'Deferred until commit, so order header, exactly one service detail and all inventory allocations must be written in one transaction.';
COMMENT ON COLUMN bookings.hold_expires_at IS 'The application worker expires pending_payment bookings in batches. Time passage alone does not release inventory; status=expired releases allocations transactionally.';


-- Financial state and amount guards. Run after 30_bookings.sql and 50_invariants.sql.
-- Runtime transactions should lock the booking before updating payment/refund
-- rows. A row-level BEFORE UPDATE trigger cannot undo locks already acquired by
-- its caller. Retry a whole transaction on 40P01 / 40001, never one statement.

CREATE FUNCTION guard_payment_attempt()
RETURNS trigger
LANGUAGE plpgsql
VOLATILE
SET search_path = travora, pg_temp
AS $$
DECLARE
    v_booking bookings%ROWTYPE;
    v_captured_minor numeric;
    v_new_capture boolean;
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'Payment attempt history cannot be deleted; cancel an unsuccessful attempt instead'
            USING ERRCODE = '23514', CONSTRAINT = 'payment_attempts_history_preserved';
    END IF;

    IF TG_OP = 'UPDATE' THEN
        IF ROW(NEW.id, NEW.booking_id, NEW.currency, NEW.method, NEW.provider,
               NEW.idempotency_key, NEW.amount_minor, NEW.created_at)
           IS DISTINCT FROM
           ROW(OLD.id, OLD.booking_id, OLD.currency, OLD.method, OLD.provider,
               OLD.idempotency_key, OLD.amount_minor, OLD.created_at) THEN
            RAISE EXCEPTION 'Payment amount, booking, currency, method, provider, idempotency key, identity and creation time are immutable'
                USING ERRCODE = '23514', CONSTRAINT = 'payment_attempts_identity_immutable';
        END IF;

        IF OLD.provider_payment_id IS NOT NULL AND NEW.provider_payment_id IS DISTINCT FROM OLD.provider_payment_id THEN
            RAISE EXCEPTION 'An assigned provider payment identifier cannot be changed'
                USING ERRCODE = '23514', CONSTRAINT = 'payment_attempts_provider_key_immutable';
        END IF;

        IF NEW.status IS DISTINCT FROM OLD.status AND NOT (
            (OLD.status = 'pending' AND NEW.status IN ('processing', 'authorized', 'succeeded', 'failed', 'cancelled')) OR
            (OLD.status = 'processing' AND NEW.status IN ('authorized', 'succeeded', 'failed', 'cancelled')) OR
            (OLD.status = 'authorized' AND NEW.status IN ('succeeded', 'failed', 'cancelled'))
        ) THEN
            RAISE EXCEPTION 'Invalid payment attempt transition: % -> %; retry a failed payment with a new attempt', OLD.status, NEW.status
                USING ERRCODE = '23514', CONSTRAINT = 'payment_attempts_transition_valid';
        END IF;

        IF OLD.status = 'succeeded' THEN
            IF NEW.succeeded_at IS DISTINCT FROM OLD.succeeded_at OR
               NEW.provider_payment_id IS DISTINCT FROM OLD.provider_payment_id THEN
                RAISE EXCEPTION 'A successful payment timestamp and provider identifier are immutable'
                    USING ERRCODE = '23514', CONSTRAINT = 'payment_attempts_success_immutable';
            END IF;
            -- An idempotent webhook touching an already captured row is not a
            -- new capture, even if the booking was subsequently cancelled.
            RETURN NEW;
        END IF;
    END IF;

    IF NEW.status <> 'succeeded' AND NEW.succeeded_at IS NOT NULL THEN
        RAISE EXCEPTION 'Only a succeeded payment can carry a success timestamp'
            USING ERRCODE = '23514', CONSTRAINT = 'payment_attempts_success_timestamp_valid';
    END IF;

    IF TG_OP = 'INSERT' THEN
        v_new_capture := NEW.status = 'succeeded';
    ELSE
        v_new_capture := NEW.status = 'succeeded' AND OLD.status <> 'succeeded';
    END IF;

    -- Booking first: the physical row-version update both acquires its lock
    -- and forces stale REPEATABLE READ transactions to retry with 40001.
    -- A lock-only SELECT would not refresh their aggregate snapshot.
    UPDATE bookings AS b SET updated_at = b.updated_at
    WHERE b.id = NEW.booking_id RETURNING b.* INTO v_booking;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Payment booking does not exist: %', NEW.booking_id
            USING ERRCODE = '23514', CONSTRAINT = 'payment_attempts_booking_required';
    END IF;

    IF v_new_capture THEN
        IF v_booking.status NOT IN ('pending_payment', 'confirmed', 'completed') THEN
            RAISE EXCEPTION 'Cannot capture payment for a % booking', v_booking.status
                USING ERRCODE = '23514', CONSTRAINT = 'payment_attempts_capture_booking_active';
        END IF;
        IF v_booking.status = 'pending_payment' AND v_booking.hold_expires_at <= now() THEN
            RAISE EXCEPTION 'Cannot capture payment after the booking hold expired'
                USING ERRCODE = '23514', CONSTRAINT = 'payment_attempts_capture_hold_valid';
        END IF;

        SELECT COALESCE(SUM(amount_minor), 0) INTO v_captured_minor
        FROM payment_attempts
        WHERE booking_id = NEW.booking_id AND status = 'succeeded' AND id <> NEW.id;

        IF v_captured_minor + NEW.amount_minor::numeric > v_booking.total_minor::numeric THEN
            RAISE EXCEPTION 'Payment capture would exceed the booking total: already captured %, attempted %, total %',
                v_captured_minor, NEW.amount_minor, v_booking.total_minor
                USING ERRCODE = '23514', CONSTRAINT = 'payment_attempts_capture_within_total';
        END IF;
        NEW.succeeded_at := COALESCE(NEW.succeeded_at, now());
    END IF;

    RETURN NEW;
END;
$$;

CREATE TRIGGER payment_attempts_guard
BEFORE INSERT OR UPDATE OR DELETE ON payment_attempts
FOR EACH ROW EXECUTE FUNCTION guard_payment_attempt();

CREATE FUNCTION guard_refund()
RETURNS trigger
LANGUAGE plpgsql
VOLATILE
SET search_path = travora, pg_temp
AS $$
DECLARE
    v_booking_id uuid;
    v_payment payment_attempts%ROWTYPE;
    v_reserved_minor numeric;
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'Refund history cannot be deleted; cancel an unsuccessful refund instead'
            USING ERRCODE = '23514', CONSTRAINT = 'refunds_history_preserved';
    END IF;

    IF TG_OP = 'UPDATE' THEN
        IF ROW(NEW.id, NEW.payment_attempt_id, NEW.currency, NEW.amount_minor,
               NEW.idempotency_key, NEW.created_at)
           IS DISTINCT FROM
           ROW(OLD.id, OLD.payment_attempt_id, OLD.currency, OLD.amount_minor,
               OLD.idempotency_key, OLD.created_at) THEN
            RAISE EXCEPTION 'Refund amount, payment, currency, idempotency key, identity and creation time are immutable'
                USING ERRCODE = '23514', CONSTRAINT = 'refunds_identity_immutable';
        END IF;

        IF OLD.provider_refund_id IS NOT NULL AND NEW.provider_refund_id IS DISTINCT FROM OLD.provider_refund_id THEN
            RAISE EXCEPTION 'An assigned provider refund identifier cannot be changed'
                USING ERRCODE = '23514', CONSTRAINT = 'refunds_provider_key_immutable';
        END IF;

        IF NEW.status IS DISTINCT FROM OLD.status AND NOT (
            (OLD.status = 'requested' AND NEW.status IN ('processing', 'succeeded', 'failed', 'cancelled')) OR
            (OLD.status = 'processing' AND NEW.status IN ('succeeded', 'failed', 'cancelled'))
        ) THEN
            RAISE EXCEPTION 'Invalid refund transition: % -> %; retry a failed refund with a new request', OLD.status, NEW.status
                USING ERRCODE = '23514', CONSTRAINT = 'refunds_transition_valid';
        END IF;

        IF OLD.status = 'succeeded' THEN
            IF NEW.succeeded_at IS DISTINCT FROM OLD.succeeded_at OR
               NEW.provider_refund_id IS DISTINCT FROM OLD.provider_refund_id THEN
                RAISE EXCEPTION 'A successful refund timestamp and provider identifier are immutable'
                    USING ERRCODE = '23514', CONSTRAINT = 'refunds_success_immutable';
            END IF;
            RETURN NEW;
        END IF;
    END IF;

    IF NEW.status <> 'succeeded' AND NEW.succeeded_at IS NOT NULL THEN
        RAISE EXCEPTION 'Only a succeeded refund can carry a success timestamp'
            USING ERRCODE = '23514', CONSTRAINT = 'refunds_success_timestamp_valid';
    END IF;

    -- Read the immutable parent identifier without taking a payment row lock.
    SELECT booking_id INTO v_booking_id FROM payment_attempts WHERE id = NEW.payment_attempt_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Refund payment attempt does not exist: %', NEW.payment_attempt_id
            USING ERRCODE = '23514', CONSTRAINT = 'refunds_payment_required';
    END IF;

    -- The lock order is booking, payment, then the reserved-refund aggregate.
    -- Physically version the booking to protect REPEATABLE READ as well.
    UPDATE bookings SET updated_at = updated_at WHERE id = v_booking_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Refund booking does not exist: %', v_booking_id
            USING ERRCODE = '23514', CONSTRAINT = 'refunds_booking_required';
    END IF;
    SELECT * INTO v_payment FROM payment_attempts WHERE id = NEW.payment_attempt_id FOR UPDATE;

    IF v_payment.status <> 'succeeded' THEN
        RAISE EXCEPTION 'A refund requires a succeeded payment attempt'
            USING ERRCODE = '23514', CONSTRAINT = 'refunds_payment_succeeded';
    END IF;

    IF NEW.status IN ('requested', 'processing', 'succeeded') THEN
        SELECT COALESCE(SUM(amount_minor), 0) INTO v_reserved_minor
        FROM refunds
        WHERE payment_attempt_id = NEW.payment_attempt_id
          AND status IN ('requested', 'processing', 'succeeded')
          AND id <> NEW.id;

        IF v_reserved_minor + NEW.amount_minor::numeric > v_payment.amount_minor::numeric THEN
            RAISE EXCEPTION 'Refund requests would exceed the captured payment: already reserved %, attempted %, captured %',
                v_reserved_minor, NEW.amount_minor, v_payment.amount_minor
                USING ERRCODE = '23514', CONSTRAINT = 'refunds_within_capture';
        END IF;
    END IF;

    IF NEW.status = 'succeeded' THEN
        NEW.succeeded_at := COALESCE(NEW.succeeded_at, now());
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER refunds_guard
BEFORE INSERT OR UPDATE OR DELETE ON refunds
FOR EACH ROW EXECUTE FUNCTION guard_refund();

COMMENT ON FUNCTION guard_payment_attempt() IS 'Preserves immutable attempt identity and terminal states, versions/locks the booking before aggregate capture checks, and rejects expired/cancelled captures and overcapture. Lock booking before financial UPDATE statements; retry the transaction on deadlock/serialization failure.';
COMMENT ON FUNCTION guard_refund() IS 'Preserves refund history and immutable identity, versions/locks booking then locks successful payment, and reserves requested/processing/succeeded refunds within the captured amount. Lock booking before financial UPDATE statements; retry the transaction on deadlock/serialization failure.';


-- Restaurant tables, private-guide appointments and finite-stock food delivery.
-- Applied after 30/50/51. Provider settlement/driver dispatch follows in 55.
DO $$ DECLARE kind_constraint text; BEGIN
  SELECT c.conname INTO kind_constraint FROM pg_constraint c
    WHERE c.conrelid='travora.bookings'::regclass AND c.contype='c'
      AND c.conname='bookings_kind_check';
  IF kind_constraint IS NULL THEN RAISE EXCEPTION 'Expected base booking kind constraint missing'; END IF;
  EXECUTE format('ALTER TABLE travora.bookings DROP CONSTRAINT %I',kind_constraint);
END; $$;
ALTER TABLE bookings ADD CONSTRAINT bookings_kind_check
  CHECK (kind IN ('HOTEL','ACTIVITY','TRANSPORT','RESTAURANT','GUIDE','DELIVERY'));

CREATE TABLE restaurant_booking_details (
  booking_id uuid PRIMARY KEY REFERENCES bookings(id) ON DELETE RESTRICT,
  restaurant_id uuid NOT NULL REFERENCES restaurants(id) ON DELETE RESTRICT,
  session_id uuid NOT NULL,
  table_id uuid NOT NULL,
  guest_count integer NOT NULL CHECK (guest_count>0),
  reservation_price_minor bigint NOT NULL CHECK (reservation_price_minor>=0),
  starts_at_snapshot timestamptz NOT NULL,
  ends_at_snapshot timestamptz NOT NULL CHECK (ends_at_snapshot>starts_at_snapshot),
  table_label_snapshot text NOT NULL CHECK (length(btrim(table_label_snapshot))>0),
  FOREIGN KEY(session_id,restaurant_id) REFERENCES restaurant_reservation_sessions(id,restaurant_id),
  FOREIGN KEY(table_id,restaurant_id) REFERENCES restaurant_tables(id,restaurant_id)
);
CREATE INDEX restaurant_booking_session_idx ON restaurant_booking_details(session_id);
CREATE INDEX restaurant_booking_table_idx ON restaurant_booking_details(table_id);
COMMENT ON TABLE restaurant_booking_details IS 'One chosen table per party. Reservation price is a fixed deposit/base charge, not multiplied by guests; meals are separate food orders.';

CREATE TABLE restaurant_allocations (
  booking_id uuid PRIMARY KEY REFERENCES restaurant_booking_details(booking_id) ON DELETE RESTRICT,
  session_id uuid NOT NULL,
  table_id uuid NOT NULL,
  currency char(3) NOT NULL,
  units integer NOT NULL CHECK(units>0),
  state text NOT NULL DEFAULT 'held' CHECK(state IN ('held','committed','released')),
  FOREIGN KEY(session_id,table_id,currency) REFERENCES restaurant_table_inventory(session_id,table_id,currency),
  FOREIGN KEY(booking_id,currency) REFERENCES bookings(id,currency)
);
CREATE INDEX restaurant_allocations_inventory_idx ON restaurant_allocations(session_id,table_id);
COMMENT ON COLUMN restaurant_allocations.units IS 'Guest seats in session pool; the chosen table simultaneously consumes exactly one table inventory unit.';

CREATE TABLE guide_booking_details (
  booking_id uuid PRIMARY KEY REFERENCES bookings(id) ON DELETE RESTRICT,
  guide_id uuid NOT NULL REFERENCES guide_profiles(id) ON DELETE RESTRICT,
  slot_id uuid NOT NULL,
  party_count integer NOT NULL CHECK(party_count>0),
  appointment_price_minor bigint NOT NULL CHECK(appointment_price_minor>=0),
  starts_at_snapshot timestamptz NOT NULL,
  ends_at_snapshot timestamptz NOT NULL CHECK(ends_at_snapshot>starts_at_snapshot),
  language_code text NOT NULL,
  FOREIGN KEY(slot_id,guide_id) REFERENCES guide_availability_slots(id,guide_id),
  FOREIGN KEY(guide_id,language_code) REFERENCES guide_languages(guide_id,language_code)
);
CREATE INDEX guide_booking_slot_idx ON guide_booking_details(slot_id);
COMMENT ON TABLE guide_booking_details IS 'Entire private appointment price, not per traveler. One personal guide appointment consumes one slot, with bounded party size.';

CREATE TABLE guide_allocations (
  booking_id uuid PRIMARY KEY REFERENCES guide_booking_details(booking_id) ON DELETE RESTRICT,
  slot_id uuid NOT NULL,
  currency char(3) NOT NULL,
  units integer NOT NULL DEFAULT 1 CHECK(units=1),
  state text NOT NULL DEFAULT 'held' CHECK(state IN ('held','committed','released')),
  FOREIGN KEY(slot_id,currency) REFERENCES guide_availability_slots(id,currency),
  FOREIGN KEY(booking_id,currency) REFERENCES bookings(id,currency)
);
CREATE INDEX guide_allocations_slot_idx ON guide_allocations(slot_id);

CREATE TABLE food_delivery_details (
  booking_id uuid PRIMARY KEY REFERENCES bookings(id) ON DELETE RESTRICT,
  restaurant_id uuid NOT NULL,
  currency char(3) NOT NULL,
  inventory_date date NOT NULL,
  delivery_fee_minor bigint NOT NULL CHECK(delivery_fee_minor>=0),
  minimum_order_minor_snapshot bigint NOT NULL DEFAULT 0 CHECK(minimum_order_minor_snapshot>=0),
  pickup_label text NOT NULL CHECK(length(btrim(pickup_label)) BETWEEN 1 AND 500),
  dropoff_label text NOT NULL CHECK(length(btrim(dropoff_label)) BETWEEN 1 AND 500),
  pickup_latitude numeric(9,6) CHECK(pickup_latitude BETWEEN -90 AND 90),
  pickup_longitude numeric(9,6) CHECK(pickup_longitude BETWEEN -180 AND 180),
  dropoff_latitude numeric(9,6) CHECK(dropoff_latitude BETWEEN -90 AND 90),
  dropoff_longitude numeric(9,6) CHECK(dropoff_longitude BETWEEN -180 AND 180),
  recipient_name text NOT NULL CHECK(length(btrim(recipient_name)) BETWEEN 1 AND 150),
  recipient_phone text NOT NULL CHECK(length(btrim(recipient_phone)) BETWEEN 1 AND 40),
  delivery_instructions text CHECK(delivery_instructions IS NULL OR length(delivery_instructions)<=1000),
  delivery_status text NOT NULL DEFAULT 'awaiting_payment'
    CHECK(delivery_status IN ('awaiting_payment','placed','preparing','ready','picked_up','delivered','cancelled')),
  prepared_at timestamptz,
  picked_up_at timestamptz,
  delivered_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(booking_id,restaurant_id,currency,inventory_date),
  FOREIGN KEY(restaurant_id,currency) REFERENCES restaurants(id,currency),
  FOREIGN KEY(booking_id,currency) REFERENCES bookings(id,currency),
  CHECK((pickup_latitude IS NULL)=(pickup_longitude IS NULL)),
  CHECK((dropoff_latitude IS NULL)=(dropoff_longitude IS NULL))
);
CREATE INDEX food_delivery_restaurant_queue_idx ON food_delivery_details(restaurant_id,delivery_status,created_at);
COMMENT ON TABLE food_delivery_details IS 'Private recipient/address snapshots. Kitchen stages live here; provider-scoped driver dispatch/proof is added by 55. Historical fee and minimum order do not change with restaurant settings.';

CREATE TABLE food_order_lines (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  booking_id uuid NOT NULL,
  restaurant_id uuid NOT NULL,
  menu_item_id uuid NOT NULL,
  inventory_date date NOT NULL,
  currency char(3) NOT NULL,
  quantity integer NOT NULL CHECK(quantity>0),
  unit_price_minor bigint NOT NULL CHECK(unit_price_minor>=0),
  item_name_snapshot text NOT NULL CHECK(length(btrim(item_name_snapshot)) BETWEEN 1 AND 200),
  preparation_notes text CHECK(preparation_notes IS NULL OR length(preparation_notes)<=1000),
  state text NOT NULL DEFAULT 'held' CHECK(state IN ('held','committed','consumed','released')),
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(booking_id,menu_item_id),
  FOREIGN KEY(booking_id,restaurant_id,currency,inventory_date)
    REFERENCES food_delivery_details(booking_id,restaurant_id,currency,inventory_date),
  FOREIGN KEY(menu_item_id,restaurant_id,currency) REFERENCES menu_items(id,restaurant_id,currency),
  FOREIGN KEY(menu_item_id,inventory_date,currency) REFERENCES menu_item_inventory(menu_item_id,inventory_date,currency)
);
CREATE INDEX food_order_lines_stock_idx ON food_order_lines(menu_item_id,inventory_date);
COMMENT ON TABLE food_order_lines IS 'Immutable quoted lines also form the stock ledger. held reserves stock, committed confirms order, consumed begins food preparation and never returns stock on cancellation, released frees unprepared stock.';

CREATE TABLE food_carts (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  owner_user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  restaurant_id uuid NOT NULL,
  currency char(3) NOT NULL,
  status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','converted','abandoned')),
  booking_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(id,restaurant_id,currency),
  FOREIGN KEY(restaurant_id,currency) REFERENCES restaurants(id,currency),
  FOREIGN KEY(booking_id,owner_user_id) REFERENCES bookings(id,user_id),
  CHECK((status='converted')=(booking_id IS NOT NULL))
);
CREATE UNIQUE INDEX food_carts_active_owner_restaurant_idx ON food_carts(owner_user_id,restaurant_id) WHERE status='active';
CREATE INDEX food_carts_booking_idx ON food_carts(booking_id) WHERE booking_id IS NOT NULL;
CREATE TABLE food_cart_items (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  cart_id uuid NOT NULL,
  restaurant_id uuid NOT NULL,
  menu_item_id uuid NOT NULL,
  currency char(3) NOT NULL,
  quantity integer NOT NULL CHECK(quantity>0),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(cart_id,menu_item_id),
  FOREIGN KEY(cart_id,restaurant_id,currency) REFERENCES food_carts(id,restaurant_id,currency) ON DELETE CASCADE,
  FOREIGN KEY(menu_item_id,restaurant_id,currency) REFERENCES menu_items(id,restaurant_id,currency)
);
CREATE INDEX food_cart_items_menu_idx ON food_cart_items(menu_item_id);
COMMENT ON TABLE food_cart_items IS 'Shopping intent only, without inventory holds. API reprices from current menu at checkout, validates published daily stock, then creates immutable order and reservations atomically.';

CREATE TABLE food_delivery_status_history (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  booking_id uuid NOT NULL REFERENCES food_delivery_details(booking_id) ON DELETE RESTRICT,
  from_status text,
  to_status text NOT NULL,
  changed_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX food_delivery_status_history_booking_idx ON food_delivery_status_history(booking_id,changed_at);

CREATE TRIGGER immutable_restaurant_detail BEFORE INSERT OR UPDATE OR DELETE ON restaurant_booking_details
  FOR EACH ROW EXECUTE FUNCTION guard_booking_detail();
CREATE TRIGGER immutable_guide_detail BEFORE INSERT OR UPDATE OR DELETE ON guide_booking_details
  FOR EACH ROW EXECUTE FUNCTION guard_booking_detail();

CREATE FUNCTION guard_extra_inventory_counters() RETURNS trigger LANGUAGE plpgsql
SET search_path=travora,pg_temp AS $$
DECLARE h text; b text;
BEGIN
  IF TG_TABLE_NAME='menu_item_inventory' THEN h:='held_units';b:='booked_units';
  ELSE h:='held_count';b:='booked_count'; END IF;
  IF TG_OP='INSERT' AND ((to_jsonb(NEW)->>h)::integer<>0 OR (to_jsonb(NEW)->>b)::integer<>0) THEN
    RAISE EXCEPTION 'New extra-service inventory counters must start at zero' USING ERRCODE='23514';
  END IF;
  IF TG_OP='UPDATE' AND pg_trigger_depth()<=1 AND
    ROW(to_jsonb(NEW)->h,to_jsonb(NEW)->b) IS DISTINCT FROM ROW(to_jsonb(OLD)->h,to_jsonb(OLD)->b) THEN
    RAISE EXCEPTION 'Extra-service counters belong to allocation ledger' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END; $$;
CREATE TRIGGER extra_counter_guard BEFORE INSERT OR UPDATE ON restaurant_reservation_sessions FOR EACH ROW EXECUTE FUNCTION guard_extra_inventory_counters();
CREATE TRIGGER extra_counter_guard BEFORE INSERT OR UPDATE ON restaurant_table_inventory FOR EACH ROW EXECUTE FUNCTION guard_extra_inventory_counters();
CREATE TRIGGER extra_counter_guard BEFORE INSERT OR UPDATE ON guide_availability_slots FOR EACH ROW EXECUTE FUNCTION guard_extra_inventory_counters();
CREATE TRIGGER extra_counter_guard BEFORE INSERT OR UPDATE ON menu_item_inventory FOR EACH ROW EXECUTE FUNCTION guard_extra_inventory_counters();

CREATE FUNCTION guard_extra_schedule() RETURNS trigger LANGUAGE plpgsql
SET search_path=travora,pg_temp AS $$
DECLARE overlap boolean;
BEGIN
  IF TG_OP='UPDATE' THEN
    IF TG_TABLE_NAME='guide_availability_slots' THEN
      IF ROW(NEW.starts_at,NEW.ends_at,NEW.status,NEW.guide_id) IS NOT DISTINCT FROM ROW(OLD.starts_at,OLD.ends_at,OLD.status,OLD.guide_id) THEN RETURN NEW; END IF;
    ELSE
      IF ROW(NEW.starts_at,NEW.ends_at,NEW.status,NEW.restaurant_id) IS NOT DISTINCT FROM ROW(OLD.starts_at,OLD.ends_at,OLD.status,OLD.restaurant_id) THEN RETURN NEW; END IF;
    END IF;
  END IF;
  IF TG_OP='UPDATE' AND OLD.held_count+OLD.booked_count>0 AND
     ROW(NEW.starts_at,NEW.ends_at) IS DISTINCT FROM ROW(OLD.starts_at,OLD.ends_at) THEN
    RAISE EXCEPTION 'Reserved service time is immutable; cancel existing bookings explicitly' USING ERRCODE='23514';
  END IF;
  IF TG_TABLE_NAME='guide_availability_slots' THEN
    UPDATE guide_profiles SET updated_at=updated_at WHERE id=NEW.guide_id;
    SELECT EXISTS(SELECT 1 FROM guide_availability_slots s WHERE s.guide_id=NEW.guide_id AND s.id<>NEW.id
      AND s.status='scheduled' AND tstzrange(s.starts_at,s.ends_at,'[)')&&tstzrange(NEW.starts_at,NEW.ends_at,'[)')) INTO overlap;
  ELSE
    UPDATE restaurants SET updated_at=updated_at WHERE id=NEW.restaurant_id;
    SELECT EXISTS(SELECT 1 FROM restaurant_reservation_sessions s WHERE s.restaurant_id=NEW.restaurant_id AND s.id<>NEW.id
      AND s.status='scheduled' AND tstzrange(s.starts_at,s.ends_at,'[)')&&tstzrange(NEW.starts_at,NEW.ends_at,'[)')) INTO overlap;
  END IF;
  IF NEW.status='scheduled' AND overlap THEN RAISE EXCEPTION 'Scheduled windows for this service overlap' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END; $$;
CREATE TRIGGER extra_schedule_guard BEFORE INSERT OR UPDATE ON guide_availability_slots FOR EACH ROW EXECUTE FUNCTION guard_extra_schedule();
CREATE TRIGGER extra_schedule_guard BEFORE INSERT OR UPDATE ON restaurant_reservation_sessions FOR EACH ROW EXECUTE FUNCTION guard_extra_schedule();

CREATE FUNCTION maintain_extra_allocation() RETURNS trigger LANGUAGE plpgsql
SET search_path=travora,pg_temp AS $$
DECLARE p bookings; bid uuid; old_h integer:=0;old_b integer:=0;new_h integer:=0;new_b integer:=0;
  rd restaurant_booking_details; gd guide_booking_details; rs restaurant_reservation_sessions;
  gs guide_availability_slots; tab restaurant_tables; ti restaurant_table_inventory;
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Retain allocation history; cancel the booking to release' USING ERRCODE='23514'; END IF;
  bid:=NEW.booking_id;
  SELECT * INTO p FROM bookings WHERE id=bid FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Allocation booking missing' USING ERRCODE='23503'; END IF;
  IF TG_OP='UPDATE' THEN
    IF (to_jsonb(NEW)-'state') IS DISTINCT FROM (to_jsonb(OLD)-'state') THEN RAISE EXCEPTION 'Allocation quantity and identity are immutable' USING ERRCODE='23514'; END IF;
    IF NEW.state<>OLD.state AND NOT((OLD.state='held' AND NEW.state IN('committed','released')) OR(OLD.state='committed' AND NEW.state='released')) THEN
      RAISE EXCEPTION 'Invalid allocation transition' USING ERRCODE='23514'; END IF;
    old_h:=CASE WHEN OLD.state='held' THEN OLD.units ELSE 0 END;old_b:=CASE WHEN OLD.state='committed' THEN OLD.units ELSE 0 END;
  ELSIF NEW.state<>'held' THEN RAISE EXCEPTION 'Allocation must start held' USING ERRCODE='23514'; END IF;
  IF NEW.state='held' AND(p.status<>'pending_payment' OR p.hold_expires_at<=now()) THEN RAISE EXCEPTION 'Hold requires unexpired pending booking' USING ERRCODE='23514'; END IF;
  IF NEW.state='committed' AND p.status NOT IN('confirmed','completed') THEN RAISE EXCEPTION 'Commit requires confirmed booking' USING ERRCODE='23514'; END IF;
  IF NEW.state='released' AND p.status NOT IN('cancelled','expired') THEN RAISE EXCEPTION 'Release requires cancelled or expired booking' USING ERRCODE='23514'; END IF;
  new_h:=CASE WHEN NEW.state='held' THEN NEW.units ELSE 0 END;new_b:=CASE WHEN NEW.state='committed' THEN NEW.units ELSE 0 END;
  IF TG_TABLE_NAME='restaurant_allocations' THEN
    SELECT * INTO rd FROM restaurant_booking_details WHERE booking_id=bid;
    IF NEW.session_id<>rd.session_id OR NEW.table_id<>rd.table_id OR NEW.units<>rd.guest_count THEN RAISE EXCEPTION 'Table allocation differs from reservation' USING ERRCODE='23514'; END IF;
    SELECT * INTO rs FROM restaurant_reservation_sessions WHERE id=NEW.session_id FOR UPDATE;
    SELECT * INTO ti FROM restaurant_table_inventory WHERE session_id=NEW.session_id AND table_id=NEW.table_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Chosen table inventory missing' USING ERRCODE='23503'; END IF;
    IF TG_OP='INSERT' THEN
      SELECT * INTO tab FROM restaurant_tables WHERE id=NEW.table_id;
      IF tab.status<>'active' OR rd.guest_count>tab.seats OR rd.reservation_price_minor<>rs.price_minor OR rd.starts_at_snapshot<>rs.starts_at OR rd.ends_at_snapshot<>rs.ends_at THEN
        RAISE EXCEPTION 'Table capacity, quote or session times invalid' USING ERRCODE='23514'; END IF;
      IF NOT EXISTS(SELECT 1 FROM restaurants WHERE id=rd.restaurant_id AND status='active') THEN RAISE EXCEPTION 'Restaurant is unavailable' USING ERRCODE='23514'; END IF;
    END IF;
    IF (new_h+new_b>old_h+old_b OR(TG_OP='UPDATE' AND OLD.state='held' AND NEW.state='committed')) AND rs.status<>'scheduled' THEN
      RAISE EXCEPTION 'Restaurant session unavailable' USING ERRCODE='23514'; END IF;
    UPDATE restaurant_reservation_sessions SET held_count=held_count+new_h-old_h,booked_count=booked_count+new_b-old_b WHERE id=NEW.session_id;
    UPDATE restaurant_table_inventory SET held_count=held_count+(CASE WHEN NEW.state='held' THEN 1 ELSE 0 END)-(CASE WHEN TG_OP='UPDATE' AND OLD.state='held' THEN 1 ELSE 0 END),
      booked_count=booked_count+(CASE WHEN NEW.state='committed' THEN 1 ELSE 0 END)-(CASE WHEN TG_OP='UPDATE' AND OLD.state='committed' THEN 1 ELSE 0 END)
      WHERE session_id=NEW.session_id AND table_id=NEW.table_id;
  ELSE
    SELECT * INTO gd FROM guide_booking_details WHERE booking_id=bid;
    IF NEW.slot_id<>gd.slot_id OR NEW.units<>1 THEN RAISE EXCEPTION 'Guide allocation differs from appointment' USING ERRCODE='23514'; END IF;
    SELECT * INTO gs FROM guide_availability_slots WHERE id=NEW.slot_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Guide slot missing' USING ERRCODE='23503'; END IF;
    IF TG_OP='INSERT' AND(gd.party_count>gs.max_party_size OR gd.appointment_price_minor<>gs.price_minor OR gd.starts_at_snapshot<>gs.starts_at OR gd.ends_at_snapshot<>gs.ends_at) THEN
      RAISE EXCEPTION 'Guide party size, quote or times invalid' USING ERRCODE='23514'; END IF;
    IF TG_OP='INSERT' AND NOT EXISTS(SELECT 1 FROM guide_profiles WHERE id=gd.guide_id AND status='active') THEN RAISE EXCEPTION 'Guide unavailable' USING ERRCODE='23514'; END IF;
    IF(new_h+new_b>old_h+old_b OR(TG_OP='UPDATE' AND OLD.state='held' AND NEW.state='committed')) AND gs.status<>'scheduled' THEN
      RAISE EXCEPTION 'Guide slot unavailable' USING ERRCODE='23514'; END IF;
    UPDATE guide_availability_slots SET held_count=held_count+new_h-old_h,booked_count=booked_count+new_b-old_b WHERE id=NEW.slot_id;
  END IF;
  RETURN NEW;
END; $$;
CREATE TRIGGER restaurant_allocation_ledger BEFORE INSERT OR UPDATE OR DELETE ON restaurant_allocations FOR EACH ROW EXECUTE FUNCTION maintain_extra_allocation();
CREATE TRIGGER guide_allocation_ledger BEFORE INSERT OR UPDATE OR DELETE ON guide_allocations FOR EACH ROW EXECUTE FUNCTION maintain_extra_allocation();

CREATE FUNCTION guard_food_delivery() RETURNS trigger LANGUAGE plpgsql
SET search_path=travora,pg_temp AS $$
DECLARE p bookings; settings restaurant_delivery_settings;
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Food order history is retained' USING ERRCODE='23514'; END IF;
  SELECT * INTO p FROM bookings WHERE id=NEW.booking_id FOR UPDATE;
  IF NOT FOUND OR p.kind<>'DELIVERY' THEN RAISE EXCEPTION 'Food order needs DELIVERY booking' USING ERRCODE='23514'; END IF;
  IF TG_OP='INSERT' THEN
    IF p.status NOT IN('draft','pending_payment') OR NEW.delivery_status<>'awaiting_payment' THEN RAISE EXCEPTION 'New food order awaits payment' USING ERRCODE='23514'; END IF;
    SELECT * INTO settings FROM restaurant_delivery_settings WHERE restaurant_id=NEW.restaurant_id;
    IF NOT FOUND OR NOT settings.is_enabled OR NOT settings.accepts_orders OR NEW.delivery_fee_minor<>settings.base_fee_minor OR NEW.minimum_order_minor_snapshot<>settings.min_order_minor THEN
      RAISE EXCEPTION 'Delivery unavailable or fee/minimum quote stale' USING ERRCODE='23514'; END IF;
    IF NOT EXISTS(SELECT 1 FROM restaurants WHERE id=NEW.restaurant_id AND status='active') THEN RAISE EXCEPTION 'Restaurant unavailable' USING ERRCODE='23514'; END IF;
  ELSE
    IF(to_jsonb(NEW)-ARRAY['delivery_status','prepared_at','picked_up_at','delivered_at','updated_at']) IS DISTINCT FROM
      (to_jsonb(OLD)-ARRAY['delivery_status','prepared_at','picked_up_at','delivered_at','updated_at']) THEN RAISE EXCEPTION 'Food order snapshots immutable' USING ERRCODE='23514'; END IF;
    IF NEW.delivery_status<>OLD.delivery_status AND NOT(
      (OLD.delivery_status='awaiting_payment' AND NEW.delivery_status IN('placed','cancelled')) OR
      (OLD.delivery_status='placed' AND NEW.delivery_status IN('preparing','cancelled')) OR
      (OLD.delivery_status='preparing' AND NEW.delivery_status IN('ready','cancelled')) OR
      (OLD.delivery_status='ready' AND NEW.delivery_status IN('picked_up','cancelled')) OR
      (OLD.delivery_status='picked_up' AND NEW.delivery_status IN('delivered','cancelled'))
    ) THEN RAISE EXCEPTION 'Invalid food fulfillment transition' USING ERRCODE='23514'; END IF;
  END IF;
  IF NEW.delivery_status IN('placed','preparing','ready','picked_up','delivered') AND p.status NOT IN('confirmed','completed') THEN RAISE EXCEPTION 'Fulfillment requires confirmed order' USING ERRCODE='23514'; END IF;
  IF NEW.delivery_status='cancelled' AND p.status NOT IN('cancelled','expired') THEN RAISE EXCEPTION 'Cancel booking before food order' USING ERRCODE='23514'; END IF;
  IF NEW.delivery_status IN('picked_up','delivered') AND NOT EXISTS(
    SELECT 1 FROM service_dispatches d WHERE d.booking_id=NEW.booking_id AND d.status IN('picked_up','completed')
  ) THEN RAISE EXCEPTION 'Food pickup requires the assigned driver dispatch' USING ERRCODE='23514'; END IF;
  IF NEW.delivery_status='delivered' AND NOT EXISTS(
    SELECT 1 FROM service_dispatches d JOIN service_completion_proofs proof ON proof.dispatch_id=d.id
      WHERE d.booking_id=NEW.booking_id AND d.status='completed'
  ) THEN RAISE EXCEPTION 'Food delivery completion requires dispatch proof' USING ERRCODE='23514'; END IF;
  IF NEW.delivery_status IN('preparing','ready','picked_up','delivered') THEN NEW.prepared_at:=COALESCE(NEW.prepared_at,now()); END IF;
  IF NEW.delivery_status IN('picked_up','delivered') THEN NEW.picked_up_at:=COALESCE(NEW.picked_up_at,now()); END IF;
  IF NEW.delivery_status='delivered' THEN NEW.delivered_at:=COALESCE(NEW.delivered_at,now()); END IF;
  RETURN NEW;
END; $$;
CREATE TRIGGER food_delivery_guard BEFORE INSERT OR UPDATE OR DELETE ON food_delivery_details FOR EACH ROW EXECUTE FUNCTION guard_food_delivery();

CREATE FUNCTION maintain_food_line() RETURNS trigger LANGUAGE plpgsql
SET search_path=travora,pg_temp AS $$
DECLARE p bookings; fd food_delivery_details; item menu_items; inv menu_item_inventory;
  old_h integer:=0;old_b integer:=0;new_h integer:=0;new_b integer:=0;
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Food lines are retained; cancel order' USING ERRCODE='23514'; END IF;
  SELECT * INTO p FROM bookings WHERE id=NEW.booking_id FOR UPDATE;
  SELECT * INTO fd FROM food_delivery_details WHERE booking_id=NEW.booking_id;
  IF NOT FOUND OR p.kind<>'DELIVERY' THEN RAISE EXCEPTION 'Food parent missing' USING ERRCODE='23503'; END IF;
  IF TG_OP='UPDATE' THEN
    IF(to_jsonb(NEW)-'state') IS DISTINCT FROM(to_jsonb(OLD)-'state') THEN RAISE EXCEPTION 'Food line quantity/quote immutable' USING ERRCODE='23514'; END IF;
    IF NEW.state<>OLD.state AND NOT((OLD.state='held' AND NEW.state IN('committed','released')) OR(OLD.state='committed' AND NEW.state IN('consumed','released'))) THEN RAISE EXCEPTION 'Invalid food stock transition' USING ERRCODE='23514'; END IF;
    old_h:=CASE WHEN OLD.state='held' THEN OLD.quantity ELSE 0 END;
    old_b:=CASE WHEN OLD.state IN('committed','consumed') THEN OLD.quantity ELSE 0 END;
  ELSIF NEW.state<>'held' THEN RAISE EXCEPTION 'Food line starts held' USING ERRCODE='23514'; END IF;
  IF NEW.state='held' AND(p.status<>'pending_payment' OR p.hold_expires_at<=now()) THEN RAISE EXCEPTION 'Food hold needs unexpired booking' USING ERRCODE='23514'; END IF;
  IF NEW.state='committed' AND p.status NOT IN('confirmed','completed') THEN RAISE EXCEPTION 'Food commit needs confirmed order' USING ERRCODE='23514'; END IF;
  IF NEW.state='consumed' AND fd.delivery_status NOT IN('preparing','ready','picked_up','delivered','cancelled') THEN RAISE EXCEPTION 'Food stock consumption requires kitchen preparation' USING ERRCODE='23514'; END IF;
  IF NEW.state='released' AND p.status NOT IN('cancelled','expired') THEN RAISE EXCEPTION 'Food release needs cancelled order' USING ERRCODE='23514'; END IF;
  SELECT * INTO inv FROM menu_item_inventory WHERE menu_item_id=NEW.menu_item_id AND inventory_date=NEW.inventory_date FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Daily food stock unpublished' USING ERRCODE='23503'; END IF;
  IF TG_OP='INSERT' THEN
    SELECT * INTO item FROM menu_items WHERE id=NEW.menu_item_id FOR SHARE;
    IF item.restaurant_id<>fd.restaurant_id OR item.status<>'active' OR NOT item.is_available OR NEW.unit_price_minor<>item.price_minor OR inv.is_closed THEN
      RAISE EXCEPTION 'Menu unavailable or price/restaurant invalid' USING ERRCODE='23514'; END IF;
  END IF;
  new_h:=CASE WHEN NEW.state='held' THEN NEW.quantity ELSE 0 END;
  new_b:=CASE WHEN NEW.state IN('committed','consumed') THEN NEW.quantity ELSE 0 END;
  UPDATE menu_item_inventory SET held_units=held_units+new_h-old_h,booked_units=booked_units+new_b-old_b
    WHERE menu_item_id=NEW.menu_item_id AND inventory_date=NEW.inventory_date;
  RETURN NEW;
END; $$;
CREATE TRIGGER food_line_ledger BEFORE INSERT OR UPDATE OR DELETE ON food_order_lines FOR EACH ROW EXECUTE FUNCTION maintain_food_line();

CREATE FUNCTION apply_food_status() RETURNS trigger LANGUAGE plpgsql
SET search_path=travora,pg_temp AS $$
BEGIN
  IF TG_OP='INSERT' OR NEW.delivery_status IS DISTINCT FROM OLD.delivery_status THEN
    INSERT INTO food_delivery_status_history(booking_id,from_status,to_status)
      VALUES(NEW.booking_id,CASE WHEN TG_OP='INSERT' THEN NULL ELSE OLD.delivery_status END,NEW.delivery_status);
    IF NEW.delivery_status='preparing' THEN UPDATE food_order_lines SET state='consumed' WHERE booking_id=NEW.booking_id AND state='committed'; END IF;
  END IF;
  RETURN NEW;
END; $$;
CREATE TRIGGER food_status_effects AFTER INSERT OR UPDATE ON food_delivery_details FOR EACH ROW EXECUTE FUNCTION apply_food_status();

CREATE FUNCTION guard_food_cart() RETURNS trigger LANGUAGE plpgsql
SET search_path=travora,pg_temp AS $$
DECLARE fd food_delivery_details;
BEGIN
  IF TG_OP='UPDATE' THEN
    IF ROW(NEW.id,NEW.owner_user_id,NEW.restaurant_id,NEW.currency,NEW.created_at) IS DISTINCT FROM ROW(OLD.id,OLD.owner_user_id,OLD.restaurant_id,OLD.currency,OLD.created_at) THEN RAISE EXCEPTION 'Cart scope immutable' USING ERRCODE='23514'; END IF;
    IF OLD.status<>'active' AND NEW.status IS DISTINCT FROM OLD.status THEN RAISE EXCEPTION 'Converted/abandoned cart terminal' USING ERRCODE='23514'; END IF;
    IF OLD.booking_id IS NOT NULL AND NEW.booking_id IS DISTINCT FROM OLD.booking_id THEN RAISE EXCEPTION 'Converted cart booking immutable' USING ERRCODE='23514'; END IF;
  END IF;
  IF NEW.status='converted' THEN
    SELECT * INTO fd FROM food_delivery_details WHERE booking_id=NEW.booking_id;
    IF NOT FOUND OR fd.restaurant_id<>NEW.restaurant_id OR fd.currency<>NEW.currency THEN RAISE EXCEPTION 'Converted cart needs same restaurant/currency delivery' USING ERRCODE='23514'; END IF;
  END IF;
  RETURN NEW;
END; $$;
CREATE TRIGGER food_cart_guard BEFORE INSERT OR UPDATE ON food_carts FOR EACH ROW EXECUTE FUNCTION guard_food_cart();
CREATE FUNCTION guard_food_cart_item() RETURNS trigger LANGUAGE plpgsql
SET search_path=travora,pg_temp AS $$
DECLARE cid uuid; c food_carts;
BEGIN
  IF TG_OP='DELETE' THEN cid:=OLD.cart_id; ELSE cid:=NEW.cart_id; END IF;
  SELECT * INTO c FROM food_carts WHERE id=cid FOR UPDATE;
  IF NOT FOUND AND TG_OP='DELETE' THEN RETURN OLD; END IF;
  IF NOT FOUND OR c.status<>'active' THEN RAISE EXCEPTION 'Only active cart can change items' USING ERRCODE='23514'; END IF;
  IF TG_OP='UPDATE' AND ROW(NEW.id,NEW.cart_id,NEW.restaurant_id,NEW.menu_item_id,NEW.currency) IS DISTINCT FROM ROW(OLD.id,OLD.cart_id,OLD.restaurant_id,OLD.menu_item_id,OLD.currency) THEN RAISE EXCEPTION 'Cart item scope immutable' USING ERRCODE='23514'; END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END; $$;
CREATE TRIGGER food_cart_item_guard BEFORE INSERT OR UPDATE OR DELETE ON food_cart_items FOR EACH ROW EXECUTE FUNCTION guard_food_cart_item();

-- Base status effects and the deferred six-kind completeness guard follow.

CREATE OR REPLACE FUNCTION apply_booking_status() RETURNS trigger LANGUAGE plpgsql
SET search_path = travora, pg_temp AS $$
BEGIN
  IF TG_OP='INSERT' OR NEW.status IS DISTINCT FROM OLD.status THEN
    INSERT INTO booking_status_history(booking_id,from_status,to_status)
      VALUES(NEW.id,CASE WHEN TG_OP='INSERT' THEN NULL ELSE OLD.status END,NEW.status);
    IF NEW.status='confirmed' THEN
      UPDATE room_night_allocations SET state='committed' WHERE booking_id=NEW.id AND state='held';
      UPDATE activity_allocations SET state='committed' WHERE booking_id=NEW.id AND state='held';
      UPDATE transport_allocations SET state='committed' WHERE booking_id=NEW.id AND state='held';
      UPDATE restaurant_allocations SET state='committed' WHERE booking_id=NEW.id AND state='held';
      UPDATE guide_allocations SET state='committed' WHERE booking_id=NEW.id AND state='held';
      UPDATE food_order_lines SET state='committed' WHERE booking_id=NEW.id AND state='held';
      UPDATE food_delivery_details SET delivery_status='placed' WHERE booking_id=NEW.id AND delivery_status='awaiting_payment';
    ELSIF NEW.status IN ('cancelled','expired') THEN
      UPDATE room_night_allocations SET state='released' WHERE booking_id=NEW.id AND state<>'released';
      UPDATE activity_allocations SET state='released' WHERE booking_id=NEW.id AND state<>'released';
      UPDATE transport_allocations SET state='released' WHERE booking_id=NEW.id AND state<>'released';
      UPDATE restaurant_allocations SET state='released' WHERE booking_id=NEW.id AND state<>'released';
      UPDATE guide_allocations SET state='released' WHERE booking_id=NEW.id AND state<>'released';
      UPDATE food_order_lines SET state='released' WHERE booking_id=NEW.id AND state IN('held','committed');
      UPDATE food_delivery_details SET delivery_status='cancelled' WHERE booking_id=NEW.id AND delivery_status NOT IN('cancelled','delivered');
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION validate_booking_complete() RETURNS trigger LANGUAGE plpgsql
SET search_path=travora,pg_temp AS $$
DECLARE bid uuid;p bookings;cnt integer;matching boolean;desired text;active_count bigint;line_total numeric;
 hd hotel_booking_details;ad activity_booking_details;td transport_booking_details;
 rd restaurant_booking_details;gd guide_booking_details;fd food_delivery_details;
BEGIN
 IF TG_TABLE_NAME='bookings' THEN bid:=COALESCE(NEW.id,OLD.id);
 ELSE bid:=COALESCE(NEW.booking_id,OLD.booking_id); END IF;
 SELECT * INTO p FROM bookings WHERE id=bid;
 IF NOT FOUND THEN RETURN NULL; END IF;
 SELECT (EXISTS(SELECT 1 FROM hotel_booking_details WHERE booking_id=bid))::integer+
  (EXISTS(SELECT 1 FROM activity_booking_details WHERE booking_id=bid))::integer+
  (EXISTS(SELECT 1 FROM transport_booking_details WHERE booking_id=bid))::integer+
  (EXISTS(SELECT 1 FROM restaurant_booking_details WHERE booking_id=bid))::integer+
  (EXISTS(SELECT 1 FROM guide_booking_details WHERE booking_id=bid))::integer+
  (EXISTS(SELECT 1 FROM food_delivery_details WHERE booking_id=bid))::integer INTO cnt;
 matching:=CASE p.kind
  WHEN 'HOTEL' THEN EXISTS(SELECT 1 FROM hotel_booking_details WHERE booking_id=bid)
  WHEN 'ACTIVITY' THEN EXISTS(SELECT 1 FROM activity_booking_details WHERE booking_id=bid)
  WHEN 'TRANSPORT' THEN EXISTS(SELECT 1 FROM transport_booking_details WHERE booking_id=bid)
  WHEN 'RESTAURANT' THEN EXISTS(SELECT 1 FROM restaurant_booking_details WHERE booking_id=bid)
  WHEN 'GUIDE' THEN EXISTS(SELECT 1 FROM guide_booking_details WHERE booking_id=bid)
  WHEN 'DELIVERY' THEN EXISTS(SELECT 1 FROM food_delivery_details WHERE booking_id=bid)
  ELSE false END;
 IF cnt<>1 OR NOT matching THEN RAISE EXCEPTION 'Booking needs exactly one matching service subtype' USING ERRCODE='23514'; END IF;
 IF p.status IN('draft','cancelled','expired') THEN
  IF EXISTS(SELECT 1 FROM room_night_allocations WHERE booking_id=bid AND state<>'released') OR
   EXISTS(SELECT 1 FROM activity_allocations WHERE booking_id=bid AND state<>'released') OR
   EXISTS(SELECT 1 FROM transport_allocations WHERE booking_id=bid AND state<>'released') OR
   EXISTS(SELECT 1 FROM restaurant_allocations WHERE booking_id=bid AND state<>'released') OR
   EXISTS(SELECT 1 FROM guide_allocations WHERE booking_id=bid AND state<>'released') OR
   EXISTS(SELECT 1 FROM food_order_lines WHERE booking_id=bid AND state NOT IN('released','consumed')) THEN
    RAISE EXCEPTION 'Inactive booking cannot retain live reservations' USING ERRCODE='23514'; END IF;
  IF p.kind='DELIVERY' THEN
   SELECT * INTO fd FROM food_delivery_details WHERE booking_id=bid;
   IF p.status IN('cancelled','expired') AND fd.delivery_status<>'cancelled' THEN RAISE EXCEPTION 'Cancelled booking must cancel fulfillment' USING ERRCODE='23514'; END IF;
   IF p.status='draft' AND EXISTS(SELECT 1 FROM food_order_lines WHERE booking_id=bid AND state='consumed') THEN RAISE EXCEPTION 'Draft cannot consume food' USING ERRCODE='23514'; END IF;
  END IF;
  RETURN NULL;
 END IF;
 desired:=CASE WHEN p.status='pending_payment' THEN 'held' ELSE 'committed' END;
 IF p.kind='HOTEL' THEN
  SELECT * INTO hd FROM hotel_booking_details WHERE booking_id=bid;
  SELECT count(*),COALESCE(sum(units::numeric*unit_price_minor),0) INTO active_count,line_total FROM room_night_allocations WHERE booking_id=bid AND state=desired;
  IF active_count<>(hd.check_out-hd.check_in) THEN RAISE EXCEPTION 'Hotel must allocate every night excluding checkout' USING ERRCODE='23514'; END IF;
 ELSIF p.kind='ACTIVITY' THEN
  SELECT * INTO ad FROM activity_booking_details WHERE booking_id=bid;
  SELECT count(*) INTO active_count FROM activity_allocations WHERE booking_id=bid AND state=desired;
  line_total:=ad.unit_price_minor::numeric*ad.participant_count;
  IF active_count<>1 THEN RAISE EXCEPTION 'Activity requires one participant allocation' USING ERRCODE='23514'; END IF;
 ELSIF p.kind='TRANSPORT' THEN
  SELECT * INTO td FROM transport_booking_details WHERE booking_id=bid;
  SELECT count(*) INTO active_count FROM transport_allocations WHERE booking_id=bid AND state=desired;
  line_total:=td.unit_price_minor;
  IF active_count<>1 THEN RAISE EXCEPTION 'Transport requires one vehicle allocation' USING ERRCODE='23514'; END IF;
 ELSIF p.kind='RESTAURANT' THEN
  SELECT * INTO rd FROM restaurant_booking_details WHERE booking_id=bid;
  SELECT count(*) INTO active_count FROM restaurant_allocations WHERE booking_id=bid AND state=desired;
  line_total:=rd.reservation_price_minor;
  IF active_count<>1 THEN RAISE EXCEPTION 'Restaurant requires one chosen-table allocation' USING ERRCODE='23514'; END IF;
 ELSIF p.kind='GUIDE' THEN
  SELECT * INTO gd FROM guide_booking_details WHERE booking_id=bid;
  SELECT count(*) INTO active_count FROM guide_allocations WHERE booking_id=bid AND state=desired;
  line_total:=gd.appointment_price_minor;
  IF active_count<>1 THEN RAISE EXCEPTION 'Guide requires one appointment allocation' USING ERRCODE='23514'; END IF;
 ELSE
  SELECT * INTO fd FROM food_delivery_details WHERE booking_id=bid;
  SELECT count(*),COALESCE(sum(quantity::numeric*unit_price_minor),0) INTO active_count,line_total FROM food_order_lines WHERE booking_id=bid;
  IF active_count=0 THEN RAISE EXCEPTION 'Delivery requires at least one food line' USING ERRCODE='23514'; END IF;
  IF p.status='pending_payment' AND(EXISTS(SELECT 1 FROM food_order_lines WHERE booking_id=bid AND state<>'held') OR fd.delivery_status<>'awaiting_payment') THEN RAISE EXCEPTION 'Pending delivery requires held stock and awaiting payment' USING ERRCODE='23514'; END IF;
  IF p.status IN('confirmed','completed') AND EXISTS(SELECT 1 FROM food_order_lines WHERE booking_id=bid AND state NOT IN('committed','consumed')) THEN RAISE EXCEPTION 'Confirmed delivery needs committed/consumed stock' USING ERRCODE='23514'; END IF;
  IF line_total<fd.minimum_order_minor_snapshot THEN RAISE EXCEPTION 'Food subtotal below quoted minimum order' USING ERRCODE='23514'; END IF;
  IF p.status='completed' AND fd.delivery_status<>'delivered' THEN RAISE EXCEPTION 'Complete only delivered food order' USING ERRCODE='23514'; END IF;
  line_total:=line_total+fd.delivery_fee_minor;
 END IF;
 IF line_total<>p.subtotal_minor THEN RAISE EXCEPTION 'Booking subtotal must equal frozen service lines including delivery fee' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END; $$;
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['restaurant_booking_details','restaurant_allocations','guide_booking_details','guide_allocations','food_delivery_details','food_order_lines'] LOOP
 EXECUTE format('CREATE CONSTRAINT TRIGGER booking_complete AFTER INSERT OR UPDATE OR DELETE ON travora.%I DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION travora.validate_booking_complete()',t);
 END LOOP;
END; $$;
COMMENT ON FUNCTION guard_extra_schedule() IS 'Versions/locks the service parent to serialize scheduled-window overlap checks; rooms/tables and personal-guide slots cannot be sold through overlapping windows.';
COMMENT ON FUNCTION maintain_extra_allocation() IS 'Booking then session/slot then table inventory lock order; fixed restaurant/guide pricing with guest capacity checks only on initial hold. Historical releases survive catalog edits.';
COMMENT ON COLUMN food_delivery_details.delivery_fee_minor IS 'Frozen last-mile delivery fee; included in booking subtotal with food lines. Platform taxes/fees remain separate header fields, avoiding double counting.';


-- Provider attribution, settlement ledger, tokenized payouts, and common dispatch.
-- No bank credentials, card data, PSP secrets, or live authorization are implied.
-- Order runtime locks provider -> booking -> settlement -> payment/dispatch;
-- retry complete transactions on deadlock or serialization failure.

ALTER TABLE providers ADD COLUMN financial_version bigint NOT NULL DEFAULT 0;
ALTER TABLE bookings ADD COLUMN provider_id uuid REFERENCES providers(id) ON DELETE RESTRICT,
  ADD COLUMN provider_branch_id uuid,
  ADD COLUMN provider_snapshot_set boolean NOT NULL DEFAULT false,
  ADD CONSTRAINT bookings_provider_scope UNIQUE (id,provider_id),
  ADD CONSTRAINT bookings_provider_currency_scope UNIQUE (id,provider_id,currency),
  ADD CONSTRAINT bookings_branch_scope FOREIGN KEY (provider_branch_id,provider_id)
    REFERENCES provider_branches(id,provider_id) ON DELETE RESTRICT,
  ADD CONSTRAINT bookings_branch_requires_provider CHECK (provider_branch_id IS NULL OR provider_id IS NOT NULL);
CREATE INDEX bookings_provider_status ON bookings(provider_id,status,created_at DESC) WHERE provider_id IS NOT NULL;
CREATE INDEX bookings_provider_branch ON bookings(provider_branch_id) WHERE provider_branch_id IS NOT NULL;

CREATE FUNCTION guard_booking_provider_snapshot() RETURNS trigger LANGUAGE plpgsql
SET search_path=travora,pg_temp AS $$
BEGIN
  IF TG_OP='UPDATE' THEN
    IF (OLD.provider_snapshot_set OR OLD.provider_id IS NOT NULL) AND
      ROW(NEW.provider_id,NEW.provider_branch_id) IS DISTINCT FROM ROW(OLD.provider_id,OLD.provider_branch_id) THEN
      RAISE EXCEPTION 'Historical booking provider and branch attribution is immutable' USING ERRCODE='23514';
    END IF;
    IF OLD.provider_snapshot_set AND NOT NEW.provider_snapshot_set THEN
      RAISE EXCEPTION 'Booking provider snapshot cannot be reopened' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END; $$;
CREATE TRIGGER booking_provider_snapshot BEFORE INSERT OR UPDATE ON bookings
FOR EACH ROW EXECUTE FUNCTION guard_booking_provider_snapshot();

CREATE FUNCTION booked_service_provider(p_booking_id uuid) RETURNS uuid LANGUAGE plpgsql STABLE
SET search_path=travora,pg_temp AS $$
DECLARE v_provider uuid; v_kind text;
BEGIN
  SELECT kind INTO v_kind FROM bookings WHERE id=p_booking_id;
  CASE v_kind
    WHEN 'HOTEL' THEN SELECT s.provider_id INTO v_provider FROM hotel_booking_details d JOIN hotels s ON s.id=d.hotel_id WHERE d.booking_id=p_booking_id;
    WHEN 'ACTIVITY' THEN SELECT s.provider_id INTO v_provider FROM activity_booking_details d JOIN activities s ON s.id=d.activity_id WHERE d.booking_id=p_booking_id;
    WHEN 'TRANSPORT' THEN SELECT s.provider_id INTO v_provider FROM transport_booking_details d JOIN transport_services s ON s.id=d.transport_service_id WHERE d.booking_id=p_booking_id;
    WHEN 'RESTAURANT' THEN SELECT s.provider_id INTO v_provider FROM restaurant_booking_details d JOIN restaurants s ON s.id=d.restaurant_id WHERE d.booking_id=p_booking_id;
    WHEN 'GUIDE' THEN SELECT s.provider_id INTO v_provider FROM guide_booking_details d JOIN guide_profiles s ON s.id=d.guide_id WHERE d.booking_id=p_booking_id;
    WHEN 'DELIVERY' THEN SELECT s.provider_id INTO v_provider FROM food_delivery_details d JOIN restaurants s ON s.id=d.restaurant_id WHERE d.booking_id=p_booking_id;
    ELSE v_provider:=NULL;
  END CASE;
  RETURN v_provider;
END; $$;

CREATE FUNCTION sync_booking_provider_snapshot() RETURNS trigger LANGUAGE plpgsql VOLATILE
SET search_path=travora,pg_temp AS $$
DECLARE v_table text; v_key text; v_provider uuid;
BEGIN
  CASE TG_TABLE_NAME
    WHEN 'hotel_booking_details' THEN v_table:='hotels'; v_key:='hotel_id';
    WHEN 'activity_booking_details' THEN v_table:='activities'; v_key:='activity_id';
    WHEN 'transport_booking_details' THEN v_table:='transport_services'; v_key:='transport_service_id';
    WHEN 'restaurant_booking_details' THEN v_table:='restaurants'; v_key:='restaurant_id';
    WHEN 'guide_booking_details' THEN v_table:='guide_profiles'; v_key:='guide_id';
    WHEN 'food_delivery_details' THEN v_table:='restaurants'; v_key:='restaurant_id';
  END CASE;
  -- A physical catalog version, not a lock-only read, closes stale RR races
  -- between first booking attribution and catalog supplier reassignment.
  EXECUTE format('UPDATE travora.%I SET updated_at=updated_at WHERE id=$1 RETURNING provider_id',v_table)
    INTO v_provider USING (to_jsonb(NEW)->>v_key)::uuid;
  UPDATE bookings SET provider_id=v_provider,provider_snapshot_set=true WHERE id=NEW.booking_id;
  RETURN NEW;
END; $$;

CREATE FUNCTION assert_booking_provider_snapshot() RETURNS trigger LANGUAGE plpgsql
SET search_path=travora,pg_temp AS $$
DECLARE v_id uuid; v_booking bookings;
BEGIN
  v_id:=CASE WHEN TG_TABLE_NAME='bookings' THEN (to_jsonb(NEW)->>'id')::uuid
             ELSE COALESCE((to_jsonb(NEW)->>'booking_id')::uuid,(to_jsonb(OLD)->>'booking_id')::uuid) END;
  SELECT * INTO v_booking FROM bookings WHERE id=v_id;
  IF FOUND AND (NOT v_booking.provider_snapshot_set OR
      v_booking.provider_id IS DISTINCT FROM booked_service_provider(v_id)) THEN
    RAISE EXCEPTION 'Booking supplier snapshot must match its service supplier' USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END; $$;
CREATE CONSTRAINT TRIGGER booking_provider_snapshot_complete AFTER INSERT OR UPDATE ON bookings
DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION assert_booking_provider_snapshot();
DO $$ DECLARE t text; BEGIN
  FOREACH t IN ARRAY ARRAY['hotel_booking_details','activity_booking_details','transport_booking_details',
    'restaurant_booking_details','guide_booking_details','food_delivery_details'] LOOP
    EXECUTE format('CREATE TRIGGER supplier_snapshot_sync AFTER INSERT OR UPDATE ON travora.%I FOR EACH ROW EXECUTE FUNCTION travora.sync_booking_provider_snapshot()',t);
    EXECUTE format('CREATE CONSTRAINT TRIGGER supplier_snapshot_complete AFTER INSERT OR UPDATE OR DELETE ON travora.%I DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION travora.assert_booking_provider_snapshot()',t);
  END LOOP;
END; $$;

CREATE FUNCTION guard_catalog_provider_reassignment() RETURNS trigger LANGUAGE plpgsql VOLATILE
SET search_path=travora,pg_temp AS $$
DECLARE v_used boolean;
BEGIN
  IF NEW.provider_id IS NOT DISTINCT FROM OLD.provider_id THEN RETURN NEW; END IF;
  CASE TG_TABLE_NAME
    WHEN 'hotels' THEN SELECT EXISTS(SELECT 1 FROM hotel_booking_details WHERE hotel_id=OLD.id) INTO v_used;
    WHEN 'activities' THEN SELECT EXISTS(SELECT 1 FROM activity_booking_details WHERE activity_id=OLD.id) INTO v_used;
    WHEN 'transport_services' THEN SELECT EXISTS(SELECT 1 FROM transport_booking_details WHERE transport_service_id=OLD.id) INTO v_used;
    WHEN 'restaurants' THEN SELECT EXISTS(SELECT 1 FROM restaurant_booking_details WHERE restaurant_id=OLD.id)
      OR EXISTS(SELECT 1 FROM food_delivery_details WHERE restaurant_id=OLD.id) INTO v_used;
    WHEN 'guide_profiles' THEN SELECT EXISTS(SELECT 1 FROM guide_booking_details WHERE guide_id=OLD.id) INTO v_used;
  END CASE;
  IF v_used THEN RAISE EXCEPTION 'A booked catalog service cannot change supplier; archive it and create a new service' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END; $$;
DO $$ DECLARE t text; BEGIN
  FOREACH t IN ARRAY ARRAY['hotels','activities','transport_services','restaurants','guide_profiles'] LOOP
    EXECUTE format('CREATE TRIGGER catalog_provider_history BEFORE UPDATE OF provider_id ON travora.%I FOR EACH ROW EXECUTE FUNCTION travora.guard_catalog_provider_reassignment()',t);
  END LOOP;
END; $$;

CREATE TABLE commission_rules (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  provider_id uuid REFERENCES providers(id) ON DELETE RESTRICT,
  currency char(3) NOT NULL REFERENCES currencies(code) ON DELETE RESTRICT,
  booking_kind text NOT NULL CHECK (booking_kind IN ('HOTEL','ACTIVITY','TRANSPORT','RESTAURANT','GUIDE','DELIVERY')),
  name text NOT NULL CHECK (length(btrim(name))>0),
  rate_bps integer NOT NULL CHECK (rate_bps BETWEEN 0 AND 10000),
  effective_from timestamptz NOT NULL DEFAULT now(),
  effective_until timestamptz,
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK (effective_until IS NULL OR effective_until>effective_from)
);
CREATE INDEX commission_rules_scope ON commission_rules(provider_id,currency,booking_kind,effective_from);

CREATE TABLE booking_commissions (
  booking_id uuid PRIMARY KEY,
  provider_id uuid NOT NULL,
  currency char(3) NOT NULL,
  commission_rule_id uuid NOT NULL REFERENCES commission_rules(id) ON DELETE RESTRICT,
  rate_bps integer NOT NULL CHECK (rate_bps BETWEEN 0 AND 10000),
  created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (booking_id,provider_id,currency) REFERENCES bookings(id,provider_id,currency) ON DELETE RESTRICT
);
CREATE INDEX booking_commissions_provider ON booking_commissions(provider_id,currency);
CREATE INDEX booking_commissions_rule ON booking_commissions(commission_rule_id);

CREATE FUNCTION guard_commission_rule() RETURNS trigger LANGUAGE plpgsql
SET search_path=travora,pg_temp AS $$
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Commission rule history must be retained' USING ERRCODE='23514'; END IF;
  IF ROW(NEW.id,NEW.provider_id,NEW.currency,NEW.booking_kind,NEW.rate_bps,NEW.effective_from,NEW.effective_until,NEW.created_at)
    IS DISTINCT FROM ROW(OLD.id,OLD.provider_id,OLD.currency,OLD.booking_kind,OLD.rate_bps,OLD.effective_from,OLD.effective_until,OLD.created_at) THEN
    RAISE EXCEPTION 'Commission rule financial terms are immutable; create a new rule' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END; $$;
CREATE TRIGGER commission_rule_terms BEFORE UPDATE OR DELETE ON commission_rules FOR EACH ROW EXECUTE FUNCTION guard_commission_rule();

CREATE FUNCTION guard_booking_commission() RETURNS trigger LANGUAGE plpgsql VOLATILE
SET search_path=travora,pg_temp AS $$
DECLARE r commission_rules; b bookings;
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Booking commission snapshots are immutable' USING ERRCODE='23514'; END IF;
  UPDATE providers SET financial_version=financial_version+1 WHERE id=NEW.provider_id;
  UPDATE bookings SET updated_at=updated_at WHERE id=NEW.booking_id RETURNING * INTO b;
  SELECT * INTO r FROM commission_rules WHERE id=NEW.commission_rule_id FOR SHARE;
  IF NOT FOUND OR NOT r.is_active OR (r.provider_id IS NOT NULL AND r.provider_id<>NEW.provider_id)
     OR r.currency<>NEW.currency OR r.booking_kind<>b.kind OR r.rate_bps<>NEW.rate_bps
     OR b.created_at<r.effective_from OR (r.effective_until IS NOT NULL AND b.created_at>=r.effective_until)
     OR b.provider_id IS DISTINCT FROM NEW.provider_id OR b.currency<>NEW.currency THEN
    RAISE EXCEPTION 'Commission snapshot does not match the booking and applicable supplier rule' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END; $$;
CREATE TRIGGER booking_commission_guard BEFORE INSERT OR UPDATE OR DELETE ON booking_commissions
FOR EACH ROW EXECUTE FUNCTION guard_booking_commission();

CREATE TABLE provider_settlements (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  provider_id uuid NOT NULL REFERENCES providers(id) ON DELETE RESTRICT,
  currency char(3) NOT NULL REFERENCES currencies(code) ON DELETE RESTRICT,
  period_start timestamptz NOT NULL,
  period_end timestamptz NOT NULL,
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','approved','closed','void')),
  approved_at timestamptz,
  closed_at timestamptz,
  financial_version bigint NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(id,provider_id,currency),
  UNIQUE(provider_id,currency,period_start),
  CHECK (period_end>period_start),
  CHECK ((status IN ('approved','closed'))=(approved_at IS NOT NULL)),
  CHECK ((status='closed')=(closed_at IS NOT NULL))
);
CREATE INDEX provider_settlements_status ON provider_settlements(provider_id,status,period_end);

CREATE TABLE settlement_items (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  settlement_id uuid NOT NULL,
  provider_id uuid NOT NULL,
  currency char(3) NOT NULL,
  booking_id uuid NOT NULL,
  entry_type text NOT NULL CHECK (entry_type IN ('capture','refund')),
  payment_attempt_id uuid NOT NULL,
  refund_id uuid REFERENCES refunds(id) ON DELETE RESTRICT,
  gross_minor bigint NOT NULL,
  commission_minor bigint NOT NULL,
  net_minor bigint GENERATED ALWAYS AS (gross_minor-commission_minor) STORED,
  occurred_at timestamptz NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (settlement_id,provider_id,currency) REFERENCES provider_settlements(id,provider_id,currency) ON DELETE RESTRICT,
  FOREIGN KEY (booking_id,provider_id,currency) REFERENCES bookings(id,provider_id,currency) ON DELETE RESTRICT,
  FOREIGN KEY (payment_attempt_id,currency) REFERENCES payment_attempts(id,currency) ON DELETE RESTRICT,
  CHECK ((entry_type='capture' AND refund_id IS NULL AND gross_minor>0 AND commission_minor BETWEEN 0 AND gross_minor)
      OR (entry_type='refund' AND refund_id IS NOT NULL AND gross_minor<0 AND commission_minor BETWEEN gross_minor AND 0))
);
CREATE UNIQUE INDEX settlement_items_capture_once ON settlement_items(payment_attempt_id) WHERE entry_type='capture';
CREATE UNIQUE INDEX settlement_items_refund_once ON settlement_items(refund_id) WHERE entry_type='refund';
CREATE INDEX settlement_items_settlement ON settlement_items(settlement_id);
CREATE INDEX settlement_items_provider ON settlement_items(provider_id,currency);
CREATE INDEX settlement_items_booking ON settlement_items(booking_id);
CREATE INDEX settlement_items_payment ON settlement_items(payment_attempt_id);
CREATE INDEX settlement_items_refund ON settlement_items(refund_id) WHERE refund_id IS NOT NULL;

CREATE FUNCTION guard_settlement_item() RETURNS trigger LANGUAGE plpgsql VOLATILE
SET search_path=travora,pg_temp AS $$
DECLARE s provider_settlements; p payment_attempts; r refunds; c booking_commissions;
  capture settlement_items; refunded numeric; returned_commission numeric; fee numeric; source_time timestamptz;
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Settlement ledger items are immutable and cannot be deleted' USING ERRCODE='23514'; END IF;
  UPDATE providers SET financial_version=financial_version+1 WHERE id=NEW.provider_id;
  UPDATE bookings SET updated_at=updated_at WHERE id=NEW.booking_id;
  UPDATE provider_settlements SET financial_version=financial_version+1 WHERE id=NEW.settlement_id RETURNING * INTO s;
  SELECT * INTO p FROM payment_attempts WHERE id=NEW.payment_attempt_id FOR SHARE;
  SELECT * INTO c FROM booking_commissions WHERE booking_id=NEW.booking_id;
  IF s.id IS NULL OR s.status<>'draft' OR s.provider_id<>NEW.provider_id OR s.currency<>NEW.currency
    OR p.id IS NULL OR p.status<>'succeeded' OR p.booking_id<>NEW.booking_id OR p.currency<>NEW.currency
    OR c.booking_id IS NULL OR c.provider_id<>NEW.provider_id OR c.currency<>NEW.currency THEN
    RAISE EXCEPTION 'Settlement item requires a draft supplier settlement, matching captured payment and commission snapshot' USING ERRCODE='23514';
  END IF;
  IF NEW.entry_type='capture' THEN
    IF NEW.refund_id IS NOT NULL THEN RAISE EXCEPTION 'Capture cannot reference a refund' USING ERRCODE='23514'; END IF;
    fee:=floor(p.amount_minor::numeric*c.rate_bps/10000);
    NEW.gross_minor:=p.amount_minor; NEW.commission_minor:=fee::bigint; source_time:=p.succeeded_at;
  ELSE
    SELECT * INTO r FROM refunds WHERE id=NEW.refund_id FOR SHARE;
    SELECT * INTO capture FROM settlement_items WHERE payment_attempt_id=p.id AND entry_type='capture';
    IF r.id IS NULL OR r.status<>'succeeded' OR r.payment_attempt_id<>p.id OR r.currency<>NEW.currency OR capture.id IS NULL THEN
      RAISE EXCEPTION 'Refund settlement requires a succeeded refund and its previously settled capture' USING ERRCODE='23514';
    END IF;
    SELECT COALESCE(-sum(gross_minor),0),COALESCE(-sum(commission_minor),0) INTO refunded,returned_commission
      FROM settlement_items WHERE payment_attempt_id=p.id AND entry_type='refund';
    fee:=capture.commission_minor-floor((p.amount_minor::numeric-refunded-r.amount_minor)*c.rate_bps/10000)-returned_commission;
    IF refunded+r.amount_minor>p.amount_minor OR fee<0 OR fee>r.amount_minor THEN
      RAISE EXCEPTION 'Refund ledger or commission reversal exceeds capture' USING ERRCODE='23514';
    END IF;
    NEW.gross_minor:=-r.amount_minor; NEW.commission_minor:=(-fee)::bigint; source_time:=r.succeeded_at;
  END IF;
  IF source_time<s.period_start OR source_time>=s.period_end THEN
    RAISE EXCEPTION 'Capture/refund event is outside settlement period' USING ERRCODE='23514';
  END IF;
  NEW.occurred_at:=source_time;
  RETURN NEW;
END; $$;
CREATE TRIGGER settlement_item_guard BEFORE INSERT OR UPDATE OR DELETE ON settlement_items FOR EACH ROW EXECUTE FUNCTION guard_settlement_item();

CREATE TABLE provider_payouts (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  settlement_id uuid NOT NULL,
  provider_id uuid NOT NULL,
  currency char(3) NOT NULL,
  payout_destination_id uuid NOT NULL,
  processor text NOT NULL CHECK (length(btrim(processor))>0),
  processor_payout_ref text,
  idempotency_key text NOT NULL CHECK (length(btrim(idempotency_key))>0),
  amount_minor bigint NOT NULL CHECK (amount_minor>0),
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','processing','succeeded','failed','cancelled')),
  succeeded_at timestamptz,
  failure_code text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (processor,idempotency_key),
  UNIQUE (processor,processor_payout_ref),
  FOREIGN KEY (settlement_id,provider_id,currency) REFERENCES provider_settlements(id,provider_id,currency) ON DELETE RESTRICT,
  FOREIGN KEY (payout_destination_id,provider_id,currency) REFERENCES provider_payout_destinations(id,provider_id,currency) ON DELETE RESTRICT,
  CHECK (status<>'succeeded' OR (succeeded_at IS NOT NULL AND processor_payout_ref IS NOT NULL AND length(btrim(processor_payout_ref))>0))
);
CREATE INDEX provider_payouts_settlement ON provider_payouts(settlement_id,status);
CREATE INDEX provider_payouts_provider ON provider_payouts(provider_id,currency,status);
CREATE INDEX provider_payouts_destination ON provider_payouts(payout_destination_id);

-- Available cash uses reserved refunds, even before their reversal is posted.
-- Late refunds after a completed payout create negative supplier debt; they do
-- not rewrite an irreversible historical payout or reject a customer refund.
CREATE VIEW provider_cash_positions AS
WITH cash AS (
  SELECT i.provider_id,i.currency,
    sum((p.amount_minor::numeric-COALESCE(r.reserved,0))-
        floor((p.amount_minor::numeric-COALESCE(r.reserved,0))*c.rate_bps/10000)) AS available_gross_net
  FROM settlement_items i JOIN payment_attempts p ON p.id=i.payment_attempt_id
  JOIN booking_commissions c ON c.booking_id=i.booking_id
  LEFT JOIN (SELECT payment_attempt_id,sum(amount_minor) AS reserved FROM refunds
    WHERE status IN ('requested','processing','succeeded') GROUP BY payment_attempt_id) r ON r.payment_attempt_id=p.id
  WHERE i.entry_type='capture' GROUP BY i.provider_id,i.currency
), paid AS (
  SELECT provider_id,currency,sum(amount_minor) AS reserved_payouts FROM provider_payouts
  WHERE status IN ('pending','processing','succeeded') GROUP BY provider_id,currency
)
SELECT COALESCE(c.provider_id,p.provider_id) AS provider_id,COALESCE(c.currency,p.currency) AS currency,
  COALESCE(c.available_gross_net,0)::bigint AS earned_after_reserved_refunds_minor,
  COALESCE(p.reserved_payouts,0)::bigint AS reserved_payouts_minor,
  (COALESCE(c.available_gross_net,0)-COALESCE(p.reserved_payouts,0))::bigint AS available_minor
FROM cash c FULL JOIN paid p USING(provider_id,currency);

CREATE VIEW provider_settlement_balances AS
SELECT s.id AS settlement_id,s.provider_id,s.currency,s.status,
  COALESCE(i.gross_minor,0)::bigint AS gross_minor,COALESCE(i.commission_minor,0)::bigint AS commission_minor,
  COALESCE(i.net_minor,0)::bigint AS net_minor,COALESCE(p.reserved_minor,0)::bigint AS reserved_payout_minor,
  (COALESCE(i.net_minor,0)-COALESCE(p.reserved_minor,0))::bigint AS available_minor
FROM provider_settlements s
LEFT JOIN (SELECT settlement_id,sum(gross_minor) AS gross_minor,sum(commission_minor) AS commission_minor,sum(net_minor) AS net_minor
  FROM settlement_items GROUP BY settlement_id) i ON i.settlement_id=s.id
LEFT JOIN (SELECT settlement_id,sum(amount_minor) AS reserved_minor FROM provider_payouts
  WHERE status IN ('pending','processing','succeeded') GROUP BY settlement_id) p ON p.settlement_id=s.id;

CREATE FUNCTION guard_provider_settlement() RETURNS trigger LANGUAGE plpgsql
SET search_path=travora,pg_temp AS $$
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Settlement history must be retained' USING ERRCODE='23514'; END IF;
  IF TG_OP='INSERT' THEN
    IF NEW.status<>'draft' OR NEW.approved_at IS NOT NULL OR NEW.closed_at IS NOT NULL THEN
      RAISE EXCEPTION 'Settlement must start as an unapproved draft' USING ERRCODE='23514';
    END IF;
  ELSE
    IF ROW(NEW.id,NEW.provider_id,NEW.currency,NEW.period_start,NEW.period_end,NEW.created_at)
       IS DISTINCT FROM ROW(OLD.id,OLD.provider_id,OLD.currency,OLD.period_start,OLD.period_end,OLD.created_at) THEN
      RAISE EXCEPTION 'Settlement financial identity and period are immutable' USING ERRCODE='23514';
    END IF;
    IF NEW.status<>OLD.status AND NOT ((OLD.status='draft' AND NEW.status IN ('approved','void')) OR
        (OLD.status='approved' AND NEW.status='closed')) THEN
      RAISE EXCEPTION 'Invalid settlement state transition' USING ERRCODE='23514';
    END IF;
    IF ROW(NEW.approved_at,NEW.closed_at) IS DISTINCT FROM ROW(OLD.approved_at,OLD.closed_at) THEN
      RAISE EXCEPTION 'Settlement timestamps are maintained by approval/close transitions' USING ERRCODE='23514';
    END IF;
    IF NEW.status='void' AND EXISTS(SELECT 1 FROM settlement_items WHERE settlement_id=NEW.id) THEN
      RAISE EXCEPTION 'An event-bearing settlement cannot be voided' USING ERRCODE='23514';
    END IF;
  END IF;
  IF NEW.status IN ('approved','closed') THEN NEW.approved_at:=COALESCE(NEW.approved_at,now()); END IF;
  IF NEW.status='closed' THEN NEW.closed_at:=COALESCE(NEW.closed_at,now()); END IF;
  RETURN NEW;
END; $$;
CREATE TRIGGER provider_settlement_guard BEFORE INSERT OR UPDATE OR DELETE ON provider_settlements
FOR EACH ROW EXECUTE FUNCTION guard_provider_settlement();
CREATE TRIGGER touch_updated_at BEFORE UPDATE ON provider_settlements FOR EACH ROW EXECUTE FUNCTION touch_updated_at();

CREATE FUNCTION guard_provider_payout() RETURNS trigger LANGUAGE plpgsql VOLATILE
SET search_path=travora,pg_temp AS $$
DECLARE s provider_settlements; d provider_payout_destinations; settlement_net numeric;
  reserved numeric; cash numeric;
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Payout history must be retained' USING ERRCODE='23514'; END IF;
  IF TG_OP='UPDATE' THEN
    IF ROW(NEW.id,NEW.settlement_id,NEW.provider_id,NEW.currency,NEW.payout_destination_id,NEW.processor,NEW.idempotency_key,NEW.amount_minor,NEW.created_at)
      IS DISTINCT FROM ROW(OLD.id,OLD.settlement_id,OLD.provider_id,OLD.currency,OLD.payout_destination_id,OLD.processor,OLD.idempotency_key,OLD.amount_minor,OLD.created_at) THEN
      RAISE EXCEPTION 'Payout financial identity and tokenized destination are immutable' USING ERRCODE='23514';
    END IF;
    IF OLD.processor_payout_ref IS NOT NULL AND NEW.processor_payout_ref IS DISTINCT FROM OLD.processor_payout_ref THEN
      RAISE EXCEPTION 'Assigned processor payout reference is immutable' USING ERRCODE='23514';
    END IF;
    IF NEW.status<>OLD.status AND NOT ((OLD.status='pending' AND NEW.status IN ('processing','succeeded','failed','cancelled')) OR
      (OLD.status='processing' AND NEW.status IN ('succeeded','failed','cancelled'))) THEN
      RAISE EXCEPTION 'Invalid terminal payout transition' USING ERRCODE='23514';
    END IF;
    IF OLD.status='succeeded' THEN
      IF NEW.succeeded_at IS DISTINCT FROM OLD.succeeded_at OR NEW.processor_payout_ref IS DISTINCT FROM OLD.processor_payout_ref THEN
        RAISE EXCEPTION 'Successful payout timestamp and reference are immutable' USING ERRCODE='23514';
      END IF;
      RETURN NEW;
    END IF;
  ELSE
    IF NEW.status<>'pending' OR NEW.succeeded_at IS NOT NULL THEN
      RAISE EXCEPTION 'A payout starts pending and is finalized by a verified processor workflow' USING ERRCODE='23514';
    END IF;
  END IF;
  IF NEW.status<>'succeeded' AND NEW.succeeded_at IS NOT NULL THEN
    RAISE EXCEPTION 'Only a succeeded payout has a success timestamp' USING ERRCODE='23514';
  END IF;
  UPDATE providers SET financial_version=financial_version+1 WHERE id=NEW.provider_id;
  UPDATE provider_settlements SET financial_version=financial_version+1 WHERE id=NEW.settlement_id RETURNING * INTO s;
  SELECT * INTO d FROM provider_payout_destinations WHERE id=NEW.payout_destination_id FOR SHARE;
  IF s.id IS NULL OR s.provider_id<>NEW.provider_id OR s.currency<>NEW.currency OR
    d.id IS NULL OR d.provider_id<>NEW.provider_id OR d.currency<>NEW.currency OR d.processor<>NEW.processor THEN
    RAISE EXCEPTION 'Payout must match supplier, currency, settlement and processor destination' USING ERRCODE='23514';
  END IF;
  -- The fixed amount reserves cash exactly once, at insertion. Later verified
  -- processor results must remain recordable after a refund creates debt or a
  -- destination is disabled; their reservation is unchanged, not new spending.
  IF TG_OP='INSERT' THEN
    IF s.status NOT IN ('approved','closed') OR d.status<>'active' THEN
      RAISE EXCEPTION 'Payout needs an approved settlement and active tokenized destination' USING ERRCODE='23514';
    END IF;
    SELECT COALESCE(sum(net_minor),0) INTO settlement_net FROM settlement_items WHERE settlement_id=NEW.settlement_id;
    SELECT COALESCE(sum(amount_minor),0) INTO reserved FROM provider_payouts
      WHERE settlement_id=NEW.settlement_id AND status IN ('pending','processing','succeeded') AND id<>NEW.id;
    SELECT COALESCE(available_minor,0) INTO cash FROM provider_cash_positions WHERE provider_id=NEW.provider_id AND currency=NEW.currency;
    cash:=COALESCE(cash,0);
    IF reserved+NEW.amount_minor>settlement_net OR NEW.amount_minor>cash THEN
      RAISE EXCEPTION 'Payout exceeds settled funds or supplier cash after reserved refunds and payouts' USING ERRCODE='23514';
    END IF;
  END IF;
  IF NEW.status='succeeded' THEN NEW.succeeded_at:=COALESCE(NEW.succeeded_at,now()); END IF;
  RETURN NEW;
END; $$;
CREATE TRIGGER provider_payout_guard BEFORE INSERT OR UPDATE OR DELETE ON provider_payouts FOR EACH ROW EXECUTE FUNCTION guard_provider_payout();
CREATE TRIGGER touch_updated_at BEFORE UPDATE ON provider_payouts FOR EACH ROW EXECUTE FUNCTION touch_updated_at();

CREATE FUNCTION lock_provider_refund_cash() RETURNS trigger LANGUAGE plpgsql VOLATILE
SET search_path=travora,pg_temp AS $$
DECLARE v_provider uuid;
BEGIN
  SELECT b.provider_id INTO v_provider FROM payment_attempts p JOIN bookings b ON b.id=p.booking_id
    WHERE p.id=NEW.payment_attempt_id;
  IF v_provider IS NOT NULL THEN UPDATE providers SET financial_version=financial_version+1 WHERE id=v_provider; END IF;
  RETURN NEW;
END; $$;
CREATE TRIGGER business_refund_cash_lock BEFORE INSERT OR UPDATE ON refunds FOR EACH ROW EXECUTE FUNCTION lock_provider_refund_cash();

CREATE VIEW provider_booking_earnings AS
SELECT b.id AS booking_id,b.provider_id,b.currency,c.rate_bps,
  COALESCE(x.captured_minor,0)::bigint AS captured_minor,COALESCE(x.refunded_minor,0)::bigint AS refunded_minor,
  COALESCE(x.commission_minor,0)::bigint AS commission_minor,
  (COALESCE(x.captured_minor,0)-COALESCE(x.refunded_minor,0)-COALESCE(x.commission_minor,0))::bigint AS net_provider_minor
FROM bookings b JOIN booking_commissions c ON c.booking_id=b.id
LEFT JOIN (
  SELECT p.booking_id,sum(p.amount_minor) AS captured_minor,sum(COALESCE(r.amount_minor,0)) AS refunded_minor,
    sum(floor((p.amount_minor::numeric-COALESCE(r.amount_minor,0))*bc.rate_bps/10000)) AS commission_minor
  FROM payment_attempts p JOIN booking_commissions bc ON bc.booking_id=p.booking_id
  LEFT JOIN (SELECT payment_attempt_id,sum(amount_minor) AS amount_minor FROM refunds WHERE status='succeeded' GROUP BY payment_attempt_id) r ON r.payment_attempt_id=p.id
  WHERE p.status='succeeded' GROUP BY p.booking_id
) x ON x.booking_id=b.id;

COMMENT ON TABLE booking_commissions IS 'Immutable percentage snapshot. Financial commission amounts are derived from successful captured net per payment, never arbitrary mutable balances. 10000 basis points = 100 percent.';
COMMENT ON TABLE settlement_items IS 'Append-only event ledger backed by real succeeded captures/refunds. Amounts and proportional commission reversals are populated by guards; each capture/refund is settled at most once. Late customer refunds become supplier debt without rewriting successful payouts.';
COMMENT ON VIEW provider_cash_positions IS 'Derived settled-capture cash less commissions, reserved requested/processing/succeeded refunds and pending/processing/succeeded payouts. Negative amounts represent supplier debt, not an editable balance.';

CREATE TABLE service_dispatches (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  booking_id uuid NOT NULL,
  provider_id uuid NOT NULL,
  driver_user_id uuid NOT NULL REFERENCES driver_profiles(user_id) ON DELETE RESTRICT,
  vehicle_id uuid,
  status text NOT NULL DEFAULT 'assigned' CHECK (status IN ('assigned','accepted','en_route','arrived','picked_up','completed','cancelled')),
  assigned_at timestamptz NOT NULL DEFAULT now(),
  accepted_at timestamptz,
  en_route_at timestamptz,
  arrived_at timestamptz,
  picked_up_at timestamptz,
  completed_at timestamptz,
  cancelled_at timestamptz,
  cancellation_reason text,
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(id,provider_id,driver_user_id),
  FOREIGN KEY (booking_id,provider_id) REFERENCES bookings(id,provider_id) ON DELETE RESTRICT,
  FOREIGN KEY (provider_id,driver_user_id) REFERENCES provider_memberships(provider_id,user_id) ON DELETE RESTRICT,
  FOREIGN KEY (vehicle_id,provider_id) REFERENCES provider_vehicles(id,provider_id) ON DELETE RESTRICT,
  CHECK (status='assigned' OR status='cancelled' OR accepted_at IS NOT NULL),
  CHECK (status NOT IN ('en_route','arrived','picked_up','completed') OR en_route_at IS NOT NULL),
  CHECK (status NOT IN ('arrived','picked_up','completed') OR arrived_at IS NOT NULL),
  CHECK (status NOT IN ('picked_up','completed') OR picked_up_at IS NOT NULL),
  CHECK (status<>'completed' OR completed_at IS NOT NULL),
  CHECK (status<>'cancelled' OR (cancelled_at IS NOT NULL AND cancellation_reason IS NOT NULL AND length(btrim(cancellation_reason))>0))
);
CREATE UNIQUE INDEX service_dispatches_active_driver ON service_dispatches(driver_user_id) WHERE status NOT IN ('completed','cancelled');
CREATE UNIQUE INDEX service_dispatches_active_booking ON service_dispatches(booking_id) WHERE status NOT IN ('completed','cancelled');
CREATE UNIQUE INDEX service_dispatches_active_vehicle ON service_dispatches(vehicle_id) WHERE vehicle_id IS NOT NULL AND status NOT IN ('completed','cancelled');
CREATE INDEX service_dispatches_provider ON service_dispatches(provider_id,status,assigned_at);
CREATE INDEX service_dispatches_provider_driver ON service_dispatches(provider_id,driver_user_id);
CREATE INDEX service_dispatches_driver ON service_dispatches(driver_user_id,assigned_at DESC);
CREATE INDEX service_dispatches_vehicle ON service_dispatches(vehicle_id) WHERE vehicle_id IS NOT NULL;

CREATE TABLE service_dispatch_events (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  dispatch_id uuid NOT NULL REFERENCES service_dispatches(id) ON DELETE RESTRICT,
  driver_user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  from_status text CHECK (from_status IS NULL OR from_status IN ('assigned','accepted','en_route','arrived','picked_up','completed','cancelled')),
  to_status text NOT NULL CHECK (to_status IN ('assigned','accepted','en_route','arrived','picked_up','completed','cancelled')),
  occurred_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX service_dispatch_events_dispatch ON service_dispatch_events(dispatch_id,occurred_at);
CREATE INDEX service_dispatch_events_driver ON service_dispatch_events(driver_user_id);

CREATE TABLE service_location_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  dispatch_id uuid NOT NULL,
  provider_id uuid NOT NULL,
  driver_user_id uuid NOT NULL,
  latitude numeric(9,6) NOT NULL CHECK (latitude BETWEEN -90 AND 90),
  longitude numeric(9,6) NOT NULL CHECK (longitude BETWEEN -180 AND 180),
  accuracy_m numeric(10,2) CHECK (accuracy_m IS NULL OR accuracy_m>=0),
  recorded_at timestamptz NOT NULL DEFAULT now(),
  received_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (dispatch_id,provider_id,driver_user_id) REFERENCES service_dispatches(id,provider_id,driver_user_id) ON DELETE RESTRICT,
  CHECK (recorded_at<=received_at+interval '5 minutes')
);
CREATE INDEX service_location_events_dispatch ON service_location_events(dispatch_id,recorded_at DESC);
CREATE INDEX service_location_events_driver ON service_location_events(driver_user_id,recorded_at DESC);
CREATE INDEX service_location_events_provider ON service_location_events(provider_id);

CREATE TABLE service_completion_proofs (
  dispatch_id uuid PRIMARY KEY,
  provider_id uuid NOT NULL,
  driver_user_id uuid NOT NULL,
  proof_kind text NOT NULL CHECK (proof_kind IN ('photo','signature','verified_otp')),
  media_asset_id uuid,
  recipient_otp_digest bytea,
  recipient_name_snapshot text,
  verified_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (dispatch_id,provider_id,driver_user_id) REFERENCES service_dispatches(id,provider_id,driver_user_id) ON DELETE RESTRICT,
  FOREIGN KEY (media_asset_id,driver_user_id) REFERENCES media_assets(id,owner_user_id) ON DELETE RESTRICT,
  CHECK ((proof_kind IN ('photo','signature') AND media_asset_id IS NOT NULL AND recipient_otp_digest IS NULL)
      OR (proof_kind='verified_otp' AND media_asset_id IS NULL AND octet_length(recipient_otp_digest)=32 AND recipient_otp_digest IS NOT NULL))
);
CREATE INDEX service_completion_proofs_provider ON service_completion_proofs(provider_id);
CREATE INDEX service_completion_proofs_driver ON service_completion_proofs(driver_user_id);
CREATE INDEX service_completion_proofs_asset ON service_completion_proofs(media_asset_id) WHERE media_asset_id IS NOT NULL;

CREATE FUNCTION guard_service_dispatch() RETURNS trigger LANGUAGE plpgsql VOLATILE
SET search_path=travora,pg_temp AS $$
DECLARE b bookings; m provider_memberships; d driver_profiles; v provider_vehicles;
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Dispatch history must be retained' USING ERRCODE='23514'; END IF;
  UPDATE bookings SET updated_at=updated_at WHERE id=NEW.booking_id RETURNING * INTO b;
  IF b.id IS NULL OR b.kind NOT IN ('TRANSPORT','DELIVERY') OR b.provider_id IS DISTINCT FROM NEW.provider_id THEN
    RAISE EXCEPTION 'Dispatch must match a transport/delivery booking supplier' USING ERRCODE='23514';
  END IF;
  IF TG_OP='INSERT' THEN
    IF NEW.status<>'assigned' OR b.status<>'confirmed' OR
      ROW(NEW.accepted_at,NEW.en_route_at,NEW.arrived_at,NEW.picked_up_at,NEW.completed_at,NEW.cancelled_at) IS DISTINCT FROM ROW(NULL::timestamptz,NULL::timestamptz,NULL::timestamptz,NULL::timestamptz,NULL::timestamptz,NULL::timestamptz) THEN
      RAISE EXCEPTION 'Dispatch starts assigned for a confirmed booking' USING ERRCODE='23514';
    END IF;
    IF EXISTS(SELECT 1 FROM service_dispatches WHERE booking_id=NEW.booking_id AND status='completed') THEN
      RAISE EXCEPTION 'A completed service cannot be dispatched again' USING ERRCODE='23514';
    END IF;
  ELSE
    IF ROW(NEW.id,NEW.booking_id,NEW.provider_id,NEW.assigned_at) IS DISTINCT FROM ROW(OLD.id,OLD.booking_id,OLD.provider_id,OLD.assigned_at) OR
      (OLD.status<>'assigned' AND ROW(NEW.driver_user_id,NEW.vehicle_id) IS DISTINCT FROM ROW(OLD.driver_user_id,OLD.vehicle_id)) THEN
      RAISE EXCEPTION 'Accepted dispatch identity and assignment are immutable' USING ERRCODE='23514';
    END IF;
    IF NEW.status<>OLD.status AND NOT ((OLD.status='assigned' AND NEW.status IN ('accepted','cancelled')) OR
      (OLD.status='accepted' AND NEW.status IN ('en_route','cancelled')) OR
      (OLD.status='en_route' AND NEW.status IN ('arrived','cancelled')) OR
      (OLD.status='arrived' AND NEW.status IN ('picked_up','cancelled')) OR
      (OLD.status='picked_up' AND NEW.status IN ('completed','cancelled'))) THEN
      RAISE EXCEPTION 'Invalid dispatch progression' USING ERRCODE='23514';
    END IF;
    IF ROW(NEW.accepted_at,NEW.en_route_at,NEW.arrived_at,NEW.picked_up_at,NEW.completed_at,NEW.cancelled_at)
      IS DISTINCT FROM ROW(OLD.accepted_at,OLD.en_route_at,OLD.arrived_at,OLD.picked_up_at,OLD.completed_at,OLD.cancelled_at) THEN
      RAISE EXCEPTION 'Dispatch milestone timestamps are maintained by transitions' USING ERRCODE='23514';
    END IF;
  END IF;
  IF NEW.status NOT IN ('cancelled','completed') OR (TG_OP='UPDATE' AND NEW.status='completed' AND OLD.status<>'completed') THEN
    IF b.status<>'confirmed' THEN RAISE EXCEPTION 'Active dispatch requires confirmed booking' USING ERRCODE='23514'; END IF;
    SELECT * INTO m FROM provider_memberships WHERE provider_id=NEW.provider_id AND user_id=NEW.driver_user_id FOR SHARE;
    SELECT * INTO d FROM driver_profiles WHERE user_id=NEW.driver_user_id FOR SHARE;
    IF m.provider_id IS NULL OR m.status<>'active' OR m.role_code<>'driver' OR d.id IS NULL OR d.status<>'active'
      OR d.license_expires_on<current_date OR NOT EXISTS(SELECT 1 FROM users WHERE id=NEW.driver_user_id AND status='active') THEN
      RAISE EXCEPTION 'Dispatch driver must be active in this supplier team and driver registry' USING ERRCODE='23514';
    END IF;
    IF (TG_OP='INSERT' OR NEW.driver_user_id IS DISTINCT FROM OLD.driver_user_id) AND d.availability<>'available' THEN
      RAISE EXCEPTION 'New assignments require an available driver' USING ERRCODE='23514';
    END IF;
    IF NEW.vehicle_id IS NOT NULL THEN
      SELECT * INTO v FROM provider_vehicles WHERE id=NEW.vehicle_id FOR SHARE;
      IF v.id IS NULL OR v.provider_id<>NEW.provider_id OR v.status<>'active' THEN
        RAISE EXCEPTION 'Dispatch vehicle must be active and owned by the same supplier' USING ERRCODE='23514';
      END IF;
      IF b.kind='TRANSPORT' AND EXISTS(SELECT 1 FROM transport_booking_details WHERE booking_id=b.id AND passenger_count>v.seats) THEN
        RAISE EXCEPTION 'Assigned vehicle cannot carry all booked passengers' USING ERRCODE='23514';
      END IF;
      IF b.kind='TRANSPORT' AND EXISTS(SELECT 1 FROM transport_booking_details WHERE booking_id=b.id AND luggage_count>v.luggage_capacity) THEN
        RAISE EXCEPTION 'Assigned vehicle cannot carry all booked luggage' USING ERRCODE='23514';
      END IF;
    END IF;
  END IF;
  IF TG_OP='UPDATE' AND NEW.status<>OLD.status THEN
    CASE NEW.status
      WHEN 'accepted' THEN NEW.accepted_at:=COALESCE(NEW.accepted_at,now());
      WHEN 'en_route' THEN NEW.en_route_at:=COALESCE(NEW.en_route_at,now());
      WHEN 'arrived' THEN NEW.arrived_at:=COALESCE(NEW.arrived_at,now());
      WHEN 'picked_up' THEN
        IF b.kind='DELIVERY' AND NOT EXISTS(SELECT 1 FROM food_delivery_details WHERE booking_id=b.id AND delivery_status='ready') THEN
          RAISE EXCEPTION 'Food must be ready before driver pickup' USING ERRCODE='23514';
        END IF;
        NEW.picked_up_at:=COALESCE(NEW.picked_up_at,now());
      WHEN 'completed' THEN
        IF NOT EXISTS(SELECT 1 FROM service_completion_proofs WHERE dispatch_id=NEW.id) THEN
          RAISE EXCEPTION 'Completion requires recipient proof verified by the application' USING ERRCODE='23514';
        END IF;
        NEW.completed_at:=COALESCE(NEW.completed_at,now());
      WHEN 'cancelled' THEN NEW.cancelled_at:=COALESCE(NEW.cancelled_at,now());
      ELSE NULL;
    END CASE;
  END IF;
  RETURN NEW;
END; $$;
CREATE TRIGGER service_dispatch_guard BEFORE INSERT OR UPDATE OR DELETE ON service_dispatches FOR EACH ROW EXECUTE FUNCTION guard_service_dispatch();
CREATE TRIGGER touch_updated_at BEFORE UPDATE ON service_dispatches FOR EACH ROW EXECUTE FUNCTION touch_updated_at();

CREATE FUNCTION log_service_dispatch() RETURNS trigger LANGUAGE plpgsql
SET search_path=travora,pg_temp AS $$
BEGIN
  IF TG_OP='INSERT' OR NEW.status IS DISTINCT FROM OLD.status THEN
    INSERT INTO service_dispatch_events(dispatch_id,driver_user_id,from_status,to_status)
      VALUES(NEW.id,NEW.driver_user_id,CASE WHEN TG_OP='UPDATE' THEN OLD.status END,NEW.status);
  END IF;
  IF EXISTS(SELECT 1 FROM food_delivery_details WHERE booking_id=NEW.booking_id) THEN
    IF NEW.status='picked_up' THEN UPDATE food_delivery_details SET delivery_status='picked_up' WHERE booking_id=NEW.booking_id;
    ELSIF NEW.status='completed' THEN UPDATE food_delivery_details SET delivery_status='delivered' WHERE booking_id=NEW.booking_id;
    END IF;
  END IF;
  RETURN NEW;
END; $$;
CREATE TRIGGER service_dispatch_history AFTER INSERT OR UPDATE ON service_dispatches FOR EACH ROW EXECUTE FUNCTION log_service_dispatch();

CREATE FUNCTION guard_dispatch_evidence() RETURNS trigger LANGUAGE plpgsql VOLATILE
SET search_path=travora,pg_temp AS $$
DECLARE d service_dispatches; a media_assets;
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Dispatch location, recipient proof and event history is append-only' USING ERRCODE='23514'; END IF;
  SELECT * INTO d FROM service_dispatches WHERE id=NEW.dispatch_id FOR UPDATE;
  IF TG_TABLE_NAME='service_dispatch_events' THEN
    IF pg_trigger_depth()<2 THEN RAISE EXCEPTION 'Dispatch history is generated by state transitions' USING ERRCODE='23514'; END IF;
    RETURN NEW;
  END IF;
  IF d.id IS NULL OR d.provider_id<>NEW.provider_id OR d.driver_user_id<>NEW.driver_user_id OR d.status IN ('completed','cancelled') THEN
    RAISE EXCEPTION 'Evidence must match an active supplier dispatch and assigned driver' USING ERRCODE='23514';
  END IF;
  IF TG_TABLE_NAME='service_completion_proofs' THEN
    IF d.status<>'picked_up' THEN RAISE EXCEPTION 'Recipient proof requires a picked-up service' USING ERRCODE='23514'; END IF;
    IF NEW.media_asset_id IS NOT NULL THEN
      SELECT * INTO a FROM media_assets WHERE id=NEW.media_asset_id FOR SHARE;
      IF a.id IS NULL OR a.owner_user_id IS DISTINCT FROM NEW.driver_user_id OR a.visibility<>'private' OR a.status<>'ready' THEN
        RAISE EXCEPTION 'Completion photo/signature must be private, ready and owned by the assigned driver' USING ERRCODE='23514';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END; $$;
CREATE TRIGGER service_dispatch_event_guard BEFORE INSERT OR UPDATE OR DELETE ON service_dispatch_events FOR EACH ROW EXECUTE FUNCTION guard_dispatch_evidence();
CREATE TRIGGER service_location_event_guard BEFORE INSERT OR UPDATE OR DELETE ON service_location_events FOR EACH ROW EXECUTE FUNCTION guard_dispatch_evidence();
CREATE TRIGGER service_completion_proof_guard BEFORE INSERT OR UPDATE OR DELETE ON service_completion_proofs FOR EACH ROW EXECUTE FUNCTION guard_dispatch_evidence();

CREATE FUNCTION sync_booking_dispatch_cancellation() RETURNS trigger LANGUAGE plpgsql
SET search_path=travora,pg_temp AS $$
BEGIN
  IF NEW.status IN ('cancelled','expired') AND NEW.status IS DISTINCT FROM OLD.status THEN
    UPDATE service_dispatches SET status='cancelled',cancellation_reason='Parent booking cancelled or expired'
      WHERE booking_id=NEW.id AND status NOT IN ('completed','cancelled');
  END IF;
  RETURN NEW;
END; $$;
CREATE TRIGGER booking_dispatch_cancellation AFTER UPDATE ON bookings FOR EACH ROW EXECUTE FUNCTION sync_booking_dispatch_cancellation();

CREATE FUNCTION assert_booking_dispatch_completion() RETURNS trigger LANGUAGE plpgsql
SET search_path=travora,pg_temp AS $$
DECLARE b bookings;
BEGIN
  SELECT * INTO b FROM bookings WHERE id=NEW.id;
  IF b.status='completed' AND b.provider_id IS NOT NULL AND b.kind IN ('TRANSPORT','DELIVERY') AND NOT EXISTS(
    SELECT 1 FROM service_dispatches d JOIN service_completion_proofs p ON p.dispatch_id=d.id
    WHERE d.booking_id=b.id AND d.status='completed') THEN
    RAISE EXCEPTION 'Supplier transport/delivery completes only after dispatch and recipient proof' USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END; $$;
CREATE CONSTRAINT TRIGGER booking_dispatch_complete AFTER INSERT OR UPDATE ON bookings
DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION assert_booking_dispatch_completion();

CREATE VIEW driver_dispatch_availability AS
SELECT d.id AS driver_profile_id,d.user_id,d.status,
  CASE WHEN d.status<>'active' OR d.availability='offline' THEN 'offline'
    WHEN EXISTS(SELECT 1 FROM service_dispatches s WHERE s.driver_user_id=d.user_id AND s.status NOT IN ('completed','cancelled')) THEN 'busy'
    ELSE d.availability END AS availability
FROM driver_profiles d;

COMMENT ON TABLE service_completion_proofs IS 'Recipient completion evidence metadata, not identity assurance by the database. Application verifies OTP/photo/signature, caller authorization and uploads; only a digest or private owner-scoped media FK is stored.';
COMMENT ON COLUMN service_completion_proofs.recipient_otp_digest IS 'Server-keyed HMAC-SHA-256 evidence of an already verified recipient challenge. Never store a raw short OTP or use this row alone to authenticate it. API enforces expiry, attempts, binding to the dispatch and one-time consumption.';
COMMENT ON TABLE service_location_events IS 'Append-only driver dispatch coordinates. API must verify the caller is the assigned driver, require consent, and apply retention/privacy rules. FKs are scope integrity, not RLS.';


-- Saved services extend the same constrained favorites model.
ALTER TABLE favorites
 ADD COLUMN restaurant_id uuid REFERENCES restaurants(id) ON DELETE CASCADE,
 ADD COLUMN guide_id uuid REFERENCES guide_profiles(id) ON DELETE CASCADE;
ALTER TABLE favorites DROP CONSTRAINT favorite_exactly_one_target;
ALTER TABLE favorites ADD CONSTRAINT favorite_exactly_one_target CHECK (
 num_nonnulls(destination_id,hotel_id,activity_id,transport_service_id,restaurant_id,guide_id)=1
);
CREATE UNIQUE INDEX favorites_restaurant_unique ON favorites(user_id,restaurant_id) WHERE restaurant_id IS NOT NULL;
CREATE UNIQUE INDEX favorites_guide_unique ON favorites(user_id,guide_id) WHERE guide_id IS NOT NULL;
COMMENT ON COLUMN favorites.restaurant_id IS 'A saved restaurant catalog entry; exactly one saved-service target per row.';
COMMENT ON COLUMN favorites.guide_id IS 'A saved guide profile; not a reservation or availability hold.';


