-- Install the shared updated_at trigger for modules created after 50_invariants.sql.
DO $$
DECLARE r record;
BEGIN
 FOR r IN SELECT c.table_name FROM information_schema.columns c WHERE c.table_schema='travora' AND c.column_name='updated_at' AND EXISTS (SELECT 1 FROM information_schema.tables t WHERE t.table_schema=c.table_schema AND t.table_name=c.table_name AND t.table_type='BASE TABLE') LOOP
  IF NOT EXISTS (SELECT 1 FROM pg_trigger tr JOIN pg_class cl ON cl.oid=tr.tgrelid JOIN pg_namespace ns ON ns.oid=cl.relnamespace WHERE ns.nspname='travora' AND cl.relname=r.table_name AND tr.tgname='touch_updated_at') THEN
   EXECUTE format('CREATE TRIGGER touch_updated_at BEFORE UPDATE ON travora.%I FOR EACH ROW EXECUTE FUNCTION travora.touch_updated_at()',r.table_name);
  END IF;
 END LOOP;
END $$;


